import { GoogleGenAI } from '@google/genai';
import { LineContext, findLinesWithForeignChars, mergeFixedLines, replacePromptVariables } from './utils/textHelpers';
import { quotaManager } from './utils/quotaManager';
import { MODEL_CONFIGS, GLOSSARY_ANALYSIS_PROMPT } from './constants';
import { StoryInfo, FileItem } from './types';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("Không tìm thấy API Key. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Optimize Dictionary:
 * 1. Parse dictionary lines.
 * 2. Deduplicate keys.
 * 3. Only keep terms that appear in content.
 */
const optimizeDictionary = (dictionary: string, content: string): string => {
  if (!content || !dictionary) return '';

  const lines = dictionary.split('\n');
  const uniqueMap = new Map<string, string>();

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; 

    const key = trimmed.substring(0, eqIndex).trim();
    if (key) {
        uniqueMap.set(key, trimmed);
    }
  }

  const usedLines: string[] = [];
  for (const [key, line] of uniqueMap.entries()) {
      if (content.includes(key)) {
          usedLines.push(line);
      }
  }

  return usedLines.join('\n');
};

const formatError = (error: any, modelId: string): string => {
    const msg = (error.message || error.toString()).toLowerCase();
    if (msg.includes('quota')) return `Model ${modelId} hết dung lượng.`;
    if (msg.includes('429')) return `Model ${modelId} quá tải.`;
    if (msg.includes('safety')) return `Bị chặn bởi bộ lọc an toàn.`;
    return error.message || error.toString();
};

const handleErrorQuota = (error: any, modelId: string) => {
    const msg = (error.message || error.toString()).toLowerCase();
    if (msg.includes('quota') || msg.includes('exhausted')) {
        quotaManager.markAsDepleted(modelId);
    } else if (error.status === 429 || msg.includes('429')) {
        quotaManager.recordRateLimit(modelId);
    }
};

export const testModelConnection = async (modelId: string): Promise<{ success: boolean; message: string }> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: modelId,
            contents: "Hi",
            config: { maxOutputTokens: 10, thinkingConfig: { thinkingBudget: 0 } }
        });
        return { success: !!response.text, message: response.text ? "Kết nối thành công!" : "Không có phản hồi." };
    } catch (error: any) {
        return { success: false, message: formatError(error, modelId) };
    }
};

export const optimizePrompt = async (promptTemplate: string, storyInfo: StoryInfo): Promise<string> => {
  const ai = getAiClient();
  const modelsToTry = ['gemini-3-pro-preview', 'gemini-3-flash-preview'];
  const filledTemplate = replacePromptVariables(promptTemplate, storyInfo);

  const instruction = `Bạn là chuyên gia Prompt Engineering. Hãy tối ưu prompt dịch truyện cho bộ truyện này. Loại bỏ các phần thừa không liên quan đến thể loại.`;
  const userContent = `[TRUYỆN]: ${storyInfo.title}\n[THỂ LOẠI]: ${storyInfo.genres.join(', ')}\n[PROMPT GỐC]:\n${filledTemplate}`;

  for (const modelId of modelsToTry) {
      if (!quotaManager.isModelAvailable(modelId)) continue;
      try {
        const response = await ai.models.generateContent({
          model: modelId,
          contents: userContent,
          config: { 
            systemInstruction: instruction, 
            temperature: 0.7,
            thinkingConfig: { thinkingBudget: 1024 } 
          },
        });
        if (response.text) {
          quotaManager.recordRequest(modelId);
          return response.text.trim();
        }
      } catch (error: any) {
         handleErrorQuota(error, modelId);
      }
  }
  return filledTemplate; 
};

export const analyzeStoryContext = async (files: FileItem[], storyInfo: StoryInfo, promptTemplate: string = ""): Promise<string> => {
    const ai = getAiClient();
    const modelsToTry = ['gemini-3-pro-preview', 'gemini-3-flash-preview'];

    let contextContent = files.slice(0, 5).map(f => f.content).join('\n').substring(0, 50000);
    const userPrompt = `Dựa trên nội dung sau, hãy lập từ điển thuật ngữ và quan hệ nhân vật.\n${contextContent}`;

    for (const modelId of modelsToTry) {
        if (!quotaManager.isModelAvailable(modelId)) continue;
        try {
            const response = await ai.models.generateContent({
                model: modelId,
                contents: userPrompt,
                config: {
                    systemInstruction: GLOSSARY_ANALYSIS_PROMPT,
                    temperature: 0.2,
                    thinkingConfig: { thinkingBudget: 4096 }
                },
            });
            if (response.text) {
                quotaManager.recordRequest(modelId);
                return response.text.trim();
            }
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    throw new Error("Không thể phân tích ngữ cảnh.");
};

let translationRequestCount = 0;

const selectModel = (allowedModelIds: string[]) => {
  const currentConfigs = quotaManager.getConfigs();
  const priorityTier = ['gemini-3-pro-preview', 'gemini-3-flash-preview'];
  const available = currentConfigs
    .filter(c => allowedModelIds.includes(c.id) && quotaManager.isModelAvailable(c.id))
    .sort((a, b) => {
        const aPri = priorityTier.indexOf(a.id);
        const bPri = priorityTier.indexOf(b.id);
        return (aPri === -1 ? 99 : aPri) - (bPri === -1 ? 99 : bPri);
    });

  if (available.length === 0) return [];
  translationRequestCount++;
  return available.map(m => m.id);
}

export const translateBatch = async (
    files: { id: string, content: string }[],
    userPrompt: string,
    dictionary: string,
    globalContext: string,
    allowedModelIds: string[],
    previousBatchContext: string = ""
): Promise<{ results: Map<string, string>, model: string }> => {
    const ai = getAiClient();
    const combinedContent = files.map(f => f.content).join('\n');
    const relevantDictionary = optimizeDictionary(dictionary, combinedContent);

    let inputContent = "";
    for (const file of files) {
        inputContent += `\n[[[FILE: ${file.id}]]]\n${file.content}\n[[[END: ${file.id}]]]\n`;
    }

    const systemInstruction = `Bạn là dịch giả chuyên nghiệp. Dịch nhiều chương cùng lúc. Giữ nguyên các tag [[[FILE: ID]]] và [[[END: ID]]].`;
    const fullPrompt = `[GLOSSARY]\n${relevantDictionary}\n\n[CONTEXT]\n${globalContext}\n${previousBatchContext}\n\n[INSTRUCTION]\n${userPrompt}\n\n[INPUT]\n${inputContent}`;

    const attempts = selectModel(allowedModelIds);
    if (attempts.length === 0) throw new Error("Hết quota.");

    for (const modelId of attempts) {
        try {
            const isGemini3 = modelId.includes('gemini-3');
            const response = await ai.models.generateContent({
                model: modelId,
                contents: fullPrompt,
                config: {
                    systemInstruction: systemInstruction,
                    temperature: 0.3,
                    maxOutputTokens: 60000,
                    ...(isGemini3 ? { thinkingConfig: { thinkingBudget: 8192 } } : {})
                },
            });

            if (!response.text) throw new Error("Phản hồi trống");

            const rawText = response.text;
            const results = new Map<string, string>();
            let parseSuccessCount = 0;

            for (const file of files) {
                const idPattern = file.id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const regex = new RegExp(`\\[\\[\\[FILE:\\s*${idPattern}\\s*\\]\\]\\]([\\s\\S]*?)\\[\\[\\[END:\\s*${idPattern}\\s*\\]\\]\\]`, 'i');
                const match = rawText.match(regex);
                if (match && match[1]) {
                    results.set(file.id, match[1].trim());
                    parseSuccessCount++;
                }
            }

            if (parseSuccessCount === 0) throw new Error("Lỗi parse tag.");
            quotaManager.recordRequest(modelId);
            return { results, model: modelId };
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    throw new Error("Dịch thất bại trên mọi model.");
};

export const translateText = async (
  content: string,
  userPrompt: string,
  dictionary: string,
  globalContext: string = "",
  previousChapterContext: string = "",
  allowedModelIds: string[] = [] 
): Promise<{ text: string, model: string }> => {
  const ai = getAiClient();
  const relevantDictionary = optimizeDictionary(dictionary, content);
  const systemInstruction = `Dịch từ tiếng Trung sang tiếng Việt mượt mà.`;
  const fullPrompt = `[GLOSSARY]\n${relevantDictionary}\n\n${globalContext}\n${previousChapterContext}\n\n[INSTRUCTION]\n${userPrompt}\n\n[INPUT]\n${content}`;

  const attempts = selectModel(allowedModelIds);
  for (const modelId of attempts) {
    try {
      const isGemini3 = modelId.includes('gemini-3');
      const response = await ai.models.generateContent({
        model: modelId,
        contents: fullPrompt,
        config: { 
            systemInstruction, 
            temperature: 0.3, 
            maxOutputTokens: 60000,
            ...(isGemini3 ? { thinkingConfig: { thinkingBudget: 4096 } } : {})
        },
      });

      if (response.text) {
        quotaManager.recordRequest(modelId);
        return { text: response.text.trim(), model: modelId };
      }
    } catch (error: any) {
        handleErrorQuota(error, modelId);
    }
  }
  throw new Error("Dịch thất bại.");
};

export const repairTranslations = async (
  badLines: LineContext[],
  dictionary: string,
  useHighQuality: boolean = false
): Promise<{ index: number; text: string }[]> => {
  if (badLines.length === 0) return [];
  const ai = getAiClient();
  const linesToFixStr = badLines.map((l, i) => `LINE_${i}: ${l.originalLine}`).join('\n');
  const systemInstruction = `Bạn là công cụ sửa lỗi. Dịch các dòng sau sang tiếng Việt sạch sẽ. Trả về JSON Array.`;
  const prompt = `[DICTIONARY]\n${dictionary}\n[TASKS]\n${linesToFixStr}`;

  const modelId = useHighQuality ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
  if (!quotaManager.isModelAvailable(modelId)) return [];

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: 'application/json',
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 1024 }
      },
    });

    if (response.text) {
      quotaManager.recordRequest(modelId);
      const fixedStrings = JSON.parse(response.text);
      if (Array.isArray(fixedStrings)) {
          return badLines.map((item, idx) => ({ index: item.index, text: fixedStrings[idx] }));
      }
    }
  } catch (error: any) {
      handleErrorQuota(error, modelId);
  }
  return [];
};

