import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { 
  FileItem, 
  FileStatus, 
  StoryInfo, 
  ProcessingStats 
} from './types';
import { 
  DEFAULT_PROMPT, 
  DEFAULT_DICTIONARY, 
  MODEL_CONFIGS,
  AVAILABLE_LANGUAGES,
  AVAILABLE_GENRES,
  AVAILABLE_PERSONALITIES,
  AVAILABLE_SETTINGS,
  AVAILABLE_FLOWS
} from './constants';
import { 
  unzipFiles, 
  splitContentByRegex, 
  splitContentByLength, 
  generateEpub, 
  downloadTextFile,
  createMergedFile,
  parseEpub,
  downloadRawAsZip
} from './utils/fileHelpers';
import { translateBatch, repairTranslations, analyzeStoryContext } from './geminiService';
import { quotaManager } from './utils/quotaManager';
import { saveToStorage, loadFromStorage, clearDatabase } from './utils/storage';

const App: React.FC = () => {
  // --- State ---
  const [files, setFiles] = useState<FileItem[]>([]);
  const [storyInfo, setStoryInfo] = useState<StoryInfo>({
    title: '',
    author: '',
    languages: [AVAILABLE_LANGUAGES[0]],
    genres: [],
    mcPersonality: [],
    worldSetting: [],
    sectFlow: []
  });
  const [prompt, setPrompt] = useState(DEFAULT_PROMPT);
  const [dictionary, setDictionary] = useState(DEFAULT_DICTIONARY);
  const [isProcessing, setIsProcessing] = useState(false);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [tick, setTick] = useState(0);
  const [globalContext, setGlobalContext] = useState('');
  const [selectedModels, setSelectedModels] = useState<string[]>(MODEL_CONFIGS.map(m => m.id));

  const processingRef = useRef(false);

  // --- Persistence ---
  useEffect(() => {
    const loadData = async () => {
      const savedFiles = await loadFromStorage('files');
      if (savedFiles) setFiles(savedFiles);

      const savedInfo = await loadFromStorage('storyInfo');
      if (savedInfo) setStoryInfo(savedInfo);

      const savedPrompt = await loadFromStorage('prompt');
      if (savedPrompt) setPrompt(savedPrompt);

      const savedDict = await loadFromStorage('dictionary');
      if (savedDict) setDictionary(savedDict);

      const savedModels = await loadFromStorage('selectedModels');
      if (savedModels) setSelectedModels(savedModels);
    };
    loadData();
  }, []);

  useEffect(() => {
    saveToStorage('files', files);
    saveToStorage('storyInfo', storyInfo);
    saveToStorage('prompt', prompt);
    saveToStorage('dictionary', dictionary);
    saveToStorage('selectedModels', selectedModels);
  }, [files, storyInfo, prompt, dictionary, selectedModels]);

  // --- Stats & Visuals ---
  const stats = useMemo<ProcessingStats>(() => {
    const total = files.length;
    const completed = files.filter(f => f.status === FileStatus.COMPLETED).length;
    const failed = files.filter(f => f.status === FileStatus.ERROR).length;
    const processing = files.filter(f => f.status === FileStatus.PROCESSING || f.status === FileStatus.REPAIRING).length;
    return {
      total,
      completed,
      failed,
      pending: total - completed - failed - processing,
      processing
    };
  }, [files]);

  useEffect(() => {
    let interval: any;
    if (isProcessing) {
      interval = setInterval(() => setTick(t => t + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [isProcessing]);

  /* Fix: Define averageSpeed with proper dependencies */
  const averageSpeed = useMemo(() => {
    if (!startTime || stats.completed === 0) return 0;
    const elapsedMinutes = (Date.now() - startTime) / 60000;
    return Math.round(stats.completed / elapsedMinutes) || 0;
  }, [stats.completed, startTime, tick]);

  // --- Handlers ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList) return;

    const newFiles: FileItem[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      if (f.name.endsWith('.zip')) {
        const unzipped = await unzipFiles(f);
        newFiles.push(...unzipped);
      } else if (f.name.endsWith('.epub')) {
        const result = await parseEpub(f);
        newFiles.push(...result.files);
        if (result.info) setStoryInfo(prev => ({ ...prev, ...result.info }));
      } else if (f.name.endsWith('.txt')) {
        const content = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = (re) => resolve(re.target?.result as string);
          reader.readAsText(f);
        });
        newFiles.push({
          id: crypto.randomUUID(),
          name: f.name,
          content,
          translatedContent: null,
          status: FileStatus.IDLE,
          retryCount: 0,
          originalCharCount: content.length,
          remainingRawCharCount: 0
        });
      }
    }
    setFiles(prev => [...prev, ...newFiles]);
  };

  const startProcessing = async () => {
    if (isProcessing || files.length === 0) return;
    setIsProcessing(true);
    setStartTime(Date.now());
    processingRef.current = true;

    // Optional: Analysis first if context is empty
    if (!globalContext && files.length > 0) {
      try {
        const context = await analyzeStoryContext(files, storyInfo, prompt);
        setGlobalContext(context);
      } catch (e) {
        console.warn("Analysis failed, proceeding anyway.");
      }
    }

    const batchSize = 3;
    let pendingFiles = files.filter(f => f.status === FileStatus.IDLE || f.status === FileStatus.ERROR);

    while (processingRef.current && pendingFiles.length > 0) {
      const currentBatch = pendingFiles.slice(0, batchSize);

      // Update status to processing
      setFiles(prev => prev.map(f => 
        currentBatch.some(cb => cb.id === f.id) ? { ...f, status: FileStatus.PROCESSING } : f
      ));

      try {
        const { results, model } = await translateBatch(
          currentBatch.map(f => ({ id: f.id, content: f.content })),
          prompt,
          dictionary,
          globalContext,
          selectedModels
        );

        setFiles(prev => prev.map(f => {
          const translated = results.get(f.id);
          if (translated) {
            return { ...f, status: FileStatus.COMPLETED, translatedContent: translated, usedModel: model };
          }
          return f;
        }));
      } catch (error: any) {
        console.error("Batch failed", error);
        setFiles(prev => prev.map(f => 
          currentBatch.some(cb => cb.id === f.id) ? { ...f, status: FileStatus.ERROR, errorMessage: error.message } : f
        ));
      }

      pendingFiles = pendingFiles.slice(batchSize);
    }

    setIsProcessing(false);
    processingRef.current = false;
  };

  const stopProcessing = () => {
    processingRef.current = false;
    setIsProcessing(false);
  };

  const clearAll = async () => {
    if (window.confirm("Bạn có chắc chắn muốn xóa toàn bộ dữ liệu?")) {
      await clearDatabase();
      setFiles([]);
      setGlobalContext('');
      setStartTime(null);
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', maxWidth: '1200px', margin: '0 auto' }}>
      <h1>Bàn Làm Việc Dịch Thuật</h1>

      {/* Dashboard Stats */}
      <div style={{ display: 'flex', gap: '20px', background: '#f0f4f8', padding: '15px', borderRadius: '8px', marginBottom: '20px' }}>
        <div>Tổng: <strong>{stats.total}</strong></div>
        <div style={{ color: 'green' }}>Hoàn thành: <strong>{stats.completed}</strong></div>
        <div style={{ color: 'red' }}>Lỗi: <strong>{stats.failed}</strong></div>
        <div style={{ color: 'blue' }}>Đang chạy: <strong>{stats.processing}</strong></div>
        <div>Tốc độ: <strong>{averageSpeed} ch/phút</strong></div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 300px', gap: '20px' }}>
        {/* Main Section */}
        <section>
          <div style={{ marginBottom: '15px', display: 'flex', gap: '10px' }}>
            <input type="file" multiple accept=".txt,.zip,.epub" onChange={handleFileUpload} />
            <button onClick={startProcessing} disabled={isProcessing || files.length === 0} style={{ background: 'green', color: 'white' }}>
              {isProcessing ? 'Đang dịch...' : 'Bắt đầu dịch'}
            </button>
            <button onClick={stopProcessing} disabled={!isProcessing} style={{ background: 'orange' }}>Dừng</button>
            <button onClick={clearAll} style={{ background: 'red', color: 'white' }}>Xóa hết</button>
          </div>

          <div style={{ border: '1px solid #ccc', borderRadius: '4px', height: '500px', overflowY: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead style={{ position: 'sticky', top: 0, background: '#eee' }}>
                <tr>
                  <th style={{ textAlign: 'left', padding: '8px' }}>Tên file</th>
                  <th style={{ textAlign: 'center', padding: '8px' }}>Trạng thái</th>
                  <th style={{ textAlign: 'right', padding: '8px' }}>Model</th>
                </tr>
              </thead>
              <tbody>
                {files.map(file => (
                  <tr key={file.id} style={{ borderBottom: '1px solid #eee' }}>
                    <td style={{ padding: '8px' }}>{file.name}</td>
                    <td style={{ padding: '8px', textAlign: 'center' }}>
                      <span style={{ 
                        padding: '2px 6px', 
                        borderRadius: '4px', 
                        fontSize: '12px',
                        background: file.status === FileStatus.COMPLETED ? '#e6fffa' : file.status === FileStatus.ERROR ? '#fff5f5' : '#f7fafc',
                        color: file.status === FileStatus.COMPLETED ? '#2c7a7b' : file.status === FileStatus.ERROR ? '#c53030' : '#4a5568'
                      }}>
                        {file.status}
                      </span>
                    </td>
                    <td style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: '#666' }}>
                      {file.usedModel || '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        {/* Sidebar Info */}
        <aside style={{ background: '#f9f9f9', padding: '15px', borderRadius: '8px', border: '1px solid #eee' }}>
          <h3>Thông tin truyện</h3>
          <input 
            placeholder="Tên truyện" 
            value={storyInfo.title} 
            onChange={e => setStoryInfo({...storyInfo, title: e.target.value})} 
            style={{ width: '100%', marginBottom: '10px', padding: '5px' }}
          />
          <input 
            placeholder="Tác giả" 
            value={storyInfo.author} 
            onChange={e => setStoryInfo({...storyInfo, author: e.target.value})} 
            style={{ width: '100%', marginBottom: '10px', padding: '5px' }}
          />

          <div style={{ marginTop: '20px' }}>
            <button onClick={() => downloadTextFile(`${storyInfo.title || 'truyen'}_merged.txt`, createMergedFile(files))} style={{ width: '100%', marginBottom: '10px' }}>
              Tải TXT Gộp
            </button>
            <button onClick={async () => {
              const blob = await generateEpub(files, storyInfo, null);
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `${storyInfo.title || 'truyen'}.epub`;
              a.click();
            }} style={{ width: '100%' }}>
              Tải EPUB
            </button>
          </div>

          <div style={{ marginTop: '30px', fontSize: '12px' }}>
            <h4>Cấu hình Model</h4>
            {MODEL_CONFIGS.map(m => (
              <label key={m.id} style={{ display: 'block', marginBottom: '5px' }}>
                <input 
                  type="checkbox" 
                  checked={selectedModels.includes(m.id)} 
                  onChange={(e) => {
                    if (e.target.checked) setSelectedModels([...selectedModels, m.id]);
                    else setSelectedModels(selectedModels.filter(id => id !== m.id));
                  }}
                /> {m.name}
              </label>
            ))}
          </div>
        </aside>
      </div>
    </div>
  );
};

