// Danh sách các Proxy hỗ trợ vượt rào CORS
const PROXY_LIST = [
    "https://corsproxy.io/?",
    "https://api.allorigins.win/raw?url="
];

/**
 * Lấy nội dung văn bản từ URL với cơ chế thử lại qua nhiều Proxy
 */
export const fetchContentFromUrl = async (url: string): Promise<{ title: string, content: string }> => {
    let lastError = "";

    for (const proxy of PROXY_LIST) {
        try {
            const finalUrl = `${proxy}${encodeURIComponent(url)}`;
            const response = await fetch(finalUrl);

            if (!response.ok) {
                lastError = `Proxy ${proxy} trả về lỗi ${response.status}`;
                continue;
            }

            // Xử lý Encoding: Truyện Trung Quốc thường dùng GBK
            // Chúng ta lấy ArrayBuffer để có thể decode chính xác nếu cần
            const buffer = await response.arrayBuffer();
            const decoder = new TextDecoder('utf-8'); // Mặc định thử utf-8
            let html = decoder.decode(buffer);

            // Kiểm tra nếu là GBK (thường thấy trong meta tag)
            if (html.toLowerCase().includes('charset=gbk') || html.toLowerCase().includes('charset=gb2312')) {
                const gbkDecoder = new TextDecoder('gbk');
                html = gbkDecoder.decode(buffer);
            }

            const parser = new DOMParser();
            const doc = parser.parseFromString(html, 'text/html');

            // 1. Trích xuất Tiêu đề thông minh
            let title = doc.title || "Chương không tên";
            const h1 = doc.querySelector('h1');
            if (h1 && h1.innerText.trim().length < 100) {
                title = h1.innerText.trim();
            }

            // 2. Dọn dẹp DOM (Xóa rác web lậu)
            const selectorsToRemove = [
                'script', 'style', 'iframe', 'ads', '.ads', '#ads', 
                '#footer', '.footer', '.header', 'nav', '.nav',
                'button', '.recommend', '.social-share', '.bottom-ad'
            ];
            selectorsToRemove.forEach(s => doc.querySelectorAll(s).forEach(el => el.remove()));

            // 3. Thuật toán tìm Content (Dựa trên mật độ thẻ P và text)
            const containers = Array.from(doc.querySelectorAll('div, article, section, td'));
            let bestContainer: HTMLElement | null = null;
            let maxScore = 0;

            containers.forEach(container => {
                const text = container.innerText.trim();
                const pCount = container.querySelectorAll('p').length;
                const score = text.length + (pCount * 50);

                // Tránh lấy nhầm thẻ body hoặc html quá rộng
                if (container.tagName !== 'BODY' && container.tagName !== 'HTML' && score > maxScore) {
                    maxScore = score;
                    bestContainer = container as HTMLElement;
                }
            });

            const target = bestContainer || doc.body;

            // Lấy text và xử lý xuống dòng
            let cleanText = "";
            const paragraphs = target.querySelectorAll('p');
            if (paragraphs.length > 3) {
                cleanText = Array.from(paragraphs)
                    .map(p => p.innerText.trim())
                    .filter(t => t.length > 5)
                    .join('\n\n');
            } else {
                // Fallback nếu web không dùng thẻ P cho nội dung
                cleanText = target.innerText
                    .replace(/\t/g, '')
                    .replace(/ +/g, ' ')
                    .replace(/\n\s*\n/g, '\n\n')
                    .trim();
            }

            // Kiểm tra nếu nội dung quá ngắn (có thể do bóc tách lỗi)
            if (cleanText.length < 100) {
                lastError = "Nội dung bóc tách được quá ngắn, có thể trang web này có bảo mật cao.";
                continue;
            }

            return { title, content: cleanText };
        } catch (e: any) {
            lastError = e.message;
        }
    }

    throw new Error(lastError || "Tất cả proxy đều không thể truy cập trang web này.");
};

export const unzipFiles = async (file: File): Promise<FileItem[]> => {
  const zip = new JSZip();
  const loadedZip = await zip.loadAsync(file);
  const files: FileItem[] = [];

  const filePaths = Object.keys(loadedZip.files).sort((a, b) => 
    a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' })
  );

  for (const relativePath of filePaths) {
    const zipEntry = loadedZip.files[relativePath];
    if (!zipEntry.dir && zipEntry.name.toLowerCase().endsWith('.txt')) {
      const content = await zipEntry.async('string');
      files.push({
        id: crypto.randomUUID(),
        name: zipEntry.name.split('/').pop() || zipEntry.name, 
        content: content,
        translatedContent: null,
        status: FileStatus.IDLE,
        retryCount: 0,
        originalCharCount: content.length,
        remainingRawCharCount: 0,
      });
    }
  }
  return files;
};

export const parseDocx = async (file: File): Promise<string> => {
    try {
        const zip = new JSZip();
        const loadedZip = await zip.loadAsync(file);
        const xmlContent = await loadedZip.file("word/document.xml")?.async("string");
        if (!xmlContent) throw new Error("Invalid DOCX");
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlContent, "text/xml");
        const paragraphs = xmlDoc.getElementsByTagName("w:p");
        let fullText = "";
        for (let i = 0; i < paragraphs.length; i++) {
            const texts = paragraphs[i].getElementsByTagName("w:t");
            for (let j = 0; j < texts.length; j++) fullText += texts[j].textContent;
            fullText += "\n";
        }
        return fullText.trim();
    } catch (e: any) { throw new Error(`Failed to parse DOCX: ${e.message}`); }
};

export const splitContentByRegex = (content: string, customRegex?: string): FileItem[] => {
    const defaultRegex = /(?:^|\n)(?:第[0-9零一二三四五六七八九十百千]+[章話節回].*?|Chapter\s+\d+.*?|Chương\s+\d+.*?|Hồi\s+\d+.*?|^\d+[\.．]\s.*?|^\d+話.*?)(?=\n|$)/im;
    const regex = customRegex ? new RegExp(customRegex, 'im') : defaultRegex;
    const lines = content.split('\n');
    const files: FileItem[] = [];
    let currentBuffer: string[] = [];
    let currentTitle = "Phần mở đầu";
    for (const line of lines) {
        if (regex.test(line)) {
            if (currentBuffer.length > 0) {
                files.push({
                    id: crypto.randomUUID(),
                    name: currentTitle.replace(/[:/\\?%*|"<>]/g, '').trim().substring(0, 50) || `Chương ${files.length + 1}`,
                    content: currentBuffer.join('\n').trim(),
                    translatedContent: null,
                    status: FileStatus.IDLE,
                    retryCount: 0,
                    originalCharCount: currentBuffer.join('\n').length,
                    remainingRawCharCount: 0,
                });
            }
            currentTitle = line.trim();
            currentBuffer = [line];
        } else currentBuffer.push(line);
    }
    if (currentBuffer.length > 0) {
         files.push({
            id: crypto.randomUUID(),
            name: currentTitle.replace(/[:/\\?%*|"<>]/g, '').trim().substring(0, 50) || `Chương ${files.length + 1}`,
            content: currentBuffer.join('\n').trim(),
            translatedContent: null,
            status: FileStatus.IDLE,
            retryCount: 0,
            originalCharCount: currentBuffer.join('\n').length,
            remainingRawCharCount: 0,
        });
    }
    return files;
};

export const splitContentByLength = (content: string, charLimit: number = 6000): FileItem[] => {
    const cleanupRegex = /(?:^|\n)(?:第[0-9零一二三四五六七八九十百千]+[章話節回].*|Chapter\s+\d+.*|Chương\s+\d+.*|Hồi\s+\d+.*|^\d+[\.．]\s.*|^\d+話.*)(?=\n|$)/gim;
    const cleanedContent = content.replace(cleanupRegex, '\n').replace(/\n{3,}/g, '\n\n').trim();
    const files: FileItem[] = [];
    let currentIndex = 0;
    let chapterCount = 1;
    while (currentIndex < cleanedContent.length) {
        let endIndex = Math.min(currentIndex + charLimit, cleanedContent.length);
        if (endIndex < cleanedContent.length) {
            const nextNewline = cleanedContent.indexOf('\n', endIndex);
            if (nextNewline !== -1 && (nextNewline - endIndex) < 2000) endIndex = nextNewline + 1;
            else {
                const prevNewline = cleanedContent.lastIndexOf('\n', endIndex);
                if (prevNewline > currentIndex) endIndex = prevNewline + 1;
            }
        }
        const chunkText = cleanedContent.substring(currentIndex, endIndex).trim();
        if (chunkText.length > 0) {
             const title = `Chương ${chapterCount}`;
             const finalContent = `${title}\n\n${chunkText}`;
             files.push({ id: crypto.randomUUID(), name: title, content: finalContent, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: finalContent.length, remainingRawCharCount: 0 });
            chapterCount++;
        }
        currentIndex = endIndex;
    }
    return files;
};

export const parseEpub = async (file: File): Promise<{ files: FileItem[], info: Partial<StoryInfo>, coverBlob: Blob | null }> => {
  const zip = new JSZip();
  const loadedZip = await zip.loadAsync(file);
  const containerXml = await loadedZip.file("META-INF/container.xml")?.async("string");
  if (!containerXml) throw new Error("Invalid EPUB");
  const parser = new DOMParser();
  const containerDoc = parser.parseFromString(containerXml, "text/xml");
  const opfPath = containerDoc.getElementsByTagName("rootfile")[0]?.getAttribute("full-path");
  if (!opfPath) throw new Error("Invalid EPUB");
  const opfContent = await loadedZip.file(opfPath)?.async("string");
  if (!opfContent) throw new Error("Invalid EPUB");
  const opfDoc = parser.parseFromString(opfContent, "text/xml");
  const metadataTitle = opfDoc.getElementsByTagName("dc:title")[0]?.textContent || "";
  const metadataAuthor = opfDoc.getElementsByTagName("dc:creator")[0]?.textContent || "";
  const opfDir = opfPath.substring(0, opfPath.lastIndexOf('/'));
  const getFullPath = (href: string) => opfDir ? `${opfDir}/${href}` : href;
  const manifestItems = opfDoc.getElementsByTagName("item");
  const manifest: Record<string, string> = {};
  for (let i = 0; i < manifestItems.length; i++) {
    const id = manifestItems[i].getAttribute("id");
    const href = manifestItems[i].getAttribute("href");
    if (id && href) manifest[id] = href;
  }
  const spineItems = opfDoc.getElementsByTagName("itemref");
  const files: FileItem[] = [];
  let chapterIndex = 1;
  for (let i = 0; i < spineItems.length; i++) {
    const idref = spineItems[i].getAttribute("idref");
    if (!idref || !manifest[idref]) continue;
    const fullPath = getFullPath(manifest[idref]);
    const fileContent = await loadedZip.file(fullPath)?.async("string");
    if (!fileContent) continue;
    const htmlDoc = parser.parseFromString(fileContent, "text/html");
    const scripts = htmlDoc.getElementsByTagName('script');
    for (let j = scripts.length - 1; j >= 0; j--) scripts[j].remove();
    let rawText = htmlDoc.body ? htmlDoc.body.innerText : "";
    if (rawText.trim().length < 50) continue;
    files.push({ id: crypto.randomUUID(), name: `Chương ${chapterIndex++}`, content: rawText.trim(), translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: rawText.length, remainingRawCharCount: 0 });
  }
  return { files, info: { title: metadataTitle, author: metadataAuthor }, coverBlob: null };
};

export const createMergedFile = (files: FileItem[]): string => {
  return [...files].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }))
    .filter((f) => f.status === FileStatus.COMPLETED && f.translatedContent)
    .map((f) => f.translatedContent?.trim()) 
    .join('\n\n'); 
};

export const downloadRawAsZip = async (files: FileItem[], filename: string) => {
    const zip = new JSZip();
    [...files].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }))
    .forEach(f => {
        let safeName = f.name.replace(/[:/\\?%*|"<>]/g, '_').trim();
        if (!safeName.toLowerCase().endsWith('.txt')) safeName += '.txt';
        zip.file(safeName, f.content);
    });
    const blob = await zip.generateAsync({ type: "blob" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename.endsWith('.zip') ? filename : `${filename}.zip`;
    a.click();
    URL.revokeObjectURL(url);
};

export const downloadTextFile = (filename: string, content: string) => {
  const file = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(file);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
};

export const downloadJsonFile = (filename: string, data: any) => {
  const file = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(file);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
};

export const readFileAsText = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => resolve(e.target?.result as string);
    reader.onerror = (e) => reject(e);
    reader.readAsText(file);
  });
};

export const generateEpub = async (files: FileItem[], storyInfo: StoryInfo, coverImage: File | null): Promise<Blob> => {
  const zip = new JSZip();
  const sortedFiles = [...files].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true })).filter(f => f.status === FileStatus.COMPLETED);
  if (sortedFiles.length === 0) throw new Error("No files");
  zip.file("mimetype", "application/epub+zip", { compression: "STORE" });
  zip.folder("META-INF")?.file("container.xml", `<?xml version="1.0"?><container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>`);
  const oebps = zip.folder("OEBPS");
  oebps?.file("Styles/style.css", `body { font-family: serif; line-height: 1.5; padding: 1em; } h2 { text-align: center; } p { text-indent: 1.5em; margin: 0.5em 0; }`);
  let manifest = ""; let spine = "";
  sortedFiles.forEach((f, i) => {
    const id = `ch${i}`;
    const html = `<?xml version="1.0" encoding="utf-8"?><!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml"><head><title>${f.name}</title><link href="../Styles/style.css" rel="stylesheet" type="text/css"/></head><body><h2>${f.name}</h2>${(f.translatedContent || "").split('\n').map(l => `<p>${l}</p>`).join('')}</body></html>`;
    oebps?.file(`Text/${id}.xhtml`, html);
    manifest += `<item id="${id}" href="Text/${id}.xhtml" media-type="application/xhtml+xml"/>\n`;
    spine += `<itemref idref="${id}"/>\n`;
  });
  oebps?.file("content.opf", `<?xml version="1.0" encoding="UTF-8"?><package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="id"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>${storyInfo.title}</dc:title><dc:creator>${storyInfo.author}</dc:creator><dc:language>vi</dc:language><dc:identifier id="id">uuid</dc:identifier></metadata><manifest>${manifest}</manifest><spine>${spine}</spine></package>`);
  return await zip.generateAsync({ type: "blob" });
};

import { GoogleGenAI } from '@google/genai';
import { LineContext, findLinesWithForeignChars, mergeFixedLines, replacePromptVariables } from './utils/textHelpers';
