const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("Không tìm thấy API Key. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

const optimizeDictionary = (dictionary: string, content: string): string => {
  if (!content || !dictionary) return '';
  const lines = dictionary.split('\n');
  const uniqueMap = new Map<string, string>();
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//')) continue;
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; 
    const key = trimmed.substring(0, eqIndex).trim();
    if (key) uniqueMap.set(key, trimmed);
  }
  const usedLines: string[] = [];
  for (const [key, line] of uniqueMap.entries()) {
      if (content.includes(key)) usedLines.push(line);
  }
  return usedLines.join('\n');
};

const formatError = (error: any, modelId: string): string => {
    const msg = (error.message || error.toString()).toLowerCase();
    if (msg.includes('quota')) return `Model ${modelId} hết dung lượng (Quota Exceeded).`;
    if (msg.includes('429')) return `Model ${modelId} quá tải. Đang cooldown...`;
    if (msg.includes('safety')) return `Nội dung bị Gemini chặn do vi phạm quy tắc an toàn.`;
    return error.message || error.toString();
};

const handleErrorQuota = (error: any, modelId: string) => {
    const msg = (error.message || error.toString()).toLowerCase();
    if (msg.includes('quota') || msg.includes('exhausted')) {
        quotaManager.markAsDepleted(modelId);
    } else if (error.status === 429 || msg.includes('429')) {
        quotaManager.recordRateLimit(modelId);
    }
};

export const testModelConnection = async (modelId: string): Promise<{ success: boolean; message: string }> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: modelId,
            contents: "Hi",
            config: { maxOutputTokens: 10 }
        });
        return { success: !!response.text, message: response.text ? "Kết nối thành công!" : "Không phản hồi." };
    } catch (error: any) {
        return { success: false, message: formatError(error, modelId) };
    }
};

export const optimizePrompt = async (promptTemplate: string, storyInfo: StoryInfo): Promise<string> => {
  const ai = getAiClient();
  const modelsToTry = ['gemini-3-pro-preview', 'gemini-3-flash-preview'];
  const filledTemplate = replacePromptVariables(promptTemplate, storyInfo);

  const instruction = `Bạn là chuyên gia Prompt Engineering. Hãy tối ưu prompt dịch truyện cho bộ truyện này. Loại bỏ các phần thừa không liên quan đến thể loại.`;
  const userContent = `[TRUYỆN]: ${storyInfo.title}\n[THÔNG TIN]: ${JSON.stringify(storyInfo)}\n[PROMPT]:\n${filledTemplate}`;

  for (const modelId of modelsToTry) {
      if (!quotaManager.isModelAvailable(modelId)) continue;
      try {
        const response = await ai.models.generateContent({
          model: modelId,
          contents: userContent,
          config: { 
            systemInstruction: instruction,
            temperature: 0.7,
            thinkingConfig: { thinkingBudget: 4096 } // Sử dụng thinking cho việc thiết kế prompt
          },
        });
        if (response.text) {
          quotaManager.recordRequest(modelId);
          return response.text.trim();
        }
      } catch (error: any) {
         handleErrorQuota(error, modelId);
      }
  }
  return filledTemplate; 
};

export const analyzeStoryContext = async (files: FileItem[], storyInfo: StoryInfo): Promise<string> => {
    const ai = getAiClient();
    const modelsToTry = ['gemini-3-pro-preview', 'gemini-3-flash-preview'];
    let contextContent = files.slice(0, 5).map(f => f.content).join('\n').substring(0, 50000);
    const userPrompt = `Phân tích cốt truyện và lập từ điển nhân vật từ nội dung sau:\n${contextContent}`;

    for (const modelId of modelsToTry) {
        if (!quotaManager.isModelAvailable(modelId)) continue;
        try {
            const response = await ai.models.generateContent({
                model: modelId,
                contents: userPrompt,
                config: {
                    systemInstruction: GLOSSARY_ANALYSIS_PROMPT,
                    temperature: 0.2,
                    thinkingConfig: { thinkingBudget: 8192 }
                },
            });
            if (response.text) {
                quotaManager.recordRequest(modelId);
                return response.text.trim();
            }
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    return "Không thể phân tích ngữ cảnh.";
};

let translationRequestCount = 0;
const selectModel = (allowedModelIds: string[]) => {
  const currentConfigs = quotaManager.getConfigs();
  const priorityTier = ['gemini-3-pro-preview', 'gemini-3-flash-preview', 'gemini-2.5-flash'];
  const available = currentConfigs
    .filter(c => allowedModelIds.includes(c.id) && quotaManager.isModelAvailable(c.id))
    .sort((a, b) => priorityTier.indexOf(a.id) - priorityTier.indexOf(b.id));

  if (available.length === 0) return [];
  translationRequestCount++;
  return available.map(m => m.id);
}

export const translateBatch = async (
    files: { id: string, content: string }[],
    userPrompt: string,
    dictionary: string,
    globalContext: string,
    allowedModelIds: string[]
): Promise<{ results: Map<string, string>, model: string }> => {
    const ai = getAiClient();
    const combinedContent = files.map(f => f.content).join('\n');
    const relevantDictionary = optimizeDictionary(dictionary, combinedContent);

    let inputContent = "";
    for (const file of files) {
        inputContent += `\n[[[FILE: ${file.id}]]]\n${file.content}\n[[[END: ${file.id}]]]\n`;
    }

    const systemInstruction = `Bạn là dịch giả chuyên nghiệp. Dịch đa chương truyện Trung Quốc. Giữ nguyên các tag [[[FILE: ID]]] và [[[END: ID]]].`;
    const fullPrompt = `[GLOSSARY]\n${relevantDictionary}\n\n[CONTEXT]\n${globalContext}\n\n[INSTRUCTION]\n${userPrompt}\n\n[INPUT]\n${inputContent}`;

    const attempts = selectModel(allowedModelIds);
    for (const modelId of attempts) {
        try {
            const isGemini3 = modelId.includes('gemini-3');
            const response = await ai.models.generateContent({
                model: modelId,
                contents: fullPrompt,
                config: {
                    systemInstruction,
                    temperature: 0.3,
                    maxOutputTokens: 60000,
                    ...(isGemini3 ? { thinkingConfig: { thinkingBudget: 16384 } } : {})
                },
            });

            if (!response.text) continue;
            const results = new Map<string, string>();
            for (const file of files) {
                const regex = new RegExp(`\\[\\[\\[FILE:\\s*${file.id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\]\\]\\]([\\s\\S]*?)\\[\\[\\[END:\\s*${file.id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\]\\]\\]`, 'i');
                const match = response.text.match(regex);
                if (match) results.set(file.id, match[1].trim());
            }
            if (results.size > 0) {
                quotaManager.recordRequest(modelId);
                return { results, model: modelId };
            }
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    throw new Error("Dịch thất bại trên mọi model.");
};

