import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2 } from 'lucide-react';
import { FileItem, FileStatus, ProcessingStats, StoryInfo, ModelQuota } from './types';
import { DEFAULT_PROMPT, DEFAULT_DICTIONARY, AVAILABLE_LANGUAGES, AVAILABLE_GENRES, AVAILABLE_PERSONALITIES, AVAILABLE_SETTINGS, AVAILABLE_FLOWS, MODEL_CONFIGS } from './constants';
import { translateText, repairTranslations, optimizePrompt, analyzeStoryContext, translateBatch, testModelConnection } from './geminiService';
import { unzipFiles, parseEpub, createMergedFile, downloadTextFile, readFileAsText, generateEpub, downloadJsonFile, parseDocx, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { findLinesWithForeignChars, mergeFixedLines, countForeignChars, replacePromptVariables, FOREIGN_CHARS_REGEX } from './utils/textHelpers';
import { saveToStorage, loadFromStorage, clearDatabase } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const STORAGE_KEY = 'current_session_v1';
const MAX_CONCURRENCY = 2; 
const BATCH_FILE_LIMIT = 3; 
const BATCH_CHAR_LIMIT = 20000; 

const App: React.FC = () => {
  const [files, setFiles] = useState<FileItem[]>([]);
  const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set());
  const [promptTemplate, setPromptTemplate] = useState<string>(DEFAULT_PROMPT); 
  const [storyInfo, setStoryInfo] = useState<StoryInfo>({
    title: '', author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'],
    mcPersonality: [], worldSetting: [], sectFlow: [], contextNotes: ''
  });

  const [additionalDictionary, setAdditionalDictionary] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [enabledModels, setEnabledModels] = useState<string[]>(MODEL_CONFIGS.map(m => m.id));
  const [showSettings, setShowSettings] = useState<boolean>(true);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [globalContext, setGlobalContext] = useState<string>("");

  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);
  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  // Logic xử lý hàng chờ tự động
  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY) return;

    const runWorker = async () => {
      // Lấy danh sách file để batching
      const batchIds: string[] = [];
      let currentCharCount = 0;
      let tempQueue = [...processingQueue];

      while (batchIds.length < BATCH_FILE_LIMIT && tempQueue.length > 0) {
        const id = tempQueue[0];
        const file = files.find(f => f.id === id);
        if (file) {
          if (currentCharCount + file.content.length > BATCH_CHAR_LIMIT && batchIds.length > 0) break;
          batchIds.push(id);
          currentCharCount += file.content.length;
          tempQueue.shift();
        } else {
          tempQueue.shift();
        }
      }

      if (batchIds.length === 0) {
        setProcessingQueue([]);
        setIsProcessing(false);
        return;
      }

      // Cập nhật queue và số lượng worker đang chạy
      setProcessingQueue(tempQueue);
      setActiveWorkers(prev => prev + 1);

      // Cập nhật trạng thái file đang dịch
      setFiles(prev => prev.map(f => batchIds.includes(f.id) ? { ...f, status: FileStatus.PROCESSING } : f));

      try {
        const filesToTranslate = files
          .filter(f => batchIds.includes(f.id))
          .map(f => ({ id: f.id, content: f.content }));

        const { results, model } = await translateBatch(
          filesToTranslate,
          replacePromptVariables(promptTemplate, storyInfo),
          additionalDictionary,
          globalContext,
          enabledModels
        );

        setFiles(prev => prev.map(f => {
          if (batchIds.includes(f.id)) {
            const translated = results.get(f.id);
            return {
              ...f,
              status: translated ? FileStatus.COMPLETED : FileStatus.ERROR,
              translatedContent: translated || null,
              usedModel: model,
              errorMessage: translated ? undefined : "Không nhận được kết quả dịch từ AI"
            };
          }
          return f;
        }));
      } catch (error: any) {
        console.error("Batch Translation Error:", error);
        setFiles(prev => prev.map(f => batchIds.includes(f.id) ? { 
          ...f, 
          status: FileStatus.ERROR, 
          errorMessage: error.message || "Lỗi hệ thống" 
        } : f));
        addToast(`Lỗi khi dịch: ${error.message}`, 'error');
      } finally {
        setActiveWorkers(prev => prev - 1);
      }
    };

    runWorker();
  }, [isProcessing, processingQueue, activeWorkers, files, promptTemplate, storyInfo, additionalDictionary, globalContext, enabledModels]);

  // Dừng xử lý khi hàng chờ hết
  useEffect(() => {
    if (isProcessing && processingQueue.length === 0 && activeWorkers === 0) {
      setIsProcessing(false);
      addToast("Đã hoàn thành tất cả các bản dịch!", "success");
    }
  }, [processingQueue.length, activeWorkers, isProcessing]);

  const handleLinkSubmit = async () => {
