      if (urls.length === 0) {
          addToast("Vui lòng nhập ít nhất 1 đường link hợp lệ", 'error');
          return;
      }

      setIsFetchingLinks(true);
      addToast(`Đang bóc tách dữ liệu từ ${urls.length} đường link...`, 'info');

      const newItems: FileItem[] = [];
      let successCount = 0;

      for (const url of urls) {
          try {
              const { title, content } = await fetchContentFromUrl(url);
              newItems.push({
                  id: crypto.randomUUID(),
                  name: title,
                  content: content,
                  translatedContent: null,
                  status: FileStatus.IDLE,
                  retryCount: 0,
                  originalCharCount: content.length,
                  remainingRawCharCount: 0
              });
              successCount++;
          } catch (e: any) {
              console.error(e);
              addToast(`Lỗi lấy link: ${url.substring(0, 30)}...`, 'error');
          }
      }

      if (newItems.length > 0) {
          setFiles(prev => [...prev, ...newItems]);
          addToast(`Đã thêm thành công ${successCount} chương từ link`, 'success');
          setLinkInput("");
          setShowLinkModal(false);
      }
      setIsFetchingLinks(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files) return;
      const fileList = Array.from(e.target.files);
      const newItems: FileItem[] = [];

      for (const file of fileList) {
          try {
