  };

  const startProcessing = () => {
      const pending = files.filter(f => f.status === FileStatus.IDLE || f.status === FileStatus.ERROR);
      if (pending.length === 0) {
        addToast("Không có chương nào cần dịch", "info");
        return;
      }
      setProcessingQueue(pending.map(f => f.id));
      setIsProcessing(true);
      addToast("Bắt đầu tiến trình dịch thuật...", "info");
  };

  const stopProcessing = () => {
