      setFiles([]);
      addToast("Đã xóa sạch danh sách", "info");
    }
  };

  const stats = useMemo(() => ({
      total: files.length,
      completed: files.filter(f => f.status === FileStatus.COMPLETED).length,
      failed: files.filter(f => f.status === FileStatus.ERROR).length,
      processing: files.filter(f => f.status === FileStatus.PROCESSING).length
  }), [files]);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 p-6">
