  const copyToClipboard = (text: string | null) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    addToast("Đã sao chép vào bộ nhớ tạm", "success");
  };

  const stats = useMemo(() => ({
      total: files.length,
      completed: files.filter(f => f.status === FileStatus.COMPLETED).length,
      failed: files.filter(f => f.status === FileStatus.ERROR).length,
      processing: files.filter(f => f.status === FileStatus.PROCESSING).length
  }), [files]);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 p-6">
      <div className="fixed top-6 right-6 z-[200] flex flex-col gap-2">
          {toasts.map(t => (
              <div key={t.id} className={`px-4 py-3 rounded-xl shadow-lg border text-sm font-medium animate-in slide-in-from-right duration-300 ${t.type === 'error' ? 'bg-rose-50 border-rose-100 text-rose-600' : t.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-white border-slate-100 text-slate-700'}`}>
                  {t.message}
              </div>
          ))}
      </div>

      {/* Modal Tách Chương */}
      {showSplitModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[160] flex items-center justify-center p-4">
           <div className="bg-white rounded-[28px] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95">
              <div className="p-6 border-b border-slate-100 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-2.5 bg-sky-100 text-sky-600 rounded-xl"><Split className="w-5 h-5" /></div>
                  <h3 className="font-bold">Tách chương tự động</h3>
                </div>
                <button onClick={() => setShowSplitModal(null)} className="p-2 text-slate-400 hover:bg-slate-50 rounded-lg"><X className="w-5 h-5" /></button>
              </div>
              <div className="p-6 space-y-4">
                <div className="p-4 bg-sky-50 rounded-2xl border border-sky-100 text-xs text-sky-700 leading-relaxed">
                  File này có <strong>{showSplitModal.content.length}</strong> ký tự. Hãy chọn cách tách để AI dịch tốt hơn.
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Regex nhận diện chương (Tùy chọn)</label>
                  <input 
                    className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm outline-none focus:ring-2 focus:ring-sky-200" 
                    placeholder="VD: Chương \d+:.*"
                    value={splitRegex}
                    onChange={e => setSplitRegex(e.target.value)}
                  />
                </div>
                <div className="grid grid-cols-2 gap-3 pt-2">
                  <button onClick={() => handleSplitFile(showSplitModal)} className="py-3 bg-sky-500 hover:bg-sky-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-sky-100 transition-all">Tách ngay</button>
                  <button onClick={() => setShowSplitModal(null)} className="py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl font-bold text-sm transition-all">Bỏ qua</button>
                </div>
              </div>
           </div>
        </div>
      )}

      {/* Modal View & Detail */}
      {viewingFile && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4 md:p-10 overflow-hidden animate-in fade-in duration-200">
           <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-6xl h-full flex flex-col overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-white/50 backdrop-blur-sm sticky top-0 z-10">
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-sky-100 text-sky-600 rounded-2xl"><BookOpen className="w-6 h-6" /></div>
                    <div>
                      <h3 className="text-xl font-extrabold text-slate-900 leading-tight">{viewingFile.name}</h3>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{viewingFile.originalCharCount} ký tự</span>
                        <span className="text-slate-200">•</span>
                        <span className="text-[10px] font-bold text-sky-500 uppercase tracking-wider">{viewingFile.usedModel || "Chưa dịch"}</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => copyToClipboard(viewingFile.translatedContent)} disabled={!viewingFile.translatedContent} className="p-3 hover:bg-slate-100 text-slate-500 rounded-2xl transition-all disabled:opacity-30" title="Copy bản dịch"><Copy className="w-5 h-5" /></button>
                    <button onClick={() => setViewingFile(null)} className="p-3 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all"><X className="w-6 h-6" /></button>
                  </div>
              </div>
              <div className="flex-1 overflow-hidden grid grid-cols-1 md:grid-cols-2">
