};

export default App;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

// Cấu hình tối ưu: Giảm số luồng song song để đảm bảo tính tuần tự cao nhất
const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; // Dịch 2 chương mỗi đợt để AI không bị loạn và giữ thứ tự 1,2 -> 3,4

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(50);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);

  const [viewingFile, setViewingFile] = useState<FileItem | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  // Ref để theo dõi dự án đang dịch, tránh rò rỉ dữ liệu khi chuyển project
  const processingProjectIdRef = useRef<string | null>(null);

  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  // Load projects from DB
  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  // Tự động dừng dịch khi người dùng chuyển dự án để đảm bảo an toàn dữ liệu
  useEffect(() => {
    if (isProcessing && currentProjectId !== processingProjectIdRef.current) {
        stopTranslation();
        addToast("Đã dừng dịch dự án cũ để chuyển sang dự án mới", "info");
    }
  }, [currentProjectId]);

  // Persistent saving logic
  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) {
      console.error("Save failed", e);
    } finally {
      setIsSaving(false);
    }
  };

  // Auto-save on change
  useEffect(() => {
    if (currentProject) {
        persistProject(currentProject);
    }
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
    addToast("Đã tạo dự án truyện mới", "success");
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const deleteProjectAction = async (id: string) => {
    if (window.confirm("Bạn chắc chắn muốn xóa dự án này? Mọi chương truyện đã dịch sẽ mất sạch!")) {
        await deleteProject(id);
        setProjects(prev => prev.filter(p => p.id !== id));
        if (currentProjectId === id) setCurrentProjectId(null);
        addToast("Đã xóa dự án", "info");
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject || !window.confirm("Xóa chương này?")) return;
    updateProject(currentProject.id, {
        chapters: currentProject.chapters.filter(c => c.id !== chapterId)
    });
    addToast("Đã xóa chương", "info");
  };

  const clearAllChapters = () => {
    if (!currentProject || !window.confirm("Xóa toàn bộ chương trong dự án này?")) return;
    updateProject(currentProject.id, { chapters: [] });
    addToast("Đã xóa toàn bộ chương", "info");
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) return;

    setIsFetchingLinks(true);
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;
    let skipCount = 0;

    try {
      if (autoCrawl && urls.length === 1) {
          let currentUrl: string | null = urls[0];
          setFetchProgress({ current: 0, total: crawlLimit });

          for (let i = 0; i < crawlLimit; i++) {
              if (!currentUrl) break;
              const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());

              if (!isDuplicate) {
                const ch: FileItem = { 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                };
                updatedChapters.push(ch);
                addedCount++;
              } else {
                skipCount++;
              }

              setFetchProgress({ current: i + 1, total: crawlLimit });
              currentUrl = nextUrl;
              updateProject(currentProject.id, { chapters: [...updatedChapters] });
              await new Promise(r => setTimeout(r, 800));
          }
      } else {
          setFetchProgress({ current: 0, total: urls.length });
          for (let i = 0; i < urls.length; i++) {
              const { title, content } = await fetchContentFromUrl(urls[i]);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());

              if (!isDuplicate) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
              } else {
                skipCount++;
              }
              setFetchProgress({ current: i + 1, total: urls.length });
          }
          updateProject(currentProject.id, { chapters: updatedChapters });
      }
      if (addedCount > 0) addToast(`Đã thêm ${addedCount} chương mới`, 'success');
      if (skipCount > 0) addToast(`Bỏ qua ${skipCount} chương trùng lặp`, 'warning');
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally {
        setIsFetchingLinks(false);
        setFetchProgress(null);
        setShowLinkModal(false);
        setLinkInput("");
    }
  };

  const startTranslation = () => {
    if (!currentProject) return;

    // Tìm các chương chưa dịch và SẮP XẾP THEO TIÊU ĐỀ (Numeric sort) để dịch đúng thứ tự 1,2,3...
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));

    if (idleChapters.length === 0) {
        addToast("Không còn chương nào cần dịch!", "info");
        return;
    }

    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    addToast(`Bắt đầu dịch tuần tự ${idleChapters.length} chương...`, "success");
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt') => {
    if (!currentProject) return;
    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) {
      addToast("Chưa có chương nào hoàn thành để xuất!", "error");
      return;
    }
    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${currentProject.info.title}.epub`;
        a.click();
        addToast("Đã xuất Ebook thành công", "success");
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
        addToast("Đã xuất file TXT thành công", "success");
      }
    } catch (e: any) {
      addToast("Lỗi khi xuất file: " + e.message, "error");
    }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      if (currentProject.chapters.length === 0) {
          addToast("Cần ít nhất một chương để phân tích!", "warning");
          return;
      }
      setIsAnalyzing(true);
      addToast("AI đang đọc truyện để lập bối cảnh...", "info");
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("Đã lập bối cảnh truyện thành công!", "success");
      } catch (e: any) {
          addToast("Lỗi phân tích: " + e.message, "error");
      } finally {
          setIsAnalyzing(false);
      }
  };

  // Vòng lặp dịch chính
  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;

    // Đảm bảo dự án đang dịch trùng khớp với dự án hiện tại
    if (processingProjectIdRef.current !== currentProjectId) return;

    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId; // Giữ ID dự án đích để kiểm tra sau khi gọi API

        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);

        // UI: Đánh dấu đang xử lý
        setProjects(prev => prev.map(p => p.id === targetProjectId ? {
            ...p,
            chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c)
        } : p));

        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) {
            setActiveWorkers(prev => prev - 1);
            return;
        }

        const chaptersToTranslate = targetProj.chapters.filter(c => batchIds.includes(c.id));

        try {
            const { results, model } = await translateBatch(
                chaptersToTranslate,
                replacePromptVariables(targetProj.promptTemplate, targetProj.info),
                targetProj.dictionary,
                targetProj.globalContext,
                MODEL_CONFIGS.map(m => m.id)
            );

            // Cập nhật kết quả vào danh sách dự án
            setProjects(prev => prev.map(p => {
              if (p.id === targetProjectId) {
                return {
                  ...p,
                  lastModified: Date.now(),
                  chapters: p.chapters.map(c => {
                    if (batchIds.includes(c.id)) {
                      const translated = results.get(c.id);
                      return { 
                        ...c, 
                        status: translated ? FileStatus.COMPLETED : FileStatus.ERROR, 
                        translatedContent: translated || null, 
                        usedModel: model 
                      };
                    }
                    return c;
                  })
                };
              }
              return p;
            }));

        } catch (e) {
            console.error("Translation batch failed", e);
            // Rollback status về ERROR nếu thất bại
            setProjects(prev => prev.map(p => p.id === targetProjectId ? {
                ...p,
                chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c)
            } : p));
        } finally {
            setActiveWorkers(prev => prev - 1);
        }
    };

    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  const stats = useMemo(() => {
      if (!currentProject) return { total: 0, done: 0 };
      return {
          total: currentProject.chapters.length,
          done: currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length
      };
  }, [currentProject]);

  const filteredChapters = useMemo(() => {
      if (!currentProject) return [];
      // Sắp xếp theo tên để dễ theo dõi tiến độ
      return currentProject.chapters
        .filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject, searchTerm]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      {/* Sidebar: Projects */}
      <aside className="w-80 bg-white border-r border-slate-200 flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg shadow-sky-100"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg tracking-tight">Dịch Truyện Pro</h1>
            </div>
            <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl transition-all" title="Dự án mới"><PlusCircle className="w-6 h-6" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between items-center">
                <span>Dự án truyện ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin text-sky-400" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => setCurrentProjectId(p.id)} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProjectAction(p.id); }} className="opacity-0 group-hover:opacity-100 p-1.5 text-slate-300 hover:text-rose-500 rounded-lg transition-all"><Trash2 className="w-4 h-4" /></button>
                    </div>
                    <div className="mt-3 w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                        <div className="bg-sky-500 h-full transition-all duration-500" style={{ width: `${(p.chapters.filter(c => c.status === FileStatus.COMPLETED).length / (p.chapters.length || 1)) * 100}%` }} />
                    </div>
                </div>
            ))}
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              {/* Header */}
              <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-6">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <input 
                                className="bg-transparent font-bold text-xl outline-none focus:bg-slate-50 rounded px-1 -ml-1 transition-all"
                                value={currentProject.info.title}
                                onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })}
                            />
                            {isSaving && <Loader2 className="w-4 h-4 animate-spin text-slate-300" />}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-slate-500 font-medium">
                            <span className="flex items-center gap-1"><Book className="w-3.5 h-3.5" /> {stats.total} chương</span>
                            <span className="text-slate-300">•</span>
                            <span className="flex items-center gap-1 text-emerald-600 font-semibold"><CheckCircle className="w-3.5 h-3.5" /> {stats.done} hoàn thành</span>
                        </div>
                      </div>
                  </div>

                  <div className="flex items-center gap-3">
                      <button onClick={() => setShowLinkModal(true)} className="flex items-center gap-2 px-4 py-2.5 bg-white border border-slate-200 rounded-xl font-bold text-sm hover:bg-sky-50 hover:border-sky-200 transition-all shadow-sm">
                          <Link2 className="w-4 h-4 text-sky-500" /> Cào hàng loạt
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : startTranslation()} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm shadow-lg transition-all ${isProcessing ? 'bg-rose-500 text-white shadow-rose-100' : 'bg-sky-500 text-white shadow-sky-100 hover:scale-105 active:scale-95'}`}>
                          {isProcessing ? <><Loader2 className="w-4 h-4 animate-spin" /> Dừng dịch</> : <><Play className="w-4 h-4" /> Dịch dự án</>}
                      </button>
                      <button onClick={() => handleExport('epub')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl transition-all" title="Xuất Ebook"><Download className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden">
                {/* Chapters List */}
                <div className="flex-1 flex flex-col p-8 overflow-hidden">
                    <div className="mb-6 flex items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input 
                                className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-sky-200 shadow-sm"
                                placeholder="Tìm chương..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                        </div>
                        {currentProject.chapters.length > 0 && (
                            <button onClick={clearAllChapters} className="flex items-center gap-2 px-4 py-3 text-rose-500 hover:bg-rose-50 rounded-2xl font-bold text-xs transition-all">
                                <Trash2 className="w-4 h-4" /> Xóa tất cả chương
                            </button>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-4 content-start pb-10">
                        {filteredChapters.map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100 hover:border-emerald-200' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100 shadow-inner' : 'bg-white border-slate-100 hover:border-slate-200'}`}>
                                <div className="flex items-start justify-between gap-3">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2.5 rounded-2xl transition-all ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin shadow-lg shadow-sky-200' : ch.status === FileStatus.ERROR ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-400'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-5 h-5" /> : ch.status === FileStatus.ERROR ? <AlertCircle className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-sm truncate pr-2">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400 mt-0.5 font-medium">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setViewingFile(ch)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl transition-all" title="Xem nội dung"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all" title="Xóa chương"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex items-center justify-between">
                                    <span className={`text-[9px] font-extrabold px-2.5 py-1 rounded-lg uppercase tracking-wider flex items-center gap-1 ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : ch.status === FileStatus.PROCESSING ? 'bg-sky-100 text-sky-700' : ch.status === FileStatus.ERROR ? 'bg-rose-100 text-rose-700' : 'bg-slate-100 text-slate-500'}`}>
                                        {ch.status === FileStatus.PROCESSING && <Loader2 className="w-2.5 h-2.5 animate-spin" />}
                                        {ch.status === FileStatus.PROCESSING ? 'Đang dịch...' : ch.status}
                                    </span>
                                    {ch.usedModel && <span className="text-[9px] font-bold text-slate-400 bg-slate-50 px-2 py-0.5 rounded-md border border-slate-100">{ch.usedModel.split('-').slice(-2).join(' ')}</span>}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right Panel: Settings & Context */}
                <div className="w-96 border-l border-slate-200 bg-white overflow-y-auto p-8 space-y-8">
                    <section className="space-y-4">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2"><Settings className="w-4 h-4" /> Cấu hình truyện</h4>
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Tác giả</label>
                                <input className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm focus:ring-2 focus:ring-sky-200 outline-none transition-all" value={currentProject.info.author} onChange={e => updateProject(currentProject.id, { info: {...currentProject.info, author: e.target.value} })} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Kinh thánh truyện (Context)</label>
                                <div className="relative group">
                                    <textarea 
                                        className="w-full h-32 p-3 bg-emerald-50/30 border border-emerald-100 rounded-xl text-xs text-emerald-900 leading-relaxed resize-none outline-none focus:ring-2 focus:ring-emerald-200 transition-all" 
                                        placeholder="Thông tin bối cảnh, nhân vật..." 
                                        value={currentProject.globalContext} 
                                        onChange={e => updateProject(currentProject.id, { globalContext: e.target.value })} 
                                    />
                                    <button 
                                        onClick={handleAnalyzeContext} 
                                        disabled={isAnalyzing}
                                        className={`absolute bottom-3 right-3 p-2 bg-white rounded-lg shadow-md border border-emerald-100 text-emerald-500 hover:bg-emerald-50 hover:scale-110 active:scale-95 transition-all ${isAnalyzing ? 'bg-emerald-50 cursor-not-allowed' : ''}`}
                                        title="AI tự động phân tích bối cảnh"
                                    >
                                        {isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin text-emerald-600" /> : <Brain className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </section>

                    <section className="space-y-4">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2"><Wrench className="w-4 h-4" /> Từ điển (Glossary)</h4>
                        <textarea className="w-full h-48 p-3 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-mono leading-normal resize-none focus:ring-2 focus:ring-sky-200 outline-none transition-all" placeholder="TừGốc=TừDịch..." value={currentProject.dictionary} onChange={e => updateProject(currentProject.id, { dictionary: e.target.value })} />
                    </section>
                </div>
              </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center p-20 text-center animate-in fade-in duration-500">
                <div className="w-24 h-24 bg-sky-100 rounded-[32px] flex items-center justify-center mb-8 shadow-2xl shadow-sky-200/50"><LayoutDashboard className="w-12 h-12 text-sky-500" /></div>
                <h2 className="text-3xl font-bold text-slate-900 tracking-tight">Quản lý Dự án Truyện</h2>
                <p className="text-slate-500 mt-2 max-w-sm">Chọn một bộ truyện ở Sidebar hoặc tạo dự án mới để bắt đầu "bào" truyện thông minh.</p>
                <button onClick={createNewProject} className="mt-8 px-8 py-4 bg-sky-500 text-white rounded-[20px] font-bold shadow-xl shadow-sky-200 hover:-translate-y-1 hover:shadow-2xl transition-all flex items-center gap-2">
                    <PlusCircle className="w-5 h-5" /> Tạo Dự Án Mới Ngay
                </button>
            </div>
          )}
      </main>

      {/* Link Modal: Bulk Crawler */}
      {showLinkModal && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
              <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
                  <div className="p-8">
                      <div className="flex items-center gap-4 mb-8">
                          <div className="p-4 bg-sky-100 text-sky-600 rounded-2xl"><ListPlus className="w-6 h-6" /></div>
                          <div>
                              <h3 className="text-xl font-bold tracking-tight">Cào Truyện Thông Minh</h3>
                              <p className="text-sm text-slate-500">Hỗ trợ cào hàng loạt, tự động lưu tiến trình.</p>
                          </div>
                      </div>

                      <div className="space-y-6">
                        <div className="space-y-2">
                          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">URL Chương bắt đầu</label>
                          <textarea 
                              className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-sky-400 font-mono resize-none shadow-inner"
                              placeholder="Dán link chương 1 vào đây..."
                              value={linkInput}
                              onChange={e => setLinkInput(e.target.value)}
                          />
                        </div>

                        <div className="p-5 bg-slate-50 rounded-3xl border border-slate-100 space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <Hash className="w-4 h-4 text-sky-500" />
                                    <span className="text-sm font-bold">Số lượng chương muốn lấy</span>
                                </div>
                                <input 
                                    type="number" 
                                    className="w-20 p-2 bg-white border border-slate-200 rounded-xl text-sm font-bold text-center outline-none focus:ring-2 focus:ring-sky-200"
                                    value={crawlLimit}
                                    onChange={e => setCrawlLimit(parseInt(e.target.value) || 1)}
                                />
                            </div>
                            <div className="flex items-center gap-3">
                                <div className={`w-10 h-6 rounded-full transition-all relative cursor-pointer ${autoCrawl ? 'bg-sky-500' : 'bg-slate-300'}`} onClick={() => setAutoCrawl(!autoCrawl)}>
                                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${autoCrawl ? 'left-5' : 'left-1'}`} />
                                </div>
                                <span className="text-xs font-bold text-slate-600">Bật cào tự động (Next Chapter)</span>
                            </div>
                        </div>
                      </div>

                      {fetchProgress && (
                          <div className="mt-8 space-y-2">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase tracking-wider">
                                  <span>Đang cào dữ liệu: {fetchProgress.current}/{fetchProgress.total}</span>
                              </div>
                              <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                                  <div className="h-full bg-sky-500 transition-all duration-300" style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }} />
                              </div>
                          </div>
                      )}

                      <div className="mt-10 flex gap-4">
                          <button onClick={() => setShowLinkModal(false)} className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-all">Đóng</button>
                          <button onClick={handleLinkSubmit} disabled={isFetchingLinks || !linkInput} className="flex-[2] py-4 bg-sky-500 hover:bg-sky-600 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 disabled:opacity-50 transition-all flex items-center justify-center gap-2">
                              {isFetchingLinks ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />}
                              Bắt Đầu Cào
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Viewing File Modal */}
      {viewingFile && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-10 animate-in fade-in duration-300">
             <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-7xl h-full flex flex-col overflow-hidden animate-in zoom-in-95 duration-300">
                <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
                    <div className="flex items-center gap-4">
                        <h3 className="text-2xl font-bold tracking-tight">{viewingFile.name}</h3>
                        <span className="text-xs font-bold text-slate-400 bg-white border px-3 py-1 rounded-full shadow-sm uppercase tracking-widest">{viewingFile.originalCharCount} ký tự</span>
                    </div>
                    <button onClick={() => setViewingFile(null)} className="p-3 hover:bg-rose-50 text-slate-400 hover:text-rose-500 rounded-2xl transition-all"><X className="w-8 h-8" /></button>
                </div>
                <div className="flex-1 overflow-hidden grid grid-cols-2">
                    <div className="p-10 overflow-y-auto bg-slate-50/50 border-r border-slate-100 leading-relaxed text-lg font-serif selection:bg-sky-100 whitespace-pre-wrap">{viewingFile.content}</div>
                    <div className="p-10 overflow-y-auto leading-relaxed text-lg font-serif text-slate-900 selection:bg-emerald-100 whitespace-pre-wrap">
                        {viewingFile.translatedContent || <div className="h-full flex flex-col items-center justify-center text-slate-400 italic gap-4">
                            <FileText className="w-12 h-12 opacity-20" />
                            Chương này chưa được dịch.
                        </div>}
                    </div>
                </div>
             </div>
          </div>
      )}

      {/* Global Toasts */}
      <div className="fixed bottom-6 right-6 z-[400] flex flex-col gap-3">
          {toasts.map(t => (
              <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-right duration-300 backdrop-blur-md ${t.type === 'error' ? 'bg-rose-50/90 border-rose-100 text-rose-600' : t.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-600' : t.type === 'warning' ? 'bg-amber-50/90 border-amber-100 text-amber-600' : 'bg-white/90 border-slate-200 text-slate-700'}`}>
                  {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : t.type === 'warning' ? <AlertTriangle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
                  <span className="font-bold text-sm">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
};

export default App;

export enum FileStatus {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  REPAIRING = 'REPAIRING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR',
}

export interface FileItem {
  id: string;
  name: string;
  content: string;
  translatedContent: string | null;
  status: FileStatus;
  errorMessage?: string;
  retryCount: number;
  originalCharCount: number;
  remainingRawCharCount: number;
  usedModel?: string;
}

export interface StoryInfo {
  title: string;
  author: string;
  languages: string[];
  genres: string[];
  mcPersonality: string[];
  worldSetting: string[];
  sectFlow: string[];
  contextNotes?: string;
}

export interface StoryProject {
  id: string;
  info: StoryInfo;
  chapters: FileItem[];
  promptTemplate: string;
  dictionary: string;
  globalContext: string;
  createdAt: number;
  lastModified: number;
  lastCrawlUrl?: string; // Lưu URL cuối cùng để cào tiếp
}

export interface ModelQuota {
  id: string;
  name: string;
  rpmLimit: number;
  rpdLimit: number;
  priority: number;
  maxOutputTokens: number;
}

export interface ModelUsage {
  requestsToday: number;
  lastResetDate: string;
  recentRequests: number[];
  cooldownUntil: number;
  isDepleted: boolean;
}

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History, Infinity as InfinityIcon } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(50);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [showFlowOffer, setShowFlowOffer] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);

  const [viewingFile, setViewingFile] = useState<FileItem | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (isProcessing && currentProjectId !== processingProjectIdRef.current) {
        stopTranslation();
        addToast("Dừng dịch dự án cũ", "info");
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) {
      console.error("Save failed", e);
    } finally {
      setIsSaving(false);
    }
  };

  useEffect(() => {
    if (currentProject) {
        persistProject(currentProject);
    }
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
    addToast("Đã tạo dự án truyện mới", "success");
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const deleteProjectAction = async (id: string) => {
    if (window.confirm("Bạn chắc chắn muốn xóa dự án này?")) {
        await deleteProject(id);
        setProjects(prev => prev.filter(p => p.id !== id));
        if (currentProjectId === id) setCurrentProjectId(null);
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    updateProject(currentProject.id, {
        chapters: currentProject.chapters.filter(c => c.id !== chapterId)
    });
  };

  const clearAllChapters = () => {
    if (!currentProject || !window.confirm("Xóa toàn bộ chương?")) return;
    updateProject(currentProject.id, { chapters: [] });
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) return;

    setIsFetchingLinks(true);
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;
    let lastNextUrl: string | null = null;

    try {
      if (autoCrawl && urls.length === 1) {
          let currentUrl: string | null = urls[0];
          setFetchProgress({ current: 0, total: crawlLimit });

          for (let i = 0; i < crawlLimit; i++) {
              if (!currentUrl) break;
              const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());

              if (!isDuplicate) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
              }
              lastNextUrl = nextUrl;
              setFetchProgress({ current: i + 1, total: crawlLimit });
              currentUrl = nextUrl;
              updateProject(currentProject.id, { chapters: [...updatedChapters], lastCrawlUrl: lastNextUrl || undefined });
              await new Promise(r => setTimeout(r, 800));
          }
      } else {
          setFetchProgress({ current: 0, total: urls.length });
          for (let i = 0; i < urls.length; i++) {
              const { title, content, nextUrl } = await fetchContentFromUrl(urls[i]);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());
              if (!isDuplicate) {
                updatedChapters.push({ id: crypto.randomUUID(), name: title, content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: content.length, remainingRawCharCount: 0 });
                addedCount++;
              }
              lastNextUrl = nextUrl;
              setFetchProgress({ current: i + 1, total: urls.length });
          }
          updateProject(currentProject.id, { chapters: updatedChapters, lastCrawlUrl: lastNextUrl || undefined });
      }
      if (addedCount > 0) setShowFlowOffer(true);
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally {
        setIsFetchingLinks(false);
        setFetchProgress(null);
        setShowLinkModal(false);
        setLinkInput("");
    }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));

    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch!", "info");
        return;
    }

    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    addToast(continuous ? "Kích hoạt Chế độ Luồng Liên Tục: Dịch & Cào tự động" : "Bắt đầu dịch tuần tự", "success");
    setShowFlowOffer(false);
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;

    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        addToast("Đã xuất file gốc tiếng Trung", "success");
        return;
    }

    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) {
      addToast("Chưa có chương nào hoàn thành!", "error");
      return;
    }

    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${currentProject.info.title}.epub`;
        a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
      addToast("Xuất file thành công", "success");
    } catch (e: any) { addToast("Lỗi: " + e.message, "error"); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("Lập bối cảnh thành công", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  // Vòng lặp Continuous Flow: Cào tự động khi hàng đợi vơi
  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;

      const bufferLow = processingQueue.length < BATCH_FILE_LIMIT;
      if (bufferLow && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1000));
                  }

                  if (newChapters.length > 0) {
                      const updated = [...currentProject.chapters, ...newChapters];
                      updateProject(currentProject.id, { chapters: updated, lastCrawlUrl: nextUrl || undefined });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                      addToast(`Auto-flow: Đã cào thêm ${newChapters.length} chương mới`, "info");
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    if (processingProjectIdRef.current !== currentProjectId) return;

    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);

        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }

        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  const filteredChapters = useMemo(() => {
      if (!currentProject) return [];
      return currentProject.chapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject, searchTerm]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      <aside className="w-80 bg-white border-r border-slate-200 flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg">Dịch Truyện Pro</h1>
            </div>
            <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl transition-all"><PlusCircle className="w-6 h-6" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between">
                <span>Dự án ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => setCurrentProjectId(p.id)} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProjectAction(p.id); }} className="opacity-0 group-hover:opacity-100 p-1.5 hover:text-rose-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                    <div className="mt-3 w-full bg-slate-200 h-1 rounded-full overflow-hidden">
                        <div className="bg-sky-500 h-full transition-all duration-500" style={{ width: `${(p.chapters.filter(c => c.status === FileStatus.COMPLETED).length / (p.chapters.length || 1)) * 100}%` }} />
                    </div>
                </div>
            ))}
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-6">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <input className="bg-transparent font-bold text-xl outline-none" value={currentProject.info.title} onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })} />
                            {isProcessing && isContinuousFlow && <InfinityIcon className="w-5 h-5 text-sky-500 animate-pulse" title="Đang chạy Continuous Flow" />}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-slate-500">
                            <span className="flex items-center gap-1"><Book className="w-3.5 h-3.5" /> {currentProject.chapters.length} chương</span>
                            <span className="text-emerald-600 font-semibold"><CheckCircle className="w-3.5 h-3.5 inline mr-1" /> {currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length} xong</span>
                        </div>
                      </div>
                  </div>
                  <div className="flex items-center gap-2">
                      <button onClick={() => setShowLinkModal(true)} className="flex items-center gap-2 px-4 py-2 border rounded-xl font-bold text-sm hover:bg-sky-50">
                          <Link2 className="w-4 h-4 text-sky-500" /> Cào hàng loạt
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : startTranslation(false)} className={`px-6 py-2 rounded-xl font-bold text-sm shadow-lg ${isProcessing ? 'bg-rose-500 text-white' : 'bg-sky-500 text-white'}`}>
                          {isProcessing ? 'Dừng dịch' : 'Dịch dự án'}
                      </button>
                      <div className="h-8 w-px bg-slate-200 mx-1" />
                      <button onClick={() => handleExport('epub')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất EPUB"><Download className="w-5 h-5" /></button>
                      <button onClick={() => handleExport('raw')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất File Gốc (CN)"><Languages className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden">
                <div className="flex-1 flex flex-col p-8 overflow-hidden">
                    <div className="mb-6 flex items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none" placeholder="Tìm chương..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                        </div>
                        <button onClick={clearAllChapters} className="text-rose-500 font-bold text-xs">Xóa tất cả</button>
                    </div>
                    <div className="flex-1 overflow-y-auto grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-4 content-start pb-20">
                        {filteredChapters.map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100' : 'bg-white'}`}>
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2.5 rounded-2xl ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin' : 'bg-slate-100'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-sm truncate">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100">
                                        <button onClick={() => setViewingFile(ch)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 rounded-xl"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex justify-between items-center text-[9px] font-extrabold uppercase tracking-wider">
                                    <span className={ch.status === FileStatus.COMPLETED ? 'text-emerald-700' : ch.status === FileStatus.PROCESSING ? 'text-sky-700' : 'text-slate-500'}>{ch.status}</span>
                                    {ch.usedModel && <span className="text-slate-400">{ch.usedModel.split('-').slice(-2).join(' ')}</span>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {showFlowOffer && (
                        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-white border-2 border-sky-400 p-6 rounded-[32px] shadow-2xl z-20 flex items-center gap-6 animate-in slide-in-from-bottom-10">
                            <div className="p-3 bg-sky-100 text-sky-600 rounded-2xl"><Sparkles className="w-8 h-8" /></div>
                            <div>
                                <h4 className="font-bold text-lg">Cào xong! Bật luồng tự động?</h4>
                                <p className="text-sm text-slate-500">Hệ thống sẽ tự động dịch & cào tiếp chương mới để bạn rảnh tay.</p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => setShowFlowOffer(false)} className="px-4 py-2 font-bold text-slate-400 hover:bg-slate-50 rounded-xl transition-all">Để sau</button>
                                <button onClick={() => startTranslation(true)} className="px-6 py-3 bg-sky-500 text-white font-bold rounded-xl shadow-lg shadow-sky-100 hover:scale-105 active:scale-95 transition-all">Kích hoạt Auto-Flow</button>
                            </div>
                        </div>
                    )}
                </div>

                <div className="w-96 border-l border-slate-200 bg-white p-8 space-y-8 overflow-y-auto">
                    <section className="space-y-4">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2"><Settings className="w-4 h-4" /> Cấu hình</h4>
                        <div className="space-y-4">
                            <input className="w-full p-3 bg-slate-50 border rounded-xl text-sm" placeholder="Tác giả" value={currentProject.info.author} onChange={e => updateProject(currentProject.id, { info: {...currentProject.info, author: e.target.value} })} />
                            <div className="relative group">
                                <textarea className="w-full h-32 p-3 bg-emerald-50/30 border border-emerald-100 rounded-xl text-xs text-emerald-900 leading-relaxed resize-none focus:ring-2 focus:ring-emerald-200 outline-none" placeholder="Bối cảnh truyện (Context)..." value={currentProject.globalContext} onChange={e => updateProject(currentProject.id, { globalContext: e.target.value })} />
                                <button onClick={handleAnalyzeContext} disabled={isAnalyzing} className="absolute bottom-3 right-3 p-2 bg-white rounded-lg shadow-sm border border-emerald-100 text-emerald-500 hover:scale-110 active:scale-95 transition-all">{isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Brain className="w-4 h-4" />}</button>
                            </div>
                            <textarea className="w-full h-48 p-3 bg-slate-50 border rounded-xl text-[10px] font-mono leading-normal resize-none" placeholder="Từ điển: TừGốc=TừDịch..." value={currentProject.dictionary} onChange={e => updateProject(currentProject.id, { dictionary: e.target.value })} />
                        </div>
                    </section>
                </div>
              </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center p-20 text-center animate-in fade-in">
                <div className="w-24 h-24 bg-sky-100 rounded-[32px] flex items-center justify-center mb-8 shadow-2xl shadow-sky-200/50"><LayoutDashboard className="w-12 h-12 text-sky-500" /></div>
                <h2 className="text-3xl font-bold">Dịch Truyện Chuyên Nghiệp</h2>
                <button onClick={createNewProject} className="mt-8 px-8 py-4 bg-sky-500 text-white rounded-[20px] font-bold shadow-xl shadow-sky-200 hover:-translate-y-1 transition-all flex items-center gap-2"><PlusCircle className="w-5 h-5" /> Dự Án Mới</button>
            </div>
          )}
      </main>

      {showLinkModal && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
              <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95">
                  <div className="p-8">
                      <div className="flex items-center gap-4 mb-8">
                          <div className="p-4 bg-sky-100 text-sky-600 rounded-2xl"><Link2 className="w-6 h-6" /></div>
                          <div><h3 className="text-xl font-bold">Cào Truyện Thông Minh</h3><p className="text-sm text-slate-500">Hỗ trợ lấy nội dung tự động từ URL.</p></div>
                      </div>
                      <div className="space-y-6">
                        <textarea className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none font-mono" placeholder="Dán link chương 1..." value={linkInput} onChange={e => setLinkInput(e.target.value)} />
                        <div className="p-5 bg-slate-50 rounded-3xl border space-y-4">
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-bold">Số lượng chương</span>
                                <input type="number" className="w-20 p-2 bg-white border rounded-xl text-sm text-center font-bold" value={crawlLimit} onChange={e => setCrawlLimit(parseInt(e.target.value) || 1)} />
                            </div>
                            <div className="flex items-center gap-3">
                                <div className={`w-10 h-6 rounded-full transition-all relative cursor-pointer ${autoCrawl ? 'bg-sky-500' : 'bg-slate-300'}`} onClick={() => setAutoCrawl(!autoCrawl)}>
                                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${autoCrawl ? 'left-5' : 'left-1'}`} />
                                </div>
                                <span className="text-xs font-bold text-slate-600">Bật cào tự động</span>
                            </div>
                        </div>
                      </div>
                      {fetchProgress && (
                          <div className="mt-8 space-y-2">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase"><span>Tiến độ: {fetchProgress.current}/{fetchProgress.total}</span></div>
                              <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-sky-500 transition-all duration-300" style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }} /></div>
                          </div>
                      )}
                      <div className="mt-10 flex gap-4">
                          <button onClick={() => setShowLinkModal(false)} className="flex-1 py-4 font-bold text-slate-500">Đóng</button>
                          <button onClick={handleLinkSubmit} disabled={isFetchingLinks || !linkInput} className="flex-[2] py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl disabled:opacity-50 flex items-center justify-center gap-2">
                              {isFetchingLinks ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Bắt Đầu Cào
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {viewingFile && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-10">
             <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-7xl h-full flex flex-col overflow-hidden animate-in zoom-in-95">
                <div className="p-8 border-b border-slate-100 flex items-center justify-between">
                    <h3 className="text-2xl font-bold">{viewingFile.name}</h3>
                    <button onClick={() => setViewingFile(null)} className="p-3 hover:bg-rose-50 rounded-2xl"><X className="w-8 h-8" /></button>
                </div>
                <div className="flex-1 overflow-hidden grid grid-cols-2">
                    <div className="p-10 overflow-y-auto bg-slate-50/50 border-r border-slate-100 font-serif whitespace-pre-wrap">{viewingFile.content}</div>
                    <div className="p-10 overflow-y-auto font-serif text-slate-900 whitespace-pre-wrap">{viewingFile.translatedContent || "Chưa dịch."}</div>
                </div>
             </div>
          </div>
      )}

      <div className="fixed bottom-6 right-6 z-[400] flex flex-col gap-3">
          {toasts.map(t => (
              <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-right backdrop-blur-md ${t.type === 'error' ? 'bg-rose-50/90 border-rose-100 text-rose-600' : t.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-600' : 'bg-white/90 border-slate-200 text-slate-700'}`}>
                  {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
                  <span className="font-bold text-sm">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History, Infinity as InfinityIcon } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(50);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [showFlowOffer, setShowFlowOffer] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);

  const [viewingFile, setViewingFile] = useState<FileItem | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (isProcessing && currentProjectId !== processingProjectIdRef.current) {
        stopTranslation();
        addToast("Dừng dịch dự án cũ", "info");
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) {
      console.error("Save failed", e);
    } finally {
      setIsSaving(false);
    }
  };

  useEffect(() => {
    if (currentProject) {
        persistProject(currentProject);
    }
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
    addToast("Đã tạo dự án truyện mới", "success");
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const deleteProjectAction = async (id: string) => {
    if (window.confirm("Bạn chắc chắn muốn xóa dự án này?")) {
        await deleteProject(id);
        setProjects(prev => prev.filter(p => p.id !== id));
        if (currentProjectId === id) setCurrentProjectId(null);
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    updateProject(currentProject.id, {
        chapters: currentProject.chapters.filter(c => c.id !== chapterId)
    });
  };

  const clearAllChapters = () => {
    if (!currentProject || !window.confirm("Xóa toàn bộ chương?")) return;
    updateProject(currentProject.id, { chapters: [] });
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) return;

    setIsFetchingLinks(true);
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;
    let lastNextUrl: string | null = null;

    try {
      if (autoCrawl && urls.length === 1) {
          let currentUrl: string | null = urls[0];
          setFetchProgress({ current: 0, total: crawlLimit });

          for (let i = 0; i < crawlLimit; i++) {
              if (!currentUrl) break;
              const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());

              if (!isDuplicate) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
              }
              lastNextUrl = nextUrl;
              setFetchProgress({ current: i + 1, total: crawlLimit });
              currentUrl = nextUrl;
              updateProject(currentProject.id, { chapters: [...updatedChapters], lastCrawlUrl: lastNextUrl || undefined });
              await new Promise(r => setTimeout(r, 800));
          }
      } else {
          setFetchProgress({ current: 0, total: urls.length });
          for (let i = 0; i < urls.length; i++) {
              const { title, content, nextUrl } = await fetchContentFromUrl(urls[i]);
              const isDuplicate = updatedChapters.some(c => c.name.trim().toLowerCase() === title.trim().toLowerCase());
              if (!isDuplicate) {
                updatedChapters.push({ id: crypto.randomUUID(), name: title, content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: content.length, remainingRawCharCount: 0 });
                addedCount++;
              }
              lastNextUrl = nextUrl;
              setFetchProgress({ current: i + 1, total: urls.length });
          }
          updateProject(currentProject.id, { chapters: updatedChapters, lastCrawlUrl: lastNextUrl || undefined });
      }
      if (addedCount > 0) setShowFlowOffer(true);
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally {
        setIsFetchingLinks(false);
        setFetchProgress(null);
        setShowLinkModal(false);
        setLinkInput("");
    }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));

    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch!", "info");
        return;
    }

    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    addToast(continuous ? "Kích hoạt Chế độ Luồng Liên Tục: Dịch & Cào tự động" : "Bắt đầu dịch tuần tự", "success");
    setShowFlowOffer(false);
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;

    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        addToast("Đã xuất file gốc tiếng Trung", "success");
        return;
    }

    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) {
      addToast("Chưa có chương nào hoàn thành!", "error");
      return;
    }

    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${currentProject.info.title}.epub`;
        a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
      addToast("Xuất file thành công", "success");
    } catch (e: any) { addToast("Lỗi: " + e.message, "error"); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("Lập bối cảnh thành công", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  // Vòng lặp Continuous Flow: Cào tự động khi hàng đợi vơi
  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;

      const bufferLow = processingQueue.length < BATCH_FILE_LIMIT;
      if (bufferLow && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1000));
                  }

                  if (newChapters.length > 0) {
                      const updated = [...currentProject.chapters, ...newChapters];
                      updateProject(currentProject.id, { chapters: updated, lastCrawlUrl: nextUrl || undefined });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                      addToast(`Auto-flow: Đã cào thêm ${newChapters.length} chương mới`, "info");
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    if (processingProjectIdRef.current !== currentProjectId) return;

    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);

        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }

        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
