                                <textarea className="w-full h-48 p-3 bg-slate-50 border rounded-xl text-[10px] font-mono leading-normal resize-none focus:ring-2 focus:ring-sky-100 outline-none" placeholder="TênGốc=TênDịch..." value={currentProject.dictionary} onChange={e => updateProject(currentProject.id, { dictionary: e.target.value })} />
