                        </div>
                      </div>
                      {fetchProgress && (
                          <div className="mt-8 space-y-2">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase px-1">
                                  <span>Đang cào: {fetchProgress.current}/{fetchProgress.total}</span>
                                  <button onClick={() => { stopCrawlRef.current = true; setIsFetchingLinks(false); }} className="text-rose-500 font-bold">Dừng cào</button>
                              </div>
                              <div className="w-full h-2.5 bg-slate-100 rounded-full overflow-hidden shadow-inner"><div className="h-full bg-sky-500 transition-all duration-300" style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }} /></div>
                          </div>
                      )}
                      <div className="mt-10 flex gap-4">
                          <button onClick={() => { stopCrawlRef.current = true; setShowLinkModal(false); }} className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-all">Hủy</button>
                          <button onClick={handleLinkSubmit} disabled={isFetchingLinks || !linkInput} className="flex-[2] py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-sky-600 transition-all active:scale-95">
                              {isFetchingLinks ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Bắt Đầu
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Context Setup Modal */}
      {showContextSetup && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[250] flex items-center justify-center p-4">
              <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95">
                  <div className="p-10 space-y-6">
                      <div className="flex items-center gap-4">
                          <div className="p-4 bg-emerald-100 text-emerald-600 rounded-3xl"><Settings2 className="w-8 h-8" /></div>
                          <div>
                              <h3 className="text-2xl font-bold tracking-tight">Cài đặt Context</h3>
                              <p className="text-sm text-slate-500">Để bản dịch chất lượng, AI cần biết bối cảnh truyện.</p>
                          </div>
                      </div>
                      <div className="space-y-4">
                          <div className="p-6 bg-amber-50 border border-amber-100 rounded-3xl flex gap-4">
                              <AlertTriangle className="w-6 h-6 text-amber-500 shrink-0" />
                              <p className="text-xs text-amber-700 leading-relaxed font-medium">Bạn chưa cấu hình bối cảnh cho truyện này. AI có thể dịch sai tên nhân vật hoặc nhầm lẫn xưng hô nếu thiếu context.</p>
                          </div>
                          <div className="space-y-2">
                            <label className="text-[10px] font-bold text-slate-500 uppercase px-1">Nhập thông tin bối cảnh</label>
                            <textarea 
                                className="w-full h-48 p-4 bg-slate-50 border rounded-3xl text-sm focus:ring-2 focus:ring-sky-200 outline-none transition-all" 
                                placeholder="Dán bối cảnh hoặc từ điển quan trọng vào đây..."
                                value={currentProject?.globalContext}
                                onChange={(e) => updateProject(currentProject!.id, { globalContext: e.target.value })}
                            />
                          </div>
                      </div>
                      <div className="flex gap-4">
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 font-bold text-slate-400 hover:bg-slate-50 rounded-2xl">Dịch thô</button>
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 hover:scale-105 transition-all">Lưu & Dịch</button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Reader Modal */}
      {viewingFile && (
          <div className={`fixed inset-0 z-[300] flex flex-col animate-in fade-in duration-300 ${readerSettings.bgColor}`}>
             <header className="h-16 px-8 border-b flex items-center justify-between shrink-0 bg-black/5">
                <h3 className="font-bold text-lg truncate max-w-lg">{viewingFile.name}</h3>
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-3">
                        {BG_COLORS.map(bg => (
                            <button key={bg.name} onClick={() => setReaderSettings(s => ({...s, bgColor: bg.code}))} className={`w-8 h-8 rounded-full border shadow-sm ${bg.code.split(' ')[0]} ${readerSettings.bgColor.includes(bg.code.split(' ')[0]) ? 'ring-2 ring-sky-500' : ''}`} title={bg.name} />
                        ))}
                    </div>
                    <div className="h-6 w-px bg-black/10" />
                    <div className="flex items-center gap-2">
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.max(12, s.fontSize - 2)}))} className="p-2 hover:bg-black/10 rounded-lg"><Type className="w-4 h-4" /></button>
                        <span className="text-xs font-bold w-6 text-center">{readerSettings.fontSize}</span>
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.min(32, s.fontSize + 2)}))} className="p-2 hover:bg-black/10 rounded-lg"><Type className="w-5 h-5" /></button>
                    </div>
                    <button onClick={() => {
                        updateProject(currentProject!.id, { readerSettings });
                        setViewingFile(null);
                    }} className="p-2 hover:bg-rose-100 hover:text-rose-600 rounded-xl transition-all"><X className="w-6 h-6" /></button>
                </div>
             </header>
             <div className="flex-1 overflow-hidden grid grid-cols-1 lg:grid-cols-2">
                <div className="p-12 overflow-y-auto font-serif border-r border-black/5 opacity-60 hover:opacity-100 transition-opacity">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className="max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-sky-200">{viewingFile.content}</div>
                </div>
                <div className="p-12 overflow-y-auto">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className={`max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-emerald-200 ${readerSettings.fontFamily}`}>{viewingFile.translatedContent || <div className="italic text-slate-400">Chương này chưa được dịch.</div>}</div>
                </div>
             </div>
          </div>
      )}

      {/* Global Toasts */}
      <div className="fixed bottom-6 right-6 z-[400] flex flex-col gap-3">
          {toasts.map(t => (
              <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-right backdrop-blur-md ${t.type === 'error' ? 'bg-rose-50/90 border-rose-100 text-rose-600' : 'bg-white/90 border-slate-200 text-slate-700'}`}>
                  {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
                  <span className="font-bold text-sm">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History, Infinity as InfinityIcon, PlayCircle, StopCircle, Settings2, Palette as PaletteIcon, Type, MousePointer2 } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject, ReaderSettings } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const BG_COLORS = [
    { name: 'Trắng', code: 'bg-white text-slate-900' },
    { name: 'Giấy cũ', code: 'bg-[#f4ecd8] text-slate-900' },
    { name: 'Xanh dịu', code: 'bg-[#e8f5e9] text-slate-900' },
    { name: 'Xám', code: 'bg-[#f5f5f5] text-slate-900' },
    { name: 'Tối', code: 'bg-slate-900 text-slate-300' }
];

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [showContextSetup, setShowContextSetup] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(10);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [showFlowOffer, setShowFlowOffer] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);
  const [isFlowMinimized, setIsFlowMinimized] = useState<boolean>(false);

  const stopCrawlRef = useRef<boolean>(false);
  const [viewingFile, setViewingFile] = useState<FileItem | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif'
  });

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (currentProject?.readerSettings) {
        setReaderSettings(currentProject.readerSettings);
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) {
        addToast("Vui lòng dán link truyện hợp lệ", "warning");
        return;
    }

    setIsFetchingLinks(true);
    stopCrawlRef.current = false;
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;

    try {
      let currentUrl: string | null = urls[0];
      setFetchProgress({ current: 0, total: crawlLimit });

      for (let i = 0; i < crawlLimit; i++) {
          if (!currentUrl || stopCrawlRef.current) break;

          try {
            const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
            if (!updatedChapters.some(c => c.name === title)) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
            }
            setFetchProgress({ current: i + 1, total: crawlLimit });
            currentUrl = nextUrl;
            updateProject(currentProject.id, { 
                chapters: [...updatedChapters], 
                lastCrawlUrl: currentUrl || undefined 
            });
            await new Promise(r => setTimeout(r, 1200));
          } catch (fetchErr: any) {
              if (autoCrawl) {
                  addToast("Dừng cào do gặp lỗi ở URL: " + currentUrl, "error");
                  break;
              } else {
                  addToast("Lỗi cào 1 chương, tiếp tục...", "warning");
              }
          }
      }

      if (addedCount > 0) {
          addToast(`Đã cào thêm ${addedCount} chương`, "success");
          setShowFlowOffer(true);
          setIsFlowMinimized(false);
      }
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsFetchingLinks(false); 
        setFetchProgress(null); 
        setShowLinkModal(false); 
        setLinkInput("");
    }
  };

  const clearAllChapters = () => {
    if (!currentProject) return;
    if (window.confirm("Bạn có chắc muốn xóa tất cả các chương?")) {
      updateProject(currentProject.id, { chapters: [] });
      addToast("Đã xóa toàn bộ chương", "success");
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    const updatedChapters = currentProject.chapters.filter(c => c.id !== chapterId);
    updateProject(currentProject.id, { chapters: updatedChapters });
    setProcessingQueue(prev => prev.filter(id => id !== chapterId));
  };

  const handleStartTranslateRequest = () => {
      if (!currentProject) return;
      if (!currentProject.globalContext || currentProject.globalContext.length < 50) {
          setShowContextSetup(true);
      } else {
          startTranslation(false);
      }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    setShowContextSetup(false);
    if (continuous) {
        setShowFlowOffer(true);
        setIsFlowMinimized(true);
    }
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;
    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        return;
    }
    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) return;
    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `${currentProject.info.title}.epub`; a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
    } catch (e: any) { addToast(e.message, 'error'); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("AI đã lập bối cảnh truyện", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;
      if (processingQueue.length < BATCH_FILE_LIMIT && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1200));
                  }
                  if (newChapters.length > 0) {
                      updateProject(currentProject.id, { 
                          chapters: [...currentProject.chapters, ...newChapters], 
                          lastCrawlUrl: nextUrl || undefined 
                      });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);
        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }
        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      <aside className="w-80 bg-white border-r border-slate-200 flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg">Dịch Truyện Pro</h1>
            </div>
            <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl transition-all"><PlusCircle className="w-6 h-6" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between items-center">
                <span>Dự án ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => setCurrentProjectId(p.id)} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProject(p.id).then(() => setProjects(prev => prev.filter(x => x.id !== p.id))); }} className="opacity-0 group-hover:opacity-100 p-1.5 hover:text-rose-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                </div>
            ))}
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-6">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <input className="bg-transparent font-bold text-xl outline-none" value={currentProject.info.title} onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })} />
                            {isProcessing && isContinuousFlow && <InfinityIcon className="w-5 h-5 text-sky-500 animate-pulse" />}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-slate-500">
                            <span className="flex items-center gap-1"><Book className="w-3.5 h-3.5" /> {currentProject.chapters.length} chương</span>
                            <span className="text-emerald-600 font-semibold"><CheckCircle className="w-3.5 h-3.5 inline mr-1" /> {currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length} xong</span>
                        </div>
                      </div>
                  </div>
                  <div className="flex items-center gap-2">
                      <button onClick={() => setShowLinkModal(true)} className="flex items-center gap-2 px-4 py-2 border rounded-xl font-bold text-sm hover:bg-sky-50">
                          <Link2 className="w-4 h-4 text-sky-500" /> Cào truyện
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : handleStartTranslateRequest()} className={`px-6 py-2 rounded-xl font-bold text-sm shadow-lg ${isProcessing ? 'bg-rose-500 text-white shadow-rose-100' : 'bg-sky-500 text-white shadow-sky-100'}`}>
                          {isProcessing ? 'Dừng dịch' : 'Dịch dự án'}
                      </button>
                      <div className="h-8 w-px bg-slate-200 mx-1" />
                      <button onClick={() => handleExport('epub')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất EPUB"><Download className="w-5 h-5" /></button>
                      <button onClick={() => handleExport('raw')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất File Gốc"><Languages className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden">
                <div className="flex-1 flex flex-col p-8 overflow-hidden relative">
                    <div className="mb-6 flex items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-sky-200" placeholder="Tìm chương..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                        </div>
                        <button onClick={clearAllChapters} className="text-rose-500 font-bold text-xs hover:underline bg-rose-50 px-3 py-2 rounded-lg">Xóa tất cả chương</button>
                    </div>

                    <div className="flex-1 overflow-y-auto grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-4 content-start pb-20">
                        {currentProject.chapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true })).map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100 shadow-inner' : 'bg-white'}`}>
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2.5 rounded-2xl ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin shadow-lg shadow-sky-200' : 'bg-slate-100 text-slate-400'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-sm truncate">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setViewingFile(ch)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl" title="Đọc chương"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 rounded-xl"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex justify-between items-center text-[9px] font-extrabold uppercase tracking-wider">
                                    <span className={ch.status === FileStatus.COMPLETED ? 'text-emerald-700' : ch.status === FileStatus.PROCESSING ? 'text-sky-700' : 'text-slate-500'}>{ch.status}</span>
                                    {ch.usedModel && <span className="text-slate-400 font-medium">{ch.usedModel.split('-').slice(-2).join(' ')}</span>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Menu Luồng Tự Động (Auto-Flow Status Menu) - Di chuyển về góc phải và thu nhỏ */}
                    {showFlowOffer && (
                        <div className={`fixed bottom-10 right-10 z-40 transition-all duration-300 ease-in-out ${isFlowMinimized ? 'w-14 h-14' : 'w-72 bg-white border-2 border-sky-400 rounded-3xl shadow-2xl p-5'}`}>
                            {isFlowMinimized ? (
                                <button 
                                    onClick={() => setIsFlowMinimized(false)}
                                    className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-all hover:scale-110 active:scale-95 ${isContinuousFlow ? 'bg-sky-500 text-white animate-pulse' : 'bg-white text-sky-500 border border-sky-100'}`}
                                    title={isContinuousFlow ? "Auto-Flow đang chạy..." : "Mở menu Auto-Flow"}
                                >
                                    {isContinuousFlow ? <InfinityIcon className="w-6 h-6" /> : <Zap className="w-6 h-6" />}
                                </button>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <div className="p-2 bg-sky-50 text-sky-500 rounded-xl"><Sparkles className="w-4 h-4" /></div>
                                            <span className="font-bold text-sm tracking-tight">Auto-Flow</span>
                                        </div>
                                        <button onClick={() => setIsFlowMinimized(true)} className="p-1 text-slate-400 hover:text-slate-600 rounded-lg transition-all"><ChevronDown className="w-4 h-4" /></button>
                                    </div>

                                    <div className="bg-slate-50 rounded-2xl p-3 border border-slate-100">
                                        <p className="text-[11px] text-slate-500 leading-relaxed font-medium">
                                            {isContinuousFlow 
                                                ? "Đang tự động cào chương mới sau mỗi 2 chương dịch xong." 
                                                : "Hệ thống sẽ tự động dịch & cào chương mới để bạn rảnh tay."}
                                        </p>
                                    </div>

                                    <div className="flex gap-2">
                                        {isContinuousFlow ? (
                                            <button onClick={() => stopTranslation()} className="w-full py-2.5 bg-rose-50 text-rose-500 font-bold text-xs rounded-xl hover:bg-rose-100 transition-all flex items-center justify-center gap-1.5">
                                                <StopCircle className="w-3.5 h-3.5" /> Dừng Auto-Flow
                                            </button>
                                        ) : (
                                            <>
                                                <button onClick={() => setIsFlowMinimized(true)} className="flex-1 py-2.5 text-slate-400 font-bold text-xs hover:bg-slate-50 rounded-xl transition-all">Bỏ qua</button>
                                                <button onClick={() => startTranslation(true)} className="flex-[1.5] py-2.5 bg-sky-500 text-white font-bold text-xs rounded-xl shadow-lg shadow-sky-100 hover:scale-105 active:scale-95 transition-all">Bật Auto-Flow</button>
                                            </>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="w-96 border-l border-slate-200 bg-white p-8 space-y-8 overflow-y-auto">
                    <section className="space-y-4">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2"><Settings className="w-4 h-4" /> Cấu hình truyện</h4>
                        <div className="space-y-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500">TÁC GIẢ</label>
                                <input className="w-full p-3 bg-slate-50 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-sky-100" value={currentProject.info.author} onChange={e => updateProject(currentProject.id, { info: {...currentProject.info, author: e.target.value} })} />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase flex items-center justify-between">
                                    <span>Kinh thánh truyện (Context)</span>
                                    {isAnalyzing && <Loader2 className="w-3 h-3 animate-spin" />}
                                </label>
                                <div className="relative group">
                                    <textarea className="w-full h-32 p-3 bg-emerald-50/30 border border-emerald-100 rounded-xl text-xs text-emerald-900 leading-relaxed resize-none focus:ring-2 focus:ring-emerald-200 outline-none" placeholder="Thông tin bối cảnh, nhân vật quan trọng..." value={currentProject.globalContext} onChange={e => updateProject(currentProject.id, { globalContext: e.target.value })} />
                                    <button onClick={handleAnalyzeContext} disabled={isAnalyzing} className="absolute bottom-3 right-3 p-2 bg-white rounded-lg shadow-sm border border-emerald-100 text-emerald-500 hover:scale-110 active:scale-95 transition-all">{isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Brain className="w-4 h-4" />}</button>
                                </div>
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Từ điển riêng</label>
                                <textarea className="w-full h-48 p-3 bg-slate-50 border rounded-xl text-[10px] font-mono leading-normal resize-none focus:ring-2 focus:ring-sky-100 outline-none" placeholder="TênGốc=TênDịch..." value={currentProject.dictionary} onChange={e => updateProject(currentProject.id, { dictionary: e.target.value })} />
                            </div>
                        </div>
                    </section>
                </div>
              </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center p-20 text-center animate-in fade-in">
                <div className="w-24 h-24 bg-sky-100 rounded-[32px] flex items-center justify-center mb-8 shadow-2xl shadow-sky-200/50"><LayoutDashboard className="w-12 h-12 text-sky-500" /></div>
                <h2 className="text-3xl font-bold">Quản lý Dự án Truyện</h2>
                <button onClick={createNewProject} className="mt-8 px-8 py-4 bg-sky-500 text-white rounded-[20px] font-bold shadow-xl shadow-sky-200 hover:-translate-y-1 transition-all flex items-center gap-2"><PlusCircle className="w-5 h-5" /> Dự Án Mới</button>
            </div>
          )}
      </main>

      {showLinkModal && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
              <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95">
                  <div className="p-8">
                      <div className="flex items-center gap-4 mb-8">
                          <div className="p-4 bg-sky-100 text-sky-600 rounded-2xl"><Link2 className="w-6 h-6" /></div>
                          <div><h3 className="text-xl font-bold">Cào Truyện Thông Minh</h3><p className="text-sm text-slate-500">Lấy nội dung tự động từ URL nguồn.</p></div>
                      </div>
                      <div className="space-y-6">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase px-1">Link chương 1</label>
                            <textarea className="w-full h-24 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none font-mono focus:ring-2 focus:ring-sky-300" placeholder="https://..." value={linkInput} onChange={e => setLinkInput(e.target.value)} />
                        </div>
                        <div className="p-5 bg-slate-50 rounded-3xl border space-y-4">
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-bold">Số lượng chương</span>
                                <input type="number" className="w-20 p-2 bg-white border rounded-xl text-sm text-center font-bold" value={crawlLimit} onChange={e => setCrawlLimit(parseInt(e.target.value) || 1)} />
                            </div>
                            <div className="flex items-center justify-between">
                                <span className="text-xs font-bold text-slate-600">Dừng cào nếu gặp lỗi</span>
                                <div className={`w-10 h-6 rounded-full transition-all relative cursor-pointer ${autoCrawl ? 'bg-sky-500' : 'bg-slate-300'}`} onClick={() => setAutoCrawl(!autoCrawl)}>
                                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${autoCrawl ? 'left-5' : 'left-1'}`} />
                                </div>
                            </div>
                        </div>
                      </div>
                      {fetchProgress && (
                          <div className="mt-8 space-y-2">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase px-1">
                                  <span>Đang cào: {fetchProgress.current}/{fetchProgress.total}</span>
                                  <button onClick={() => { stopCrawlRef.current = true; setIsFetchingLinks(false); }} className="text-rose-500 font-bold">Dừng cào</button>
                              </div>
                              <div className="w-full h-2.5 bg-slate-100 rounded-full overflow-hidden shadow-inner"><div className="h-full bg-sky-500 transition-all duration-300" style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }} /></div>
                          </div>
                      )}
                      <div className="mt-10 flex gap-4">
                          <button onClick={() => { stopCrawlRef.current = true; setShowLinkModal(false); }} className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-all">Hủy</button>
                          <button onClick={handleLinkSubmit} disabled={isFetchingLinks || !linkInput} className="flex-[2] py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-sky-600 transition-all active:scale-95">
                              {isFetchingLinks ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Bắt Đầu
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {showContextSetup && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[250] flex items-center justify-center p-4">
              <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95">
                  <div className="p-10 space-y-6">
                      <div className="flex items-center gap-4">
                          <div className="p-4 bg-emerald-100 text-emerald-600 rounded-3xl"><Settings2 className="w-8 h-8" /></div>
                          <div>
                              <h3 className="text-2xl font-bold tracking-tight">Cài đặt Context</h3>
                              <p className="text-sm text-slate-500">Để bản dịch chất lượng, AI cần biết bối cảnh truyện.</p>
                          </div>
                      </div>
                      <div className="space-y-4">
                          <div className="p-6 bg-amber-50 border border-amber-100 rounded-3xl flex gap-4">
                              <AlertTriangle className="w-6 h-6 text-amber-500 shrink-0" />
                              <p className="text-xs text-amber-700 leading-relaxed font-medium">Bạn chưa cấu hình bối cảnh cho truyện này. AI có thể dịch sai tên nhân vật hoặc nhầm lẫn xưng hô nếu thiếu context.</p>
                          </div>
                          <div className="space-y-2">
                            <label className="text-[10px] font-bold text-slate-500 uppercase px-1">Nhập thông tin bối cảnh</label>
                            <textarea 
                                className="w-full h-48 p-4 bg-slate-50 border rounded-3xl text-sm focus:ring-2 focus:ring-sky-200 outline-none transition-all" 
                                placeholder="Dán bối cảnh hoặc từ điển quan trọng vào đây..."
                                value={currentProject?.globalContext}
                                onChange={(e) => updateProject(currentProject!.id, { globalContext: e.target.value })}
                            />
                          </div>
                      </div>
                      <div className="flex gap-4">
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 font-bold text-slate-400 hover:bg-slate-50 rounded-2xl">Dịch thô</button>
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 hover:scale-105 transition-all">Lưu & Dịch</button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {viewingFile && (
          <div className={`fixed inset-0 z-[300] flex flex-col animate-in fade-in duration-300 ${readerSettings.bgColor}`}>
             <header className="h-16 px-8 border-b flex items-center justify-between shrink-0 bg-black/5">
                <h3 className="font-bold text-lg truncate max-w-lg">{viewingFile.name}</h3>
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-3">
                        {BG_COLORS.map(bg => (
                            <button key={bg.name} onClick={() => setReaderSettings(s => ({...s, bgColor: bg.code}))} className={`w-8 h-8 rounded-full border shadow-sm ${bg.code.split(' ')[0]} ${readerSettings.bgColor.includes(bg.code.split(' ')[0]) ? 'ring-2 ring-sky-500' : ''}`} title={bg.name} />
                        ))}
                    </div>
                    <div className="h-6 w-px bg-black/10" />
                    <div className="flex items-center gap-2">
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.max(12, s.fontSize - 2)}))} className="p-2 hover:bg-black/10 rounded-lg"><Type className="w-4 h-4" /></button>
                        <span className="text-xs font-bold w-6 text-center">{readerSettings.fontSize}</span>
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.min(32, s.fontSize + 2)}))} className="p-2 hover:bg-black/10 rounded-lg"><Type className="w-5 h-5" /></button>
                    </div>
                    <button onClick={() => {
                        updateProject(currentProject!.id, { readerSettings });
                        setViewingFile(null);
                    }} className="p-2 hover:bg-rose-100 hover:text-rose-600 rounded-xl transition-all"><X className="w-6 h-6" /></button>
                </div>
             </header>
             <div className="flex-1 overflow-hidden grid grid-cols-1 lg:grid-cols-2">
                <div className="p-12 overflow-y-auto font-serif border-r border-black/5 opacity-60 hover:opacity-100 transition-opacity">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className="max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-sky-200">{viewingFile.content}</div>
                </div>
                <div className="p-12 overflow-y-auto">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className={`max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-emerald-200 ${readerSettings.fontFamily}`}>{viewingFile.translatedContent || <div className="italic text-slate-400">Chương này chưa được dịch.</div>}</div>
                </div>
             </div>
          </div>
      )}

      <div className="fixed bottom-6 right-6 z-[400] flex flex-col gap-3">
          {toasts.map(t => (
              <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-right backdrop-blur-md ${t.type === 'error' ? 'bg-rose-50/90 border-rose-100 text-rose-600' : 'bg-white/90 border-slate-200 text-slate-700'}`}>
                  {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
                  <span className="font-bold text-sm">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
};

export default App;

export enum FileStatus {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  REPAIRING = 'REPAIRING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR',
}

export interface FileItem {
  id: string;
  name: string;
  content: string;
  translatedContent: string | null;
  status: FileStatus;
  errorMessage?: string;
  retryCount: number;
  originalCharCount: number;
  remainingRawCharCount: number;
  usedModel?: string;
}

export interface StoryInfo {
  title: string;
  author: string;
  languages: string[];
  genres: string[];
  mcPersonality: string[];
  worldSetting: string[];
  sectFlow: string[];
  contextNotes?: string;
}

export interface ReaderSettings {
  fontSize: number;
  bgColor: string;
  fontFamily: string;
  ttsVoice?: string;
  ttsRate?: number;
}

export interface StoryProject {
  id: string;
  info: StoryInfo;
  chapters: FileItem[];
  promptTemplate: string;
  dictionary: string;
  globalContext: string;
  createdAt: number;
  lastModified: number;
  lastCrawlUrl?: string;
  readerSettings?: ReaderSettings;
}

export interface ModelQuota {
  id: string;
  name: string;
  rpmLimit: number;
  rpdLimit: number;
  priority: number;
  maxOutputTokens: number;
}

export interface ModelUsage {
  requestsToday: number;
  lastResetDate: string;
  recentRequests: number[];
  cooldownUntil: number;
  isDepleted: boolean;
}

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History, Infinity as InfinityIcon, PlayCircle, StopCircle, Settings2, Palette as PaletteIcon, Type, MousePointer2, Volume2, VolumeX, SkipBack, SkipForward, ListOrdered } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject, ReaderSettings } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const BG_COLORS = [
    { name: 'Trắng', code: 'bg-white text-slate-900' },
    { name: 'Giấy cũ', code: 'bg-[#f4ecd8] text-slate-900' },
    { name: 'Xanh dịu', code: 'bg-[#e8f5e9] text-slate-900' },
    { name: 'Xám', code: 'bg-[#f5f5f5] text-slate-900' },
    { name: 'Tối', code: 'bg-slate-900 text-slate-300' }
];

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [showContextSetup, setShowContextSetup] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(10);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [showFlowOffer, setShowFlowOffer] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);
  const [isFlowMinimized, setIsFlowMinimized] = useState<boolean>(false);

  const stopCrawlRef = useRef<boolean>(false);
  const [viewingFileId, setViewingFileId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif',
      ttsRate: 1.0
  });

  // TTS States
  const [isTTSPlaying, setIsTTSPlaying] = useState<boolean>(false);
  const [availableVoices, setAvailableVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoiceName, setSelectedVoiceName] = useState<string | null>(null);
  const currentUtteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  useEffect(() => {
    const loadVoices = () => {
      const voices = window.speechSynthesis.getVoices();
      setAvailableVoices(voices);
      if (voices.length > 0 && !selectedVoiceName) {
          const viVoice = voices.find(v => v.lang.includes('vi')) || voices[0];
          setSelectedVoiceName(viVoice.name);
      }
    };
    loadVoices();
    window.speechSynthesis.onvoiceschanged = loadVoices;
  }, [selectedVoiceName]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (currentProject?.readerSettings) {
        setReaderSettings(currentProject.readerSettings);
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) {
        addToast("Vui lòng dán link truyện hợp lệ", "warning");
        return;
    }

    setIsFetchingLinks(true);
    stopCrawlRef.current = false;
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;

    try {
      let currentUrl: string | null = urls[0];
      setFetchProgress({ current: 0, total: crawlLimit });

      for (let i = 0; i < crawlLimit; i++) {
          if (!currentUrl || stopCrawlRef.current) break;

          try {
            const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
            if (!updatedChapters.some(c => c.name === title)) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
            }
            setFetchProgress({ current: i + 1, total: crawlLimit });
            currentUrl = nextUrl;
            updateProject(currentProject.id, { 
                chapters: [...updatedChapters], 
                lastCrawlUrl: currentUrl || undefined 
            });
            await new Promise(r => setTimeout(r, 1200));
          } catch (fetchErr: any) {
              if (autoCrawl) {
                  addToast("Dừng cào do gặp lỗi ở URL: " + currentUrl, "error");
                  break;
              } else {
                  addToast("Lỗi cào 1 chương, tiếp tục...", "warning");
              }
          }
      }

      if (addedCount > 0) {
          addToast(`Đã cào thêm ${addedCount} chương`, "success");
          setShowFlowOffer(true);
          setIsFlowMinimized(false);
      }
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsFetchingLinks(false); 
        setFetchProgress(null); 
        setShowLinkModal(false); 
        setLinkInput("");
    }
  };

  const clearAllChapters = () => {
    if (!currentProject) return;
    if (window.confirm("Bạn có chắc muốn xóa tất cả các chương?")) {
      updateProject(currentProject.id, { chapters: [] });
      addToast("Đã xóa toàn bộ chương", "success");
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    const updatedChapters = currentProject.chapters.filter(c => c.id !== chapterId);
    updateProject(currentProject.id, { chapters: updatedChapters });
    setProcessingQueue(prev => prev.filter(id => id !== chapterId));
  };

  const handleStartTranslateRequest = () => {
      if (!currentProject) return;
      if (!currentProject.globalContext || currentProject.globalContext.length < 50) {
          setShowContextSetup(true);
      } else {
          startTranslation(false);
      }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    setShowContextSetup(false);
    if (continuous) {
        setShowFlowOffer(true);
        setIsFlowMinimized(true);
    }
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;
    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        return;
    }
    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) return;
    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `${currentProject.info.title}.epub`; a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
    } catch (e: any) { addToast(e.message, 'error'); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("AI đã lập bối cảnh truyện", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;
      if (processingQueue.length < BATCH_FILE_LIMIT && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1200));
                  }
                  if (newChapters.length > 0) {
                      updateProject(currentProject.id, { 
                          chapters: [...currentProject.chapters, ...newChapters], 
                          lastCrawlUrl: nextUrl || undefined 
                      });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);
        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }
        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  // Reader Navigation Logic
  const sortedChapters = useMemo(() => {
    if (!currentProject) return [];
    return [...currentProject.chapters].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject]);

  const viewingChapter = useMemo(() => {
    return sortedChapters.find(c => c.id === viewingFileId) || null;
  }, [sortedChapters, viewingFileId]);

  const handleNextChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex < sortedChapters.length - 1) {
        setViewingFileId(sortedChapters[currentIndex + 1].id);
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  const handlePrevChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex > 0) {
        setViewingFileId(sortedChapters[currentIndex - 1].id);
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  // TTS Control Logic
  const stopTTS = useCallback(() => {
    window.speechSynthesis.cancel();
    setIsTTSPlaying(false);
    currentUtteranceRef.current = null;
  }, []);

  const playTTS = useCallback((text: string) => {
    if (!text) return;
    stopTTS();

    // Split text into smaller chunks for better synthesis stability
    const chunks = text.split('\n').filter(line => line.trim().length > 0);
    let currentChunkIndex = 0;

    const speakChunk = () => {
        if (currentChunkIndex >= chunks.length) {
            const hasNext = handleNextChapter();
            if (!hasNext) {
                stopTTS();
                addToast("Đã đọc xong toàn bộ chương hiện có.", "success");
            }
            return;
        }

        const utterance = new SpeechSynthesisUtterance(chunks[currentChunkIndex]);
        const voice = availableVoices.find(v => v.name === selectedVoiceName);
        if (voice) utterance.voice = voice;
        utterance.rate = readerSettings.ttsRate || 1.0;

        utterance.onend = () => {
            currentChunkIndex++;
            speakChunk();
        };

        utterance.onerror = (e) => {
            console.error("TTS Error:", e);
            stopTTS();
        };

        currentUtteranceRef.current = utterance;
        window.speechSynthesis.speak(utterance);
    };

    setIsTTSPlaying(true);
    speakChunk();
  }, [availableVoices, selectedVoiceName, readerSettings.ttsRate, handleNextChapter, stopTTS]);

  // Auto-play TTS on chapter change if it was already playing
  useEffect(() => {
      if (isTTSPlaying && viewingChapter?.translatedContent) {
          playTTS(viewingChapter.translatedContent);
      }
  }, [viewingFileId]);

  const stats = useMemo(() => {
      if (!currentProject) return { total: 0, done: 0 };
      return { total: currentProject.chapters.length, done: currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length };
  }, [currentProject]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      {/* Sidebar */}
      <aside className="w-80 bg-white border-r border-slate-200 flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg">Dịch Truyện Pro</h1>
            </div>
            <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl transition-all"><PlusCircle className="w-6 h-6" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between items-center">
                <span>Dự án ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => setCurrentProjectId(p.id)} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProject(p.id).then(() => setProjects(prev => prev.filter(x => x.id !== p.id))); }} className="opacity-0 group-hover:opacity-100 p-1.5 hover:text-rose-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                </div>
            ))}
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-6">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <input className="bg-transparent font-bold text-xl outline-none" value={currentProject.info.title} onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })} />
                            {isProcessing && isContinuousFlow && <InfinityIcon className="w-5 h-5 text-sky-500 animate-pulse" />}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-slate-500">
                            <span className="flex items-center gap-1"><Book className="w-3.5 h-3.5" /> {currentProject.chapters.length} chương</span>
                            <span className="text-emerald-600 font-semibold"><CheckCircle className="w-3.5 h-3.5 inline mr-1" /> {stats.done} xong</span>
                        </div>
                      </div>
                  </div>
                  <div className="flex items-center gap-2">
                      <button onClick={() => setShowLinkModal(true)} className="flex items-center gap-2 px-4 py-2 border rounded-xl font-bold text-sm hover:bg-sky-50">
                          <Link2 className="w-4 h-4 text-sky-500" /> Cào truyện
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : handleStartTranslateRequest()} className={`px-6 py-2 rounded-xl font-bold text-sm shadow-lg ${isProcessing ? 'bg-rose-500 text-white shadow-rose-100' : 'bg-sky-500 text-white shadow-sky-100'}`}>
                          {isProcessing ? 'Dừng dịch' : 'Dịch dự án'}
                      </button>
                      <div className="h-8 w-px bg-slate-200 mx-1" />
                      <button onClick={() => handleExport('epub')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất EPUB"><Download className="w-5 h-5" /></button>
                      <button onClick={() => handleExport('raw')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất File Gốc"><Languages className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden">
                <div className="flex-1 flex flex-col p-8 overflow-hidden relative">
                    <div className="mb-6 flex items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-sky-200" placeholder="Tìm chương..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                        </div>
                        <button onClick={clearAllChapters} className="text-rose-500 font-bold text-xs hover:underline bg-rose-50 px-3 py-2 rounded-lg">Xóa tất cả chương</button>
                    </div>

                    <div className="flex-1 overflow-y-auto grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-4 content-start pb-20">
                        {currentProject.chapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true })).map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100 shadow-inner' : 'bg-white'}`}>
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2.5 rounded-2xl ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin shadow-lg shadow-sky-200' : 'bg-slate-100 text-slate-400'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-sm truncate">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setViewingFileId(ch.id)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl" title="Đọc chương"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 rounded-xl"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex justify-between items-center text-[9px] font-extrabold uppercase tracking-wider">
                                    <span className={ch.status === FileStatus.COMPLETED ? 'text-emerald-700' : ch.status === FileStatus.PROCESSING ? 'text-sky-700' : 'text-slate-500'}>{ch.status}</span>
                                    {ch.usedModel && <span className="text-slate-400 font-medium">{ch.usedModel.split('-').slice(-2).join(' ')}</span>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Menu Luồng Tự Động (Auto-Flow Status Menu) */}
                    {showFlowOffer && (
                        <div className={`fixed bottom-10 right-10 z-40 transition-all duration-300 ease-in-out ${isFlowMinimized ? 'w-14 h-14' : 'w-72 bg-white border-2 border-sky-400 rounded-3xl shadow-2xl p-5'}`}>
                            {isFlowMinimized ? (
                                <button 
                                    onClick={() => setIsFlowMinimized(false)}
                                    className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-all hover:scale-110 active:scale-95 ${isContinuousFlow ? 'bg-sky-500 text-white animate-pulse' : 'bg-white text-sky-500 border border-sky-100'}`}
                                    title={isContinuousFlow ? "Auto-Flow đang chạy..." : "Mở menu Auto-Flow"}
                                >
                                    {isContinuousFlow ? <InfinityIcon className="w-6 h-6" /> : <Zap className="w-6 h-6" />}
                                </button>
                            ) : (
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <div className="p-2 bg-sky-50 text-sky-500 rounded-xl"><Sparkles className="w-4 h-4" /></div>
                                            <span className="font-bold text-sm tracking-tight">Auto-Flow</span>
                                        </div>
                                        <button onClick={() => setIsFlowMinimized(true)} className="p-1 text-slate-400 hover:text-slate-600 rounded-lg transition-all"><ChevronDown className="w-4 h-4" /></button>
                                    </div>

                                    <div className="bg-slate-50 rounded-2xl p-3 border border-slate-100">
                                        <p className="text-[11px] text-slate-500 leading-relaxed font-medium">
                                            {isContinuousFlow 
                                                ? "Đang tự động cào chương mới sau mỗi 2 chương dịch xong." 
                                                : "Hệ thống sẽ tự động dịch & cào chương mới để bạn rảnh tay."}
                                        </p>
                                    </div>

                                    <div className="flex gap-2">
                                        {isContinuousFlow ? (
                                            <button onClick={() => stopTranslation()} className="w-full py-2.5 bg-rose-50 text-rose-500 font-bold text-xs rounded-xl hover:bg-rose-100 transition-all flex items-center justify-center gap-1.5">
                                                <StopCircle className="w-3.5 h-3.5" /> Dừng Auto-Flow
                                            </button>
                                        ) : (
                                            <>
                                                <button onClick={() => setIsFlowMinimized(true)} className="flex-1 py-2.5 text-slate-400 font-bold text-xs hover:bg-slate-50 rounded-xl transition-all">Bỏ qua</button>
                                                <button onClick={() => startTranslation(true)} className="flex-[1.5] py-2.5 bg-sky-500 text-white font-bold text-xs rounded-xl shadow-lg shadow-sky-100 hover:scale-105 active:scale-95 transition-all">Bật Auto-Flow</button>
                                            </>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="w-96 border-l border-slate-200 bg-white p-8 space-y-8 overflow-y-auto">
                    <section className="space-y-4">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2"><Settings className="w-4 h-4" /> Cấu hình truyện</h4>
                        <div className="space-y-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500">TÁC GIẢ</label>
                                <input className="w-full p-3 bg-slate-50 border rounded-xl text-sm outline-none focus:ring-2 focus:ring-sky-100" value={currentProject.info.author} onChange={e => updateProject(currentProject.id, { info: {...currentProject.info, author: e.target.value} })} />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase flex items-center justify-between">
                                    <span>Kinh thánh truyện (Context)</span>
                                    {isAnalyzing && <Loader2 className="w-3 h-3 animate-spin" />}
                                </label>
                                <div className="relative group">
                                    <textarea className="w-full h-32 p-3 bg-emerald-50/30 border border-emerald-100 rounded-xl text-xs text-emerald-900 leading-relaxed resize-none focus:ring-2 focus:ring-emerald-200 outline-none" placeholder="Thông tin bối cảnh, nhân vật quan trọng..." value={currentProject.globalContext} onChange={e => updateProject(currentProject.id, { globalContext: e.target.value })} />
                                    <button onClick={handleAnalyzeContext} disabled={isAnalyzing} className="absolute bottom-3 right-3 p-2 bg-white rounded-lg shadow-sm border border-emerald-100 text-emerald-500 hover:scale-110 active:scale-95 transition-all">{isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Brain className="w-4 h-4" />}</button>
                                </div>
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Từ điển riêng</label>
                                <textarea className="w-full h-48 p-3 bg-slate-50 border rounded-xl text-[10px] font-mono leading-normal resize-none focus:ring-2 focus:ring-sky-100 outline-none" placeholder="TênGốc=TênDịch..." value={currentProject.dictionary} onChange={e => updateProject(currentProject.id, { dictionary: e.target.value })} />
                            </div>
                        </div>
                    </section>
                </div>
              </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center p-20 text-center animate-in fade-in">
                <div className="w-24 h-24 bg-sky-100 rounded-[32px] flex items-center justify-center mb-8 shadow-2xl shadow-sky-200/50"><LayoutDashboard className="w-12 h-12 text-sky-500" /></div>
                <h2 className="text-3xl font-bold">Quản lý Dự án Truyện</h2>
                <button onClick={createNewProject} className="mt-8 px-8 py-4 bg-sky-500 text-white rounded-[20px] font-bold shadow-xl shadow-sky-200 hover:-translate-y-1 transition-all flex items-center gap-2"><PlusCircle className="w-5 h-5" /> Dự Án Mới</button>
            </div>
          )}
      </main>

      {/* Crawl Modal */}
      {showLinkModal && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
              <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95">
                  <div className="p-8">
                      <div className="flex items-center gap-4 mb-8">
                          <div className="p-4 bg-sky-100 text-sky-600 rounded-2xl"><Link2 className="w-6 h-6" /></div>
                          <div><h3 className="text-xl font-bold">Cào Truyện Thông Minh</h3><p className="text-sm text-slate-500">Lấy nội dung tự động từ URL nguồn.</p></div>
                      </div>
                      <div className="space-y-6">
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-slate-500 uppercase px-1">Link chương 1</label>
                            <textarea className="w-full h-24 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none font-mono focus:ring-2 focus:ring-sky-300" placeholder="https://..." value={linkInput} onChange={e => setLinkInput(e.target.value)} />
                        </div>
                        <div className="p-5 bg-slate-50 rounded-3xl border space-y-4">
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-bold">Số lượng chương</span>
                                <input type="number" className="w-20 p-2 bg-white border rounded-xl text-sm text-center font-bold" value={crawlLimit} onChange={e => setCrawlLimit(parseInt(e.target.value) || 1)} />
                            </div>
                            <div className="flex items-center justify-between">
                                <span className="text-xs font-bold text-slate-600">Dừng cào nếu gặp lỗi</span>
                                <div className={`w-10 h-6 rounded-full transition-all relative cursor-pointer ${autoCrawl ? 'bg-sky-500' : 'bg-slate-300'}`} onClick={() => setAutoCrawl(!autoCrawl)}>
                                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${autoCrawl ? 'left-5' : 'left-1'}`} />
                                </div>
                            </div>
                        </div>
                      </div>
                      {fetchProgress && (
                          <div className="mt-8 space-y-2">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase px-1">
                                  <span>Đang cào: {fetchProgress.current}/{fetchProgress.total}</span>
                                  <button onClick={() => { stopCrawlRef.current = true; setIsFetchingLinks(false); }} className="text-rose-500 font-bold">Dừng cào</button>
                              </div>
                              <div className="w-full h-2.5 bg-slate-100 rounded-full overflow-hidden shadow-inner"><div className="h-full bg-sky-500 transition-all duration-300" style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }} /></div>
                          </div>
                      )}
                      <div className="mt-10 flex gap-4">
                          <button onClick={() => { stopCrawlRef.current = true; setShowLinkModal(false); }} className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-all">Hủy</button>
                          <button onClick={handleLinkSubmit} disabled={isFetchingLinks || !linkInput} className="flex-[2] py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-sky-600 transition-all active:scale-95">
                              {isFetchingLinks ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Bắt Đầu
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {showContextSetup && (
          <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[250] flex items-center justify-center p-4">
              <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95">
                  <div className="p-10 space-y-6">
                      <div className="flex items-center gap-4">
                          <div className="p-4 bg-emerald-100 text-emerald-600 rounded-3xl"><Settings2 className="w-8 h-8" /></div>
                          <div>
                              <h3 className="text-2xl font-bold tracking-tight">Cài đặt Context</h3>
                              <p className="text-sm text-slate-500">Để bản dịch chất lượng, AI cần biết bối cảnh truyện.</p>
                          </div>
                      </div>
                      <div className="space-y-4">
                          <div className="p-6 bg-amber-50 border border-amber-100 rounded-3xl flex gap-4">
                              <AlertTriangle className="w-6 h-6 text-amber-500 shrink-0" />
                              <p className="text-xs text-amber-700 leading-relaxed font-medium">Bạn chưa cấu hình bối cảnh cho truyện này. AI có thể dịch sai tên nhân vật hoặc nhầm lẫn xưng hô nếu thiếu context.</p>
                          </div>
                          <div className="space-y-2">
                            <label className="text-[10px] font-bold text-slate-500 uppercase px-1">Nhập thông tin bối cảnh</label>
                            <textarea 
                                className="w-full h-48 p-4 bg-slate-50 border rounded-3xl text-sm focus:ring-2 focus:ring-sky-200 outline-none transition-all" 
                                placeholder="Dán bối cảnh hoặc từ điển quan trọng vào đây..."
                                value={currentProject?.globalContext}
                                onChange={(e) => updateProject(currentProject!.id, { globalContext: e.target.value })}
                            />
                          </div>
                      </div>
                      <div className="flex gap-4">
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 font-bold text-slate-400 hover:bg-slate-50 rounded-2xl">Dịch thô</button>
                          <button onClick={() => startTranslation(false)} className="flex-1 py-4 bg-sky-500 text-white rounded-2xl font-bold shadow-xl shadow-sky-100 hover:scale-105 transition-all">Lưu & Dịch</button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Reader Modal Enhanced */}
      {viewingChapter && (
          <div className={`fixed inset-0 z-[300] flex flex-col animate-in fade-in duration-300 ${readerSettings.bgColor}`}>
             <header className="h-16 px-8 border-b flex items-center justify-between shrink-0 bg-black/5">
                <div className="flex items-center gap-4 min-w-0">
                    <button onClick={() => { stopTTS(); setViewingFileId(null); }} className="p-2 hover:bg-black/10 rounded-xl"><SkipBack className="w-5 h-5 rotate-90" /></button>
                    <h3 className="font-bold text-lg truncate max-w-lg">{viewingChapter.name}</h3>
                </div>

                <div className="flex items-center gap-6">
                    {/* Navigation Controls */}
                    <div className="flex items-center gap-1 bg-black/5 rounded-xl p-1">
                        <button onClick={handlePrevChapter} className="p-2 hover:bg-black/10 rounded-lg text-slate-600 disabled:opacity-30" disabled={sortedChapters.indexOf(viewingChapter) === 0}><SkipBack className="w-4 h-4" /></button>
                        <div className="flex items-center gap-2 px-2 text-xs font-bold border-x border-black/10">
                            <ListOrdered className="w-3.5 h-3.5" />
                            <span>{sortedChapters.indexOf(viewingChapter) + 1} / {sortedChapters.length}</span>
                        </div>
                        <button onClick={handleNextChapter} className="p-2 hover:bg-black/10 rounded-lg text-slate-600 disabled:opacity-30" disabled={sortedChapters.indexOf(viewingChapter) === sortedChapters.length - 1}><SkipForward className="w-4 h-4" /></button>
                    </div>

                    {/* TTS Controls */}
                    <div className="flex items-center gap-2 bg-sky-500/10 text-sky-600 rounded-xl p-1">
                        <button onClick={() => isTTSPlaying ? stopTTS() : playTTS(viewingChapter.translatedContent || "")} className="p-2 hover:bg-sky-500/20 rounded-lg flex items-center gap-2">
                            {isTTSPlaying ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
                            <span className="text-xs font-bold uppercase tracking-wider">{isTTSPlaying ? "Dừng Đọc" : "Đọc Truyện"}</span>
                        </button>
                        {availableVoices.length > 0 && (
                            <select 
                                value={selectedVoiceName || ""} 
                                onChange={(e) => setSelectedVoiceName(e.target.value)}
                                className="bg-transparent text-[10px] font-bold outline-none border-l border-sky-500/20 pl-2 pr-1"
                            >
                                {availableVoices.map(v => (
                                    <option key={v.name} value={v.name}>{v.name} ({v.lang})</option>
                                ))}
                            </select>
                        )}
                        <div className="flex items-center gap-1 px-2 border-l border-sky-500/20">
                            <span className="text-[10px] font-bold">Tốc độ: {readerSettings.ttsRate}x</span>
                            <input 
                                type="range" min="0.5" max="2" step="0.1" 
                                value={readerSettings.ttsRate} 
                                onChange={(e) => setReaderSettings(s => ({...s, ttsRate: parseFloat(e.target.value)}))}
                                className="w-16 h-1 bg-sky-200 rounded-full appearance-none accent-sky-500 cursor-pointer"
                            />
                        </div>
                    </div>

                    <div className="h-6 w-px bg-black/10" />

                    <div className="flex items-center gap-3">
                        {BG_COLORS.map(bg => (
                            <button key={bg.name} onClick={() => setReaderSettings(s => ({...s, bgColor: bg.code}))} className={`w-6 h-6 rounded-full border shadow-sm ${bg.code.split(' ')[0]} ${readerSettings.bgColor.includes(bg.code.split(' ')[0]) ? 'ring-2 ring-sky-500' : ''}`} title={bg.name} />
                        ))}
                    </div>

                    <div className="flex items-center gap-2">
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.max(12, s.fontSize - 2)}))} className="p-1.5 hover:bg-black/10 rounded-lg"><Type className="w-3.5 h-3.5" /></button>
                        <span className="text-xs font-bold w-6 text-center">{readerSettings.fontSize}</span>
                        <button onClick={() => setReaderSettings(s => ({...s, fontSize: Math.min(32, s.fontSize + 2)}))} className="p-1.5 hover:bg-black/10 rounded-lg"><Type className="w-4.5 h-4.5" /></button>
                    </div>

                    <button onClick={() => {
                        stopTTS();
                        updateProject(currentProject!.id, { readerSettings });
                        setViewingFileId(null);
                    }} className="p-2 hover:bg-rose-100 hover:text-rose-600 rounded-xl transition-all"><X className="w-6 h-6" /></button>
                </div>
             </header>
             <div className="flex-1 overflow-hidden grid grid-cols-1 lg:grid-cols-2">
                <div className="p-12 overflow-y-auto font-serif border-r border-black/5 opacity-40 hover:opacity-100 transition-opacity">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className="max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-sky-200">{viewingChapter.content}</div>
                </div>
                <div className="p-12 overflow-y-auto bg-black/5 shadow-inner">
                    <div style={{ fontSize: `${readerSettings.fontSize}px` }} className={`max-w-3xl mx-auto leading-relaxed whitespace-pre-wrap selection:bg-emerald-200 ${readerSettings.fontFamily}`}>
                        {viewingChapter.translatedContent ? (
                            viewingChapter.translatedContent
                        ) : (
                            <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-4">
                                <Hourglass className="w-12 h-12 animate-pulse" />
                                <div className="italic text-center">
                                    Chương này chưa được dịch xong.<br/>
                                    Hãy quay lại sau khi bản dịch hoàn tất.
                                </div>
                            </div>
                        )}
                    </div>
                </div>
             </div>
          </div>
      )}

      {/* Global Toasts */}
      <div className="fixed bottom-6 right-6 z-[400] flex flex-col gap-3">
          {toasts.map(t => (
              <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-right backdrop-blur-md ${t.type === 'error' ? 'bg-rose-50/90 border-rose-100 text-rose-600' : 'bg-white/90 border-slate-200 text-slate-700'}`}>
                  {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
                  <span className="font-bold text-sm">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { FileUp, FileText, Play, Download, Trash2, AlertCircle, CheckCircle, Loader2, FileArchive, Settings, Wrench, Copy, BookOpen, Sparkles, ChevronDown, ChevronUp, RefreshCw, Languages, Zap, Feather, Library, Upload, RotateCcw, Save, Plus, X, BarChart2, AlertTriangle, Clock, Server, Activity, Hourglass, Lock, Edit3, Book, Square, CheckSquare, MoreHorizontal, ImageIcon, Eye, ArrowRight, StickyNote, XCircle, Info, Check, ShieldAlert, Bug, Bookmark, BookmarkPlus, BookA, UploadCloud, Timer, Brain, Edit2, Maximize2, Layers, HardDriveDownload, HardDriveUpload, ChevronRight, PanelRightClose, PanelRightOpen, Hash, AlignLeft, Wand2, Users, UserPlus, HeartHandshake, Tags, Palette, Globe, Sword, Scissors, FileDown, Search, Link2, ExternalLink, ListPlus, Split, FileJson, FileType, LayoutDashboard, PlusCircle, History, Infinity as InfinityIcon, PlayCircle, StopCircle, Settings2, Palette as PaletteIcon, Type, MousePointer2, Volume2, VolumeX, SkipBack, SkipForward, ListOrdered, LogOut } from 'lucide-react';
import { FileItem, FileStatus, StoryInfo, StoryProject, ReaderSettings } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { unzipFiles, createMergedFile, downloadTextFile, readFileAsText, generateEpub, splitContentByRegex, splitContentByLength, downloadRawAsZip, fetchContentFromUrl } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const BG_COLORS = [
    { name: 'Trắng', code: 'bg-white text-slate-900' },
    { name: 'Giấy cũ', code: 'bg-[#f4ecd8] text-slate-900' },
    { name: 'Xanh dịu', code: 'bg-[#e8f5e9] text-slate-900' },
    { name: 'Xám', code: 'bg-[#f5f5f5] text-slate-900' },
    { name: 'Tối', code: 'bg-slate-900 text-slate-300' }
];

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [showContextSetup, setShowContextSetup] = useState<boolean>(false);
  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(10);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [showFlowOffer, setShowFlowOffer] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);
  const [isFlowMinimized, setIsFlowMinimized] = useState<boolean>(false);

  const stopCrawlRef = useRef<boolean>(false);
  const [viewingFileId, setViewingFileId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif',
      ttsRate: 1.0
  });

  // TTS States
  const [isTTSPlaying, setIsTTSPlaying] = useState<boolean>(false);
  const [availableVoices, setAvailableVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoiceName, setSelectedVoiceName] = useState<string | null>(null);
  const currentUtteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  useEffect(() => {
    const loadVoices = () => {
      const voices = window.speechSynthesis.getVoices();
      setAvailableVoices(voices);
      if (voices.length > 0 && !selectedVoiceName) {
          const viVoice = voices.find(v => v.lang.includes('vi')) || voices[0];
          setSelectedVoiceName(viVoice.name);
      }
    };
    loadVoices();
    window.speechSynthesis.onvoiceschanged = loadVoices;
  }, [selectedVoiceName]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (currentProject?.readerSettings) {
        setReaderSettings(currentProject.readerSettings);
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) {
        addToast("Vui lòng dán link truyện hợp lệ", "warning");
        return;
    }

    setIsFetchingLinks(true);
    stopCrawlRef.current = false;
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;

    try {
      let currentUrl: string | null = urls[0];
      setFetchProgress({ current: 0, total: crawlLimit });

      for (let i = 0; i < crawlLimit; i++) {
          if (!currentUrl || stopCrawlRef.current) break;

          try {
            const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
            if (!updatedChapters.some(c => c.name === title)) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
            }
            setFetchProgress({ current: i + 1, total: crawlLimit });
            currentUrl = nextUrl;
            updateProject(currentProject.id, { 
                chapters: [...updatedChapters], 
                lastCrawlUrl: currentUrl || undefined 
            });
            await new Promise(r => setTimeout(r, 1200));
          } catch (fetchErr: any) {
              if (autoCrawl) {
                  addToast("Dừng cào do gặp lỗi ở URL: " + currentUrl, "error");
                  break;
              } else {
                  addToast("Lỗi cào 1 chương, tiếp tục...", "warning");
              }
          }
      }

      if (addedCount > 0) {
          addToast(`Đã cào thêm ${addedCount} chương`, "success");
          setShowFlowOffer(true);
          setIsFlowMinimized(false);
      }
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsFetchingLinks(false); 
        setFetchProgress(null); 
        setShowLinkModal(false); 
        setLinkInput("");
    }
  };

  const clearAllChapters = () => {
    if (!currentProject) return;
    if (window.confirm("Bạn có chắc muốn xóa tất cả các chương?")) {
      updateProject(currentProject.id, { chapters: [] });
      addToast("Đã xóa toàn bộ chương", "success");
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    const updatedChapters = currentProject.chapters.filter(c => c.id !== chapterId);
    updateProject(currentProject.id, { chapters: updatedChapters });
    setProcessingQueue(prev => prev.filter(id => id !== chapterId));
  };

  const handleStartTranslateRequest = () => {
      if (!currentProject) return;
      if (!currentProject.globalContext || currentProject.globalContext.length < 50) {
          setShowContextSetup(true);
      } else {
          startTranslation(false);
      }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    setShowContextSetup(false);
    if (continuous) {
        setShowFlowOffer(true);
        setIsFlowMinimized(true);
    }
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;
    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        return;
    }
    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) return;
    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `${currentProject.info.title}.epub`; a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
    } catch (e: any) { addToast(e.message, 'error'); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("AI đã lập bối cảnh truyện", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;
      if (processingQueue.length < BATCH_FILE_LIMIT && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1200));
                  }
                  if (newChapters.length > 0) {
                      updateProject(currentProject.id, { 
                          chapters: [...currentProject.chapters, ...newChapters], 
                          lastCrawlUrl: nextUrl || undefined 
                      });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);
        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }
        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  // Reader Navigation Logic
  const sortedChapters = useMemo(() => {
    if (!currentProject) return [];
    return [...currentProject.chapters].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject]);

  const viewingChapter = useMemo(() => {
    return sortedChapters.find(c => c.id === viewingFileId) || null;
  }, [sortedChapters, viewingFileId]);

  const handleNextChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex < sortedChapters.length - 1) {
        setViewingFileId(sortedChapters[currentIndex + 1].id);
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  const handlePrevChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex > 0) {
        setViewingFileId(sortedChapters[currentIndex - 1].id);
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  // TTS Control Logic
  const stopTTS = useCallback(() => {
    window.speechSynthesis.cancel();
    setIsTTSPlaying(false);
    currentUtteranceRef.current = null;
  }, []);

  const playTTS = useCallback((text: string) => {
    if (!text) return;
    stopTTS();

    // Split text into smaller chunks for better synthesis stability
    const chunks = text.split('\n').filter(line => line.trim().length > 0);
    let currentChunkIndex = 0;

    const speakChunk = () => {
        if (currentChunkIndex >= chunks.length) {
            const hasNext = handleNextChapter();
            if (!hasNext) {
                stopTTS();
                addToast("Đã đọc xong toàn bộ chương hiện có.", "success");
            }
            return;
        }

        const utterance = new SpeechSynthesisUtterance(chunks[currentChunkIndex]);
        const voice = availableVoices.find(v => v.name === selectedVoiceName);
        if (voice) utterance.voice = voice;
        utterance.rate = readerSettings.ttsRate || 1.0;

        utterance.onend = () => {
            currentChunkIndex++;
            speakChunk();
        };

        utterance.onerror = (e) => {
            console.error("TTS Error:", e);
            stopTTS();
        };

        currentUtteranceRef.current = utterance;
        window.speechSynthesis.speak(utterance);
    };

    setIsTTSPlaying(true);
    speakChunk();
  }, [availableVoices, selectedVoiceName, readerSettings.ttsRate, handleNextChapter, stopTTS]);

  // Auto-play TTS on chapter change if it was already playing
  useEffect(() => {
      if (isTTSPlaying && viewingChapter?.translatedContent) {
          playTTS(viewingChapter.translatedContent);
      }
  }, [viewingFileId]);

  const stats = useMemo(() => {
      if (!currentProject) return { total: 0, done: 0 };
      return { total: currentProject.chapters.length, done: currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length };
  }, [currentProject]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      {/* Sidebar */}
      <aside className="w-80 bg-white border-r border-slate-200 flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg">Dịch Truyện Pro</h1>
            </div>
            <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl transition-all"><PlusCircle className="w-6 h-6" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between items-center">
                <span>Dự án ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => setCurrentProjectId(p.id)} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProject(p.id).then(() => setProjects(prev => prev.filter(x => x.id !== p.id))); }} className="opacity-0 group-hover:opacity-100 p-1.5 hover:text-rose-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                </div>
            ))}
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-6">
                      <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <input className="bg-transparent font-bold text-xl outline-none" value={currentProject.info.title} onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })} />
                            {isProcessing && isContinuousFlow && <InfinityIcon className="w-5 h-5 text-sky-500 animate-pulse" />}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-slate-500">
                            <span className="flex items-center gap-1"><Book className="w-3.5 h-3.5" /> {currentProject.chapters.length} chương</span>
                            <span className="text-emerald-600 font-semibold"><CheckCircle className="w-3.5 h-3.5 inline mr-1" /> {stats.done} xong</span>
                        </div>
                      </div>
                  </div>
                  <div className="flex items-center gap-2">
                      <button onClick={() => setShowLinkModal(true)} className="flex items-center gap-2 px-4 py-2 border rounded-xl font-bold text-sm hover:bg-sky-50">
                          <Link2 className="w-4 h-4 text-sky-500" /> Cào truyện
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : handleStartTranslateRequest()} className={`px-6 py-2 rounded-xl font-bold text-sm shadow-lg ${isProcessing ? 'bg-rose-500 text-white shadow-rose-100' : 'bg-sky-500 text-white shadow-sky-100'}`}>
                          {isProcessing ? 'Dừng dịch' : 'Dịch dự án'}
                      </button>
                      <div className="h-8 w-px bg-slate-200 mx-1" />
                      <button onClick={() => handleExport('epub')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất EPUB"><Download className="w-5 h-5" /></button>
                      <button onClick={() => handleExport('raw')} className="p-2.5 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất File Gốc"><Languages className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden">
                <div className="flex-1 flex flex-col p-8 overflow-hidden relative">
                    <div className="mb-6 flex items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-sky-200" placeholder="Tìm chương..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                        </div>
                        <button onClick={clearAllChapters} className="text-rose-500 font-bold text-xs hover:underline bg-rose-50 px-3 py-2 rounded-lg">Xóa tất cả chương</button>
                    </div>

                    <div className="flex-1 overflow-y-auto grid grid-cols-1 xl:grid-cols-2 2xl:grid-cols-3 gap-4 content-start pb-20">
                        {currentProject.chapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true })).map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100 shadow-inner' : 'bg-white'}`}>
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2.5 rounded-2xl ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin shadow-lg shadow-sky-200' : 'bg-slate-100 text-slate-400'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-sm truncate">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setViewingFileId(ch.id)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl" title="Đọc chương"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 rounded-xl"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
