  errorMessage?: string;
  retryCount: number;
  originalCharCount: number;
  remainingRawCharCount: number;
  usedModel?: string;
}

export interface StoryInfo {
  title: string;
  author: string;
  languages: string[];
  genres: string[];
  mcPersonality: string[];
  worldSetting: string[];
  sectFlow: string[];
  contextNotes?: string;
}

export interface ReaderSettings {
  fontSize: number;
  bgColor: string;
  fontFamily: string;
  ttsVoice?: string;
  ttsRate?: number;
  showOriginal?: boolean;
}

export interface StoryProject {
  id: string;
  info: StoryInfo;
  chapters: FileItem[];
  promptTemplate: string;
  dictionary: string;
  globalContext: string;
  createdAt: number;
  lastModified: number;
  lastCrawlUrl?: string;
