                                {readerSettings.showOriginal && !visibleOriginalIndices.has(i) && (
                                    <div className="absolute top-2 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1 text-[10px] font-bold text-emerald-500 uppercase tracking-widest">
