  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif',
      ttsRate: 1.0,
      showOriginal: false,
      autoScrollSpeed: 1,
      isAutoScrollActive: false
  });

  // TTS States
  const [isTTSPlaying, setIsTTSPlaying] = useState<boolean>(false);
  const [activeTTSIndex, setActiveTTSIndex] = useState<number>(-1);
  const [availableVoices, setAvailableVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoiceName, setSelectedVoiceName] = useState<string | null>(null);
  const currentUtteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  // Auto-scroll logic
  const readerScrollRef = useRef<HTMLDivElement>(null);
  const scrollIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    if (readerSettings.isAutoScrollActive && readerScrollRef.current) {
        const speed = readerSettings.autoScrollSpeed || 1;
        scrollIntervalRef.current = window.setInterval(() => {
            if (readerScrollRef.current) {
                readerScrollRef.current.scrollTop += speed;
            }
        }, 30);
    } else {
        if (scrollIntervalRef.current) clearInterval(scrollIntervalRef.current);
    }
    return () => { if (scrollIntervalRef.current) clearInterval(scrollIntervalRef.current); };
  }, [readerSettings.isAutoScrollActive, readerSettings.autoScrollSpeed, viewingFileId]);

  // Per-paragraph original text visibility
  const [visibleOriginalIndices, setVisibleOriginalIndices] = useState<Set<number>>(new Set());

  useEffect(() => {
    const loadVoices = () => {
      const voices = window.speechSynthesis.getVoices();
      setAvailableVoices(voices);
      if (voices.length > 0 && !selectedVoiceName) {
          const viVoice = voices.find(v => v.lang.includes('vi')) || voices[0];
          setSelectedVoiceName(viVoice.name);
      }
    };
    loadVoices();
    window.speechSynthesis.onvoiceschanged = loadVoices;
  }, [selectedVoiceName]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (currentProject?.readerSettings) {
        setReaderSettings(prev => ({...prev, ...currentProject.readerSettings}));
    }
  }, [currentProjectId]);

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const createNewProject = () => {
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { title: 'Truyện mới ' + (projects.length + 1), author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: [], worldSetting: [], sectFlow: [] },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: '',
      globalContext: '',
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    setProjects(prev => [newProject, ...prev]);
    setCurrentProjectId(newProject.id);
    setIsSidebarOpen(false);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const handleLinkSubmit = async () => {
    if (!currentProject) return;
    const urls = linkInput.split('\n').map(u => u.trim()).filter(u => u.startsWith('http'));
    if (urls.length === 0) {
        addToast("Vui lòng dán link truyện hợp lệ", "warning");
        return;
    }

    setIsFetchingLinks(true);
    stopCrawlRef.current = false;
    let updatedChapters = [...currentProject.chapters];
    let addedCount = 0;

    try {
      let currentUrl: string | null = urls[0];
      setFetchProgress({ current: 0, total: crawlLimit });

      for (let i = 0; i < crawlLimit; i++) {
          if (!currentUrl || stopCrawlRef.current) break;

          try {
            const { title, content, nextUrl } = await fetchContentFromUrl(currentUrl);
            if (!updatedChapters.some(c => c.name === title)) {
                updatedChapters.push({ 
                    id: crypto.randomUUID(), 
                    name: title, 
                    content, 
                    translatedContent: null, 
                    status: FileStatus.IDLE, 
                    retryCount: 0, 
                    originalCharCount: content.length, 
                    remainingRawCharCount: 0 
                });
                addedCount++;
            }
            setFetchProgress({ current: i + 1, total: crawlLimit });
            currentUrl = nextUrl;
            updateProject(currentProject.id, { 
                chapters: [...updatedChapters], 
                lastCrawlUrl: currentUrl || undefined 
            });
            await new Promise(r => setTimeout(r, 1200));
          } catch (fetchErr: any) {
              if (autoCrawl) {
                  addToast("Dừng cào do gặp lỗi ở URL: " + currentUrl, "error");
                  break;
              } else {
                  addToast("Lỗi cào 1 chương, tiếp tục...", "warning");
              }
          }
      }

      if (addedCount > 0) {
          addToast(`Đã cào thêm ${addedCount} chương`, "success");
          setShowFlowOffer(true);
          setIsFlowMinimized(false);
      }
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsFetchingLinks(false); 
        setFetchProgress(null); 
        setShowLinkModal(false); 
        setLinkInput("");
    }
  };

  const clearAllChapters = () => {
    if (!currentProject) return;
    if (window.confirm("Bạn có chắc muốn xóa tất cả các chương?")) {
      updateProject(currentProject.id, { chapters: [] });
      addToast("Đã xóa toàn bộ chương", "success");
    }
  };

  const deleteChapter = (chapterId: string) => {
    if (!currentProject) return;
    const updatedChapters = currentProject.chapters.filter(c => c.id !== chapterId);
    updateProject(currentProject.id, { chapters: updatedChapters });
    setProcessingQueue(prev => prev.filter(id => id !== chapterId));
  };

  const handleStartTranslateRequest = () => {
      if (!currentProject) return;
      if (!currentProject.globalContext || currentProject.globalContext.length < 50) {
          setShowContextSetup(true);
      } else {
          startTranslation(false);
      }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0 && !continuous) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    processingProjectIdRef.current = currentProject.id;
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
    setShowContextSetup(false);
    if (continuous) {
        setShowFlowOffer(true);
        setIsFlowMinimized(true);
    }
  };

  const stopTranslation = () => {
      setIsProcessing(false);
      setIsContinuousFlow(false);
      setProcessingQueue([]);
      processingProjectIdRef.current = null;
  };

  const handleExport = async (format: 'epub' | 'txt' | 'raw') => {
    if (!currentProject) return;
    if (format === 'raw') {
        const content = currentProject.chapters.map(c => `[[[ ${c.name} ]]]\n\n${c.content}`).join('\n\n');
        downloadTextFile(`${currentProject.info.title}_RAW.txt`, content);
        return;
    }
    const completedChapters = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED);
    if (completedChapters.length === 0) return;
    try {
      if (format === 'epub') {
        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `${currentProject.info.title}.epub`; a.click();
      } else {
        const content = createMergedFile(currentProject.chapters);
        downloadTextFile(`${currentProject.info.title}.txt`, content);
      }
    } catch (e: any) { addToast(e.message, 'error'); }
  };

  const handleAnalyzeContext = async () => {
      if (!currentProject || isAnalyzing) return;
      setIsAnalyzing(true);
      try {
          const context = await analyzeStoryContext(currentProject.chapters.slice(0, 10), currentProject.info);
          updateProject(currentProject.id, { globalContext: context });
          addToast("AI đã lập bối cảnh truyện", "success");
      } catch (e: any) { addToast(e.message, 'error'); } finally { setIsAnalyzing(false); }
  };

  useEffect(() => {
      if (!isContinuousFlow || !isProcessing || !currentProject || !currentProject.lastCrawlUrl) return;
      if (processingQueue.length < BATCH_FILE_LIMIT && !isFetchingLinks) {
          const fetchMore = async () => {
              setIsFetchingLinks(true);
              try {
                  let nextUrl = currentProject.lastCrawlUrl;
                  let newChapters: FileItem[] = [];
                  for (let i = 0; i < BATCH_FILE_LIMIT; i++) {
                      if (!nextUrl) break;
                      const res = await fetchContentFromUrl(nextUrl);
                      newChapters.push({ id: crypto.randomUUID(), name: res.title, content: res.content, translatedContent: null, status: FileStatus.IDLE, retryCount: 0, originalCharCount: res.content.length, remainingRawCharCount: 0 });
                      nextUrl = res.nextUrl || null;
                      await new Promise(r => setTimeout(r, 1200));
                  }
                  if (newChapters.length > 0) {
                      updateProject(currentProject.id, { 
                          chapters: [...currentProject.chapters, ...newChapters], 
                          lastCrawlUrl: nextUrl || undefined 
                      });
                      setProcessingQueue(prev => [...prev, ...newChapters.map(c => c.id)]);
                  }
              } catch (e) {} finally { setIsFetchingLinks(false); }
          };
          fetchMore();
      }
  }, [processingQueue.length, isContinuousFlow, isProcessing, currentProject?.id]);

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);
        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }
        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  // Reader Navigation Logic
  const sortedChapters = useMemo(() => {
    if (!currentProject) return [];
    return [...currentProject.chapters].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject]);

  const viewingChapter = useMemo(() => {
    return sortedChapters.find(c => c.id === viewingFileId) || null;
  }, [sortedChapters, viewingFileId]);

  const handleNextChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex < sortedChapters.length - 1) {
        setViewingFileId(sortedChapters[currentIndex + 1].id);
        setVisibleOriginalIndices(new Set());
        if (readerScrollRef.current) readerScrollRef.current.scrollTop = 0;
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  const handlePrevChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex > 0) {
        setViewingFileId(sortedChapters[currentIndex - 1].id);
        setVisibleOriginalIndices(new Set());
        if (readerScrollRef.current) readerScrollRef.current.scrollTop = 0;
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  // TTS Control Logic
  const stopTTS = useCallback(() => {
    window.speechSynthesis.cancel();
    setIsTTSPlaying(false);
    setActiveTTSIndex(-1);
    currentUtteranceRef.current = null;
  }, []);

  const playTTS = useCallback((text: string) => {
    if (!text) return;
    stopTTS();

    const chunks = text.split('\n').filter(line => line.trim().length > 0);
    let currentChunkIndex = 0;

    const speakChunk = () => {
        if (currentChunkIndex >= chunks.length) {
            const hasNext = handleNextChapter();
            if (!hasNext) {
                stopTTS();
                addToast("Đã đọc xong toàn bộ chương hiện có.", "success");
            }
            return;
        }

        setActiveTTSIndex(currentChunkIndex);
        const utterance = new SpeechSynthesisUtterance(chunks[currentChunkIndex]);
        const voice = availableVoices.find(v => v.name === selectedVoiceName);
        if (voice) utterance.voice = voice;
        utterance.rate = readerSettings.ttsRate || 1.0;

        utterance.onend = () => {
            currentChunkIndex++;
            speakChunk();
        };

        utterance.onerror = (e) => {
            console.error("TTS Error:", e);
            stopTTS();
        };

        currentUtteranceRef.current = utterance;
        window.speechSynthesis.speak(utterance);
    };

    setIsTTSPlaying(true);
    speakChunk();
  }, [availableVoices, selectedVoiceName, readerSettings.ttsRate, handleNextChapter, stopTTS]);

  useEffect(() => {
      if (isTTSPlaying && viewingChapter?.translatedContent) {
          playTTS(viewingChapter.translatedContent);
      }
  }, [viewingFileId]);

  const toggleParagraphOriginal = (index: number) => {
      if (!readerSettings.showOriginal) return;
      setVisibleOriginalIndices(prev => {
          const next = new Set(prev);
          if (next.has(index)) next.delete(index);
          else next.add(index);
          return next;
      });
  };

  const translatedParagraphs = useMemo(() => {
      return viewingChapter?.translatedContent?.split('\n').filter(l => l.trim().length > 0) || [];
  }, [viewingChapter?.translatedContent]);

  const originalParagraphs = useMemo(() => {
      return viewingChapter?.content?.split('\n').filter(l => l.trim().length > 0) || [];
  }, [viewingChapter?.content]);

  const stats = useMemo(() => {
      if (!currentProject) return { total: 0, done: 0 };
      return { total: currentProject.chapters.length, done: currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length };
  }, [currentProject]);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">
      {/* Responsive Sidebar */}
      <aside className={`fixed inset-y-0 left-0 w-80 bg-white border-r border-slate-200 flex flex-col shrink-0 z-50 transition-transform duration-300 lg:relative lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-sky-500 rounded-xl text-white shadow-lg"><Zap className="w-5 h-5" /></div>
                <h1 className="font-bold text-lg">Dịch Truyện Pro</h1>
            </div>
            <div className="flex items-center gap-1">
                <button onClick={createNewProject} className="p-2 text-sky-600 hover:bg-sky-50 rounded-xl"><PlusCircle className="w-6 h-6" /></button>
                <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-slate-400"><X className="w-6 h-6" /></button>
            </div>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2 mb-2 flex justify-between items-center">
                <span>Dự án ({projects.length})</span>
                {isSaving && <Loader2 className="w-3 h-3 animate-spin" />}
            </div>
            {projects.map(p => (
                <div key={p.id} onClick={() => { setCurrentProjectId(p.id); setIsSidebarOpen(false); }} className={`group p-4 rounded-2xl cursor-pointer border transition-all ${currentProjectId === p.id ? 'bg-sky-50 border-sky-200 shadow-sm' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <div className="flex justify-between items-start">
                        <div className="min-w-0 flex-1">
                            <h4 className="font-bold text-sm truncate">{p.info.title}</h4>
                            <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1.5"><History className="w-3 h-3" /> {new Date(p.lastModified).toLocaleDateString()}</p>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteProject(p.id).then(() => setProjects(prev => prev.filter(x => x.id !== p.id))); }} className="opacity-0 group-hover:opacity-100 p-1.5 hover:text-rose-500 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                    </div>
                </div>
            ))}
        </div>
      </aside>

      {/* Backdrop for mobile sidebar */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <main className="flex-1 flex flex-col overflow-hidden relative">
          {currentProject ? (
            <>
              <header className="h-20 bg-white border-b border-slate-200 px-4 lg:px-8 flex items-center justify-between shrink-0 z-10">
                  <div className="flex items-center gap-4 lg:gap-6 min-w-0">
                      <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 hover:bg-slate-50 rounded-xl"><Menu className="w-6 h-6" /></button>
                      <div className="flex flex-col min-w-0">
                        <div className="flex items-center gap-2">
                            <input className="bg-transparent font-bold text-lg lg:text-xl outline-none truncate" value={currentProject.info.title} onChange={e => updateProject(currentProject.id, { info: { ...currentProject.info, title: e.target.value } })} />
                            {isProcessing && isContinuousFlow && <InfinityIcon className="w-4 h-4 lg:w-5 lg:h-5 text-sky-500 animate-pulse" />}
                        </div>
                        <div className="flex items-center gap-2 lg:gap-3 text-[10px] lg:text-xs text-slate-500">
                            <span className="flex items-center gap-1 whitespace-nowrap"><Book className="w-3.5 h-3.5" /> {currentProject.chapters.length} chương</span>
                            <span className="text-emerald-600 font-semibold whitespace-nowrap"><CheckCircle className="w-3.5 h-3.5 inline mr-1" /> {stats.done} xong</span>
                        </div>
                      </div>
                  </div>
                  <div className="flex items-center gap-1 lg:gap-2 shrink-0">
                      <button onClick={() => setShowLinkModal(true)} className="hidden sm:flex items-center gap-2 px-3 lg:px-4 py-2 border rounded-xl font-bold text-xs lg:text-sm hover:bg-sky-50">
                          <Link2 className="w-4 h-4 text-sky-500" /> <span className="hidden lg:inline">Cào truyện</span>
                      </button>
                      <button onClick={() => isProcessing ? stopTranslation() : handleStartTranslateRequest()} className={`px-4 lg:px-6 py-2 rounded-xl font-bold text-xs lg:text-sm shadow-lg ${isProcessing ? 'bg-rose-500 text-white shadow-rose-100' : 'bg-sky-500 text-white shadow-sky-100'}`}>
                          {isProcessing ? 'Dừng' : (isContinuousFlow ? 'Auto Flow' : 'Dịch')}
                      </button>
                      <div className="h-8 w-px bg-slate-200 mx-1 hidden sm:block" />
                      <button onClick={() => handleExport('epub')} className="p-2 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất EPUB"><Download className="w-5 h-5" /></button>
                      <button onClick={() => handleExport('raw')} className="p-2 text-slate-500 hover:bg-slate-100 rounded-xl" title="Xuất File Gốc"><Languages className="w-5 h-5" /></button>
                  </div>
              </header>

              <div className="flex-1 flex overflow-hidden flex-col lg:flex-row">
                <div className="flex-1 flex flex-col p-4 lg:p-8 overflow-hidden relative">
                    <div className="mb-4 lg:mb-6 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
                        <div className="relative flex-1">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <input className="w-full pl-11 pr-4 py-2.5 lg:py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-sky-200" placeholder="Tìm chương..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                        </div>
                        <div className="flex items-center justify-between sm:justify-end gap-4">
                             <button onClick={() => setShowLinkModal(true)} className="sm:hidden flex items-center gap-2 px-3 py-2 border rounded-xl font-bold text-xs hover:bg-sky-50">
                                <Link2 className="w-4 h-4 text-sky-500" /> Cào
                             </button>
                             <button onClick={clearAllChapters} className="text-rose-500 font-bold text-[10px] lg:text-xs hover:underline bg-rose-50 px-3 py-2 rounded-lg">Xóa hết</button>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-2 2xl:grid-cols-3 gap-3 lg:gap-4 content-start pb-24 lg:pb-20">
                        {currentProject.chapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true })).map(ch => (
                            <div key={ch.id} className={`p-4 rounded-[24px] border transition-all flex flex-col gap-3 group relative overflow-hidden ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-50/20 border-emerald-100 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-50/50 border-sky-100 ring-2 ring-sky-100 shadow-inner' : 'bg-white'}`}>
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className={`p-2 lg:p-2.5 rounded-2xl ${ch.status === FileStatus.COMPLETED ? 'bg-emerald-100 text-emerald-600 shadow-sm' : ch.status === FileStatus.PROCESSING ? 'bg-sky-500 text-white animate-spin shadow-lg shadow-sky-200' : 'bg-slate-100 text-slate-400'}`}>
                                            {ch.status === FileStatus.PROCESSING ? <RefreshCw className="w-4 h-4 lg:w-5 lg:h-5" /> : <FileText className="w-4 h-4 lg:w-5 lg:h-5" />}
                                        </div>
                                        <div className="min-w-0">
                                            <h5 className="font-bold text-xs lg:text-sm truncate">{ch.name}</h5>
                                            <p className="text-[10px] text-slate-400">{ch.originalCharCount} ký tự</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-1 lg:opacity-0 lg:group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => setViewingFileId(ch.id)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-xl" title="Đọc chương"><Eye className="w-4 h-4" /></button>
                                        <button onClick={() => deleteChapter(ch.id)} className="p-2 text-slate-300 hover:text-rose-500 rounded-xl"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex justify-between items-center text-[9px] font-extrabold uppercase tracking-wider">
