  const [linkInput, setLinkInput] = useState<string>("");
  const [autoCrawl, setAutoCrawl] = useState<boolean>(false);
  const [crawlLimit, setCrawlLimit] = useState<number>(10);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(false);

  const stopCrawlRef = useRef<boolean>(false);
  const [viewingFileId, setViewingFileId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const processingProjectIdRef = useRef<string | null>(null);
  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif',
      ttsRate: 1.0,
      showOriginal: false,
      isAutoScrollActive: true
  });

  const [isTTSPlaying, setIsTTSPlaying] = useState<boolean>(false);
  const [activeTTSIndex, setActiveTTSIndex] = useState<number>(-1);
  const [availableVoices, setAvailableVoices] = useState<SpeechSynthesisVoice[]>([]);
  const [selectedVoiceName, setSelectedVoiceName] = useState<string | null>(null);
  const currentUtteranceRef = useRef<SpeechSynthesisUtterance | null>(null);
  const readerScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (userApiKey) {
        localStorage.setItem('user_gemini_api_key', userApiKey);
        // @ts-ignore
        process.env.API_KEY = userApiKey;
    }
  }, [userApiKey]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
  };

  const handleAnalyzeContext = async () => {
    if (!userApiKey) {
        addToast("Vui lòng cấu hình API Key trước", "error");
        setShowSettings(true);
        return;
    }
    if (!currentProject || isAnalyzing) return;
    if (currentProject.chapters.length === 0) {
        addToast("Cần có ít nhất 1 chương để phân tích", "warning");
        return;
    }
    setIsAnalyzing(true);
    try {
        const context = await analyzeStoryContext(currentProject.chapters.slice(0, 15), currentProject.info);
        updateProject(currentProject.id, { globalContext: context });
        addToast("AI đã lập bối cảnh thành công", "success");
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsAnalyzing(false); 
    }
  };

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);
        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }
        try {
            const { results, model } = await translateBatch(targetProj.chapters.filter(c => batchIds.includes(c.id)), replacePromptVariables(targetProj.promptTemplate, targetProj.info), targetProj.dictionary, targetProj.globalContext, MODEL_CONFIGS.map(m => m.id));
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: results.get(c.id) ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: results.get(c.id) || null, usedModel: model } : c) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId, projects]);

  const sortedChapters = useMemo(() => {
    if (!currentProject) return [];
    return [...currentProject.chapters].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject]);

  const handleNextChapter = useCallback(() => {
    const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
    if (currentIndex < sortedChapters.length - 1) {
        setViewingFileId(sortedChapters[currentIndex + 1].id);
        return true;
    }
    return false;
  }, [sortedChapters, viewingFileId]);

  const stopTTS = useCallback(() => {
    window.speechSynthesis.cancel();
    setIsTTSPlaying(false);
    setActiveTTSIndex(-1);
    currentUtteranceRef.current = null;
  }, []);

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Main UI Components (Sidebar, List, Reader) */}

      {/* Context Setup Modal - Cải thiện Mobile */}
      {showContextSetup && currentProject && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl w-full max-w-2xl overflow-hidden shadow-2xl border border-slate-100 flex flex-col max-h-[90vh]">
            <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-100 rounded-xl text-indigo-600">
                  <Brain className="w-5 h-5" />
                </div>
                <h3 className="font-display font-bold text-slate-800 text-lg">Bối cảnh & Xưng hô</h3>
              </div>
              <button onClick={() => setShowContextSetup(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-500" />
              </button>
            </div>

            <div className="p-6 overflow-y-auto space-y-4 flex-1 custom-scrollbar">
              <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 flex gap-3">
                <Info className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                <p className="text-sm text-amber-800 leading-relaxed">
                  Bối cảnh giúp AI hiểu các mối quan hệ (Ví dụ: Ta - Huynh, Lão nhị). Hãy nhấn nút AI để phân tích tự động.
                </p>
              </div>

              <div className="flex justify-center">
                <button
                  onClick={handleAnalyzeContext}
                  disabled={isAnalyzing || currentProject.chapters.length === 0}
                  className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-bold transition-all shadow-lg active:scale-95 ${
                    isAnalyzing 
                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-indigo-600 to-violet-600 text-white hover:shadow-indigo-200 hover:-translate-y-0.5'
                  }`}
                >
                  {isAnalyzing ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      <span>Đang phân tích cốt truyện...</span>
                    </>
                  ) : (
                    <>
                      <Wand2 className="w-5 h-5" />
                      <span>AI Tự động lập Bối cảnh</span>
                    </>
                  )}
                </button>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700 ml-1">Bối cảnh chi tiết (Story Bible)</label>
                <textarea
                  value={currentProject.globalContext}
                  onChange={(e) => updateProject(currentProject.id, { globalContext: e.target.value })}
                  placeholder="Dán hoặc nhấn AI để tự động lập bối cảnh..."
                  className="w-full h-80 p-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all text-sm leading-relaxed outline-none font-mono"
                />
              </div>
            </div>

            <div className="p-4 border-t border-slate-100 bg-slate-50/50 flex gap-3">
              <button onClick={() => setShowContextSetup(false)} className="flex-1 px-4 py-3 rounded-xl font-medium text-slate-600 hover:bg-white hover:shadow-sm border border-slate-200 transition-all">
                Hủy bỏ
              </button>
              <button
                onClick={() => {
                  if (currentProject.globalContext.length > 50) {
                    setShowContextSetup(false);
                    startTranslation(false);
                  } else {
                    addToast("Vui lòng điền thêm bối cảnh để AI dịch chuẩn hơn", "warning");
                  }
                }}
                className="flex-[2] bg-indigo-600 text-white px-4 py-3 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100 active:scale-95 transition-all"
              >
                Lưu & Bắt đầu Dịch
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Render Toast Notifications */}
      <div className="fixed bottom-4 right-4 z-[100] flex flex-col gap-2 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto flex items-center gap-3 px-4 py-3 rounded-2xl shadow-xl border animate-in slide-in-from-right duration-300 ${
            t.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-100' :
            t.type === 'error' ? 'bg-rose-50 text-rose-800 border-rose-100' :
            'bg-white text-slate-800 border-slate-100'
          }`}>
            {t.type === 'success' ? <CheckCircle className="w-5 h-5 text-emerald-500" /> : 
             t.type === 'error' ? <AlertCircle className="w-5 h-5 text-rose-500" /> : 
             <Info className="w-5 h-5 text-indigo-500" />}
            <span className="font-medium">{t.message}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

