                                    className={`px-4 py-2.5 rounded-xl text-xs font-bold transition-all border-2 ${newProjectInfo.mcPersonality.includes(p) ? 'bg-amber-500 border-amber-500 text-white shadow-lg shadow-amber-100' : 'bg-white border-slate-100 text-slate-500 hover:border-amber-200'}`}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex gap-4">
                    <button 
                        onClick={() => setShowNewProjectModal(false)}
                        className="flex-1 px-6 py-4 rounded-2xl font-bold text-slate-500 hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-200 transition-all"
                    >
                        Hủy bỏ
                    </button>
                    <button 
                        onClick={createNewProject}
                        className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold px-6 py-4 rounded-2xl transition-all shadow-xl shadow-indigo-100 active:scale-95"
                    >
                        Tiếp theo: Lập Dự Án
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Link Crawl Modal */}
      {showLinkModal && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl border border-slate-100">
                <div className="p-8">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="p-3 bg-amber-100 rounded-2xl text-amber-600">
                            <Link2 className="w-6 h-6" />
                        </div>
                        <h3 className="font-display font-bold text-2xl text-slate-800">Cào chương từ Link</h3>
                    </div>

                    <div className="space-y-6">
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">URL Chương bắt đầu</label>
                            <input 
                                type="url" 
                                placeholder="https://vuitruyen.net/chuong-1"
                                value={linkInput}
                                onChange={(e) => setLinkInput(e.target.value)}
                                className="w-full p-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:bg-white focus:border-indigo-500 outline-none transition-all font-semibold"
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Số lượng chương muốn lấy (Giới hạn: 100)</label>
                            <div className="flex items-center gap-4">
                                <input 
                                    type="range" min="1" max="100" 
                                    value={crawlLimit} 
                                    onChange={(e) => setCrawlLimit(parseInt(e.target.value))}
                                    className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                                />
                                <span className="font-display font-bold text-indigo-600 text-lg min-w-[3rem] text-center">{crawlLimit}</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex gap-4">
                    <button onClick={() => setShowLinkModal(false)} className="flex-1 px-6 py-4 rounded-2xl font-bold text-slate-500 hover:bg-white transition-all">Hủy</button>
                    <button 
                        onClick={handleLinkCrawl}
                        className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold px-6 py-4 rounded-2xl shadow-xl shadow-indigo-100 transition-all active:scale-95"
                    >
                        Bắt đầu Cào Link
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Context Setup Modal */}
      {showContextSetup && currentProject && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl overflow-hidden shadow-2xl border border-slate-100 flex flex-col max-h-[90vh]">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-2.5 bg-indigo-100 rounded-2xl text-indigo-600">
                  <Brain className="w-6 h-6" />
                </div>
                <h3 className="font-display font-bold text-2xl text-slate-800">Thiết lập Bối cảnh</h3>
              </div>
              <button onClick={() => setShowContextSetup(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <X className="w-6 h-6 text-slate-400" />
              </button>
            </div>

            <div className="p-8 overflow-y-auto space-y-6 flex-1 custom-scrollbar">
              <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100 flex gap-4">
                <Info className="w-6 h-6 text-amber-600 shrink-0" />
                <p className="text-sm text-amber-900 leading-relaxed font-medium">
                  Bối cảnh giúp AI hiểu các mối quan hệ (Ví dụ: Ta - Huynh, Lão nhị) và thuật ngữ đặc thù của truyện. Bạn nên để AI tự động phân tích từ 15 chương đầu để có kết quả tốt nhất.
                </p>
              </div>

              <div className="flex justify-center">
                <button
                  onClick={handleAnalyzeContext}
                  disabled={isAnalyzing || currentProject.chapters.length === 0}
                  className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-bold transition-all shadow-xl active:scale-95 ${
                    isAnalyzing 
                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-indigo-600 to-violet-600 text-white hover:shadow-indigo-200 hover:-translate-y-1'
                  }`}
                >
                  {isAnalyzing ? (
                    <>
                      <Loader2 className="w-6 h-6 animate-spin" />
                      <span>Đang phân tích bối cảnh...</span>
                    </>
                  ) : (
                    <>
                      <Wand2 className="w-6 h-6" />
                      <span>AI Tự động lập Bối cảnh</span>
                    </>
                  )}
                </button>
              </div>

              <div className="space-y-3">
                <label className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Bối cảnh chi tiết (Story Bible)</label>
                <textarea
                  value={currentProject.globalContext}
                  onChange={(e) => updateProject(currentProject.id, { globalContext: e.target.value })}
                  placeholder="Nhấn nút AI ở trên để tự động lập bối cảnh từ các chương đã tải lên..."
                  className="w-full h-80 p-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:bg-white focus:border-indigo-500 outline-none transition-all text-sm leading-relaxed font-mono custom-scrollbar shadow-inner"
                />
              </div>
            </div>

            <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex gap-4">
              <button onClick={() => setShowContextSetup(false)} className="flex-1 px-6 py-4 rounded-2xl font-bold text-slate-500 hover:bg-white transition-all border border-transparent hover:border-slate-200">
                Đóng
              </button>
              <button
                onClick={() => {
                    setShowContextSetup(false);
                    addToast("Đã cập nhật bối cảnh", "success");
                }}
                className="flex-[2] bg-indigo-600 text-white px-6 py-4 rounded-2xl font-bold hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-95"
              >
                Lưu thay đổi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Settings Modal */}
      {showSettings && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl border border-slate-100">
                  <div className="p-8">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="p-3 bg-indigo-100 rounded-2xl text-indigo-600">
                            <Settings className="w-6 h-6" />
                        </div>
                        <h3 className="font-display font-bold text-2xl text-slate-800">Cấu hình Hệ thống</h3>
                    </div>

                    <div className="space-y-8">
                        <div className="space-y-3">
                            <div className="flex items-center justify-between">
                                <label className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Google Gemini API Key</label>
                                <a href="https://aistudio.google.com/app/apikey" target="_blank" className="text-xs font-bold text-indigo-600 hover:underline flex items-center gap-1">
                                    Lấy Key tại đây <ExternalLink className="w-3 h-3" />
                                </a>
                            </div>
                            <div className="relative">
                                <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                                <input 
                                    type="password" 
                                    placeholder="Nhập API Key của bạn..."
                                    value={userApiKey}
                                    onChange={(e) => setUserApiKey(e.target.value)}
                                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border-2 border-transparent focus:bg-white focus:border-indigo-500 outline-none transition-all font-mono text-sm"
                                />
                            </div>
                            <p className="text-[10px] text-slate-400 font-medium px-2">Key của bạn được lưu an toàn tại trình duyệt cá nhân (Local Storage), không gửi về máy chủ bên thứ 3.</p>
                        </div>

                        <div className="p-5 bg-indigo-50 rounded-3xl border border-indigo-100">
                            <h4 className="font-bold text-indigo-900 text-sm mb-2 flex items-center gap-2">
                                <Zap className="w-4 h-4" />
                                Model thông minh hiện tại
                            </h4>
                            <p className="text-xs text-indigo-700 leading-relaxed font-medium">Hệ thống đang sử dụng Model Gemini 1.5 & 2.0 Flash làm dự phòng và Gemini 3.0 Pro cho tác vụ chính để đảm bảo tốc độ và chất lượng cao nhất.</p>
                        </div>
                    </div>
                  </div>

                  <div className="p-8 border-t border-slate-100 bg-slate-50/50">
                      <button 
                        onClick={() => setShowSettings(false)}
                        className="w-full bg-slate-800 hover:bg-slate-900 text-white font-bold py-4 px-6 rounded-2xl transition-all shadow-xl active:scale-95"
                      >
                          Xác nhận & Hoàn tất
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Toast Notification Container */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col gap-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border-2 animate-in slide-in-from-right duration-300 min-w-[280px] max-w-md ${
            t.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-100' :
            t.type === 'error' ? 'bg-rose-50 text-rose-800 border-rose-100' :
            t.type === 'warning' ? 'bg-amber-50 text-amber-800 border-amber-100' :
            'bg-white text-slate-800 border-slate-100'
          }`}>
            <div className={`p-2 rounded-xl ${
                t.type === 'success' ? 'bg-emerald-500 text-white' :
                t.type === 'error' ? 'bg-rose-500 text-white' :
                t.type === 'warning' ? 'bg-amber-500 text-white' :
                'bg-indigo-500 text-white'
            }`}>
                {t.type === 'success' ? <CheckCircle className="w-5 h-5" /> : 
                 t.type === 'error' ? <AlertCircle className="w-5 h-5" /> : 
                 t.type === 'warning' ? <AlertTriangle className="w-5 h-5" /> : 
                 <Info className="w-5 h-5" />}
            </div>
            <span className="font-bold text-sm leading-tight">{t.message}</span>
          </div>
        ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { 
  FileText, Download, Trash2, AlertCircle, CheckCircle, Loader2, Settings, Zap, Sparkles, ChevronDown, RefreshCw, Languages, Plus, Search, Link2, Book, Brain, Type, Volume2, VolumeX, SkipBack, SkipForward, LogOut, Eye, EyeOff, Menu, ScrollText, Key, ExternalLink, Github, HelpCircle, AlertTriangle, X, PlusCircle, History, Hourglass, Info, Wand2, FileArchive, ArrowRight
} from 'lucide-react';
import { FileItem, FileStatus, StoryProject, ReaderSettings } from './types';
import { DEFAULT_PROMPT, MODEL_CONFIGS, AVAILABLE_LANGUAGES, AVAILABLE_GENRES, AVAILABLE_PERSONALITIES, AVAILABLE_SETTINGS, AVAILABLE_FLOWS, DEFAULT_DICTIONARY } from './constants';
import { translateBatch, analyzeStoryContext } from './geminiService';
import { createMergedFile, downloadTextFile, generateEpub, fetchContentFromUrl, unzipFiles } from './utils/fileHelpers';
import { replacePromptVariables } from './utils/textHelpers';
import { saveProject, getAllProjects, deleteProject } from './utils/storage';
import { quotaManager } from './utils/quotaManager';

const MAX_CONCURRENCY = 1; 
const BATCH_FILE_LIMIT = 2; 

const BG_COLORS = [
    { name: 'Trắng', code: 'bg-white text-slate-900' },
    { name: 'Giấy cũ', code: 'bg-[#f4ecd8] text-slate-900' },
    { name: 'Xanh dịu', code: 'bg-[#e8f5e9] text-slate-900' },
    { name: 'Tối', code: 'bg-slate-900 text-slate-300' }
];

const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [activeWorkers, setActiveWorkers] = useState<number>(0);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [showContextSetup, setShowContextSetup] = useState<boolean>(false);
  const [showSettings, setShowSettings] = useState<boolean>(false);
  const [showNewProjectModal, setShowNewProjectModal] = useState<boolean>(false);
  const [userApiKey, setUserApiKey] = useState<string>(localStorage.getItem('user_gemini_api_key') || '');

  const [linkInput, setLinkInput] = useState<string>("");
  const [crawlLimit, setCrawlLimit] = useState<number>(10);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [fetchProgress, setFetchProgress] = useState<{current: number, total: number} | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [isContinuousFlow, setIsContinuousFlow] = useState<boolean>(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState<boolean>(false);

  const [viewingFileId, setViewingFileId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  // Fix: Defined readerScrollRef to manage reader modal scrolling behavior
  const readerScrollRef = useRef<HTMLDivElement>(null);

  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const [readerSettings, setReaderSettings] = useState<ReaderSettings>({
      fontSize: 18,
      bgColor: 'bg-[#f4ecd8] text-slate-900',
      fontFamily: 'font-serif',
      ttsRate: 1.0,
      showOriginal: false,
      isAutoScrollActive: true
  });

  // New Project State
  const [newProjectInfo, setNewProjectInfo] = useState({
      title: '', author: '', languages: ['Convert thô'], genres: ['Tiên Hiệp'], mcPersonality: ['Trầm ổn/Già dặn'], worldSetting: ['Trung Cổ/Cổ Đại'], sectFlow: ['Phàm nhân lưu']
  });

  useEffect(() => {
    if (userApiKey) {
        localStorage.setItem('user_gemini_api_key', userApiKey);
        // @ts-ignore
        process.env.API_KEY = userApiKey;
    }
  }, [userApiKey]);

  useEffect(() => {
    getAllProjects().then(setProjects);
  }, []);

  const addToast = (message: string, type: 'success' | 'error' | 'info' | 'warning' = 'info') => {
    const id = crypto.randomUUID();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
  };

  const updateProject = (id: string, updates: Partial<StoryProject>) => {
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates, lastModified: Date.now() } : p));
  };

  const persistProject = async (project: StoryProject) => {
    setIsSaving(true);
    try {
      await saveProject(project);
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  useEffect(() => {
    if (currentProject) persistProject(currentProject);
  }, [currentProject?.lastModified]);

  const createNewProject = async () => {
    if (!newProjectInfo.title) return addToast("Tên truyện không được để trống", "warning");
    const newProject: StoryProject = {
      id: crypto.randomUUID(),
      info: { ...newProjectInfo, contextNotes: "" },
      chapters: [],
      promptTemplate: DEFAULT_PROMPT,
      dictionary: DEFAULT_DICTIONARY,
      globalContext: "",
      createdAt: Date.now(),
      lastModified: Date.now()
    };
    const updated = [...projects, newProject];
    setProjects(updated);
    setCurrentProjectId(newProject.id);
    await saveProject(newProject);
    setShowNewProjectModal(false);
    addToast("Đã tạo dự án mới", "success");
  };

  const handleDeleteProject = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("Bạn có chắc chắn muốn xóa truyện này?")) return;
    await deleteProject(id);
    setProjects(prev => prev.filter(p => p.id !== id));
    if (currentProjectId === id) setCurrentProjectId(null);
    addToast("Đã xóa truyện", "info");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!currentProject || !e.target.files?.length) return;
    const files = e.target.files;
    let newChapters: FileItem[] = [];

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.name.endsWith('.zip')) {
            const unzipped = await unzipFiles(file);
            newChapters = [...newChapters, ...unzipped];
        } else if (file.name.endsWith('.txt')) {
            const reader = new FileReader();
            const content = await new Promise<string>((resolve) => {
                reader.onload = (re) => resolve(re.target?.result as string);
                reader.readAsText(file);
            });
            newChapters.push({
                id: crypto.randomUUID(),
                name: file.name.replace('.txt', ''),
                content,
                translatedContent: null,
                status: FileStatus.IDLE,
                retryCount: 0,
                originalCharCount: content.length,
                remainingRawCharCount: 0
            });
        }
    }

    updateProject(currentProject.id, { chapters: [...currentProject.chapters, ...newChapters] });
    addToast(`Đã tải lên ${newChapters.length} chương`, "success");
  };

  const handleLinkCrawl = async () => {
    if (!currentProject || !linkInput) return;
    setIsFetchingLinks(true);
    setShowLinkModal(false);
    let currentUrl = linkInput;
    let count = 0;

    try {
        while (currentUrl && count < crawlLimit) {
            setFetchProgress({ current: count + 1, total: crawlLimit });
            const result = await fetchContentFromUrl(currentUrl);
            const newChapter: FileItem = {
                id: crypto.randomUUID(),
                name: result.title,
                content: result.content,
                translatedContent: null,
                status: FileStatus.IDLE,
                retryCount: 0,
                originalCharCount: result.content.length,
                remainingRawCharCount: 0
            };

            setProjects(prev => prev.map(p => p.id === currentProject.id ? { ...p, chapters: [...p.chapters, newChapter], lastCrawlUrl: result.nextUrl || undefined } : p));
            currentUrl = result.nextUrl || "";
            count++;
            if (!currentUrl) break;
            await new Promise(r => setTimeout(r, 1000)); // Delay tránh bị block
        }
        addToast(`Đã cào xong ${count} chương`, "success");
    } catch (e: any) {
        addToast(e.message, "error");
    } finally {
        setIsFetchingLinks(false);
        setFetchProgress(null);
        setLinkInput("");
    }
  };

  const startTranslation = (continuous: boolean = false) => {
    if (!currentProject) return;
    if (!userApiKey) {
        addToast("Vui lòng nhập API Key trong phần Cài đặt", "error");
        setShowSettings(true);
        return;
    }
    const idleChapters = currentProject.chapters
        .filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR)
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
    if (idleChapters.length === 0) {
        addToast("Không còn chương nào cần dịch", "info");
        return;
    }
    setIsContinuousFlow(continuous);
    setProcessingQueue(idleChapters.map(c => c.id));
    setIsProcessing(true);
  };

  const handleAnalyzeContext = async () => {
    if (!userApiKey) {
        addToast("Vui lòng cấu hình API Key trước", "error");
        setShowSettings(true);
        return;
    }
    if (!currentProject || isAnalyzing) return;
    if (currentProject.chapters.length === 0) {
        addToast("Cần có ít nhất 1 chương để phân tích", "warning");
        return;
    }
    setIsAnalyzing(true);
    try {
        const context = await analyzeStoryContext(currentProject.chapters.slice(0, 15), currentProject.info);
        updateProject(currentProject.id, { globalContext: context });
        addToast("AI đã lập bối cảnh thành công", "success");
    } catch (e: any) { 
        addToast(e.message, 'error'); 
    } finally { 
        setIsAnalyzing(false); 
    }
  };

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || activeWorkers >= MAX_CONCURRENCY || !currentProjectId) return;
    const processBatch = async () => {
        const batchIds = processingQueue.slice(0, BATCH_FILE_LIMIT);
        const targetProjectId = currentProjectId;
        setProcessingQueue(prev => prev.slice(BATCH_FILE_LIMIT));
        setActiveWorkers(prev => prev + 1);

        setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.PROCESSING } : c) } : p));

        const targetProj = projects.find(p => p.id === targetProjectId);
        if (!targetProj) { setActiveWorkers(prev => prev - 1); return; }

        try {
            const prompt = replacePromptVariables(targetProj.promptTemplate, targetProj.info);
            const { results, model } = await translateBatch(
                targetProj.chapters.filter(c => batchIds.includes(c.id)), 
                prompt, 
                targetProj.dictionary, 
                targetProj.globalContext, 
                MODEL_CONFIGS.map(m => m.id)
            );

            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, lastModified: Date.now(), chapters: p.chapters.map(c => {
                if (batchIds.includes(c.id)) {
                    const translated = results.get(c.id);
                    return { ...c, status: translated ? FileStatus.COMPLETED : FileStatus.ERROR, translatedContent: translated || null, usedModel: model };
                }
                return c;
            }) } : p));
        } catch (e) {
            setProjects(prev => prev.map(p => p.id === targetProjectId ? { ...p, chapters: p.chapters.map(c => batchIds.includes(c.id) ? { ...c, status: FileStatus.ERROR } : c) } : p));
        } finally { setActiveWorkers(prev => prev - 1); }
    };
    processBatch();
  }, [isProcessing, processingQueue, activeWorkers, currentProjectId]);

  const sortedChapters = useMemo(() => {
    if (!currentProject) return [];
    return [...currentProject.chapters].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [currentProject]);

  const filteredChapters = useMemo(() => {
      if (!searchTerm) return sortedChapters;
      return sortedChapters.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [sortedChapters, searchTerm]);

  const stats = useMemo(() => {
      if (!currentProject) return { total: 0, completed: 0, progress: 0 };
      const total = currentProject.chapters.length;
      const completed = currentProject.chapters.filter(c => c.status === FileStatus.COMPLETED).length;
      return { total, completed, progress: total > 0 ? (completed / total) * 100 : 0 };
  }, [currentProject]);

  const viewingChapter = useMemo(() => {
      return sortedChapters.find(c => c.id === viewingFileId) || null;
  }, [sortedChapters, viewingFileId]);

  return (
    <div className="flex h-screen w-full bg-transparent overflow-hidden font-sans">

      {/* Sidebar - Mobile Responsive */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 glass-panel border-r border-slate-200/50 transition-transform duration-300 lg:relative lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full">
          <div className="p-6 border-b border-slate-200/50">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-200">
                <Languages className="w-6 h-6 text-white" />
              </div>
              <h1 className="font-display font-bold text-xl text-slate-800">Dịch Truyện <span className="text-indigo-600">AI</span></h1>
            </div>
            <button 
                onClick={() => setShowNewProjectModal(true)}
                className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-2xl transition-all shadow-md active:scale-95"
            >
              <PlusCircle className="w-5 h-5" />
              Tạo Truyện Mới
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
            <p className="px-4 text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Truyện của bạn</p>
            {projects.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                    <Book className="w-12 h-12 mb-2 opacity-20" />
                    <p className="text-sm font-medium">Chưa có truyện nào</p>
                </div>
            ) : projects.map(p => (
              <div 
                key={p.id}
                onClick={() => { setCurrentProjectId(p.id); setIsSidebarOpen(false); }}
                className={`group flex items-center justify-between p-4 rounded-2xl cursor-pointer transition-all ${currentProjectId === p.id ? 'bg-indigo-50 border border-indigo-100' : 'hover:bg-slate-50 border border-transparent'}`}
              >
                <div className="flex items-center gap-3 overflow-hidden">
                  <div className={`p-2 rounded-xl shrink-0 ${currentProjectId === p.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
                    <FileText className="w-4 h-4" />
                  </div>
                  <div className="truncate">
                    <p className={`font-bold text-sm truncate ${currentProjectId === p.id ? 'text-indigo-900' : 'text-slate-700'}`}>{p.info.title}</p>
                    <p className="text-xs text-slate-400 truncate">{p.chapters.length} chương</p>
                  </div>
                </div>
                <button 
                    onClick={(e) => handleDeleteProject(p.id, e)}
                    className="opacity-0 group-hover:opacity-100 p-2 hover:bg-rose-100 hover:text-rose-600 rounded-xl transition-all"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>

          <div className="p-6 border-t border-slate-200/50 bg-slate-50/50">
            <button 
                onClick={() => setShowSettings(true)}
                className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-slate-600 hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-200 transition-all font-semibold"
            >
              <Settings className="w-5 h-5" />
              Cài đặt hệ thống
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 bg-transparent overflow-hidden">

        {/* Navbar */}
        <header className="h-20 glass-panel border-b border-slate-200/50 flex items-center justify-between px-6 shrink-0 relative z-40">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 hover:bg-slate-100 rounded-xl transition-colors"
            >
              <Menu className="w-6 h-6 text-slate-600" />
            </button>
            <div>
              <h2 className="font-display font-bold text-lg text-slate-800 truncate max-w-[200px] sm:max-w-md">
                {currentProject ? currentProject.info.title : "Chọn một truyện để bắt đầu"}
              </h2>
              {currentProject && (
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1.5 text-xs font-semibold text-slate-400">
                        <History className="w-3 h-3" />
                        <span>{new Date(currentProject.lastModified).toLocaleDateString('vi-VN')}</span>
                    </div>
                    {isSaving && (
                        <div className="flex items-center gap-1 text-xs text-indigo-500 font-bold animate-pulse">
                            <Loader2 className="w-3 h-3 animate-spin" />
                            <span>Đang lưu...</span>
                        </div>
                    )}
                  </div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-3">
            {currentProject && (
                <div className="hidden sm:flex items-center gap-3 mr-4">
                    <div className="text-right">
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Hoàn thành</p>
                        <p className="text-sm font-display font-bold text-slate-700">{stats.completed}/{stats.total}</p>
                    </div>
                    <div className="w-24 h-2 bg-slate-200 rounded-full overflow-hidden">
                        <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${stats.progress}%` }}></div>
                    </div>
                </div>
            )}
            <div className="w-px h-8 bg-slate-200 mx-2 hidden sm:block"></div>
            <a href="https://github.com" target="_blank" className="p-2.5 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-xl transition-all hidden sm:block">
              <Github className="w-5 h-5" />
            </a>
          </div>
        </header>

        {/* Dashboard Area */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
          {!currentProject ? (
