                                >
                                    <FileText className="w-4 h-4 text-slate-400" />
                                    Tải File .txt
                                </button>
                                <button 
                                    onClick={async () => {
                                        const blob = await generateEpub(currentProject.chapters, currentProject.info, null);
                                        const url = URL.createObjectURL(blob);
                                        const a = document.createElement('a');
                                        a.href = url;
                                        a.download = `${currentProject.info.title}.epub`;
                                        a.click();
                                    }}
                                    className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 font-semibold transition-colors"
                                >
                                    <Book className="w-4 h-4 text-slate-400" />
                                    Tải File .epub
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Search & Statistics */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="md:col-span-2 relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="Tìm kiếm chương truyện..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-12 pr-4 py-4 rounded-2xl glass-panel border border-slate-200/50 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all font-medium text-slate-700"
                        />
                    </div>
                    <div className="bg-indigo-600 rounded-2xl p-4 flex items-center justify-between text-white shadow-xl shadow-indigo-100">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-white/20 rounded-xl">
                                <Zap className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-xs font-bold opacity-80 uppercase tracking-tighter">Tiến độ tổng</p>
                                <p className="font-display font-bold text-lg">{Math.round(stats.progress)}%</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <p className="text-2xl font-display font-bold">{stats.completed}</p>
                            <p className="text-[10px] font-bold opacity-70 uppercase tracking-tighter">Chương xong</p>
                        </div>
                    </div>
                </div>

                {/* Chapter List */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filteredChapters.length === 0 ? (
                        <div className="col-span-full py-24 flex flex-col items-center justify-center text-slate-400 bg-white/50 rounded-3xl border border-dashed border-slate-200">
                            <FileArchive className="w-16 h-16 mb-4 opacity-20" />
                            <p className="font-bold text-lg">Chưa có chương nào được tải</p>
                            <p className="text-sm">Hãy tải file hoặc cào link để bắt đầu</p>
                        </div>
                    ) : filteredChapters.map((chapter) => (
                        <div 
                            key={chapter.id}
                            className="group bg-white rounded-3xl p-5 border border-slate-100 hover:border-indigo-200 hover:shadow-xl hover:shadow-indigo-50/50 transition-all duration-300 relative overflow-hidden"
                        >
                            <div className="flex items-start justify-between mb-4 relative z-10">
                                <div className="flex-1 min-w-0 pr-4">
                                    <h4 className="font-bold text-slate-800 truncate leading-tight group-hover:text-indigo-600 transition-colors" title={chapter.name}>{chapter.name}</h4>
                                    <div className="flex items-center gap-2 mt-1">
                                        <div className={`w-2 h-2 rounded-full ${
                                            chapter.status === FileStatus.COMPLETED ? 'bg-emerald-500' :
                                            chapter.status === FileStatus.PROCESSING ? 'bg-amber-500 animate-pulse' :
                                            chapter.status === FileStatus.ERROR ? 'bg-rose-500' : 'bg-slate-300'
                                        }`}></div>
                                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                                            {chapter.status === FileStatus.COMPLETED ? 'Đã xong' :
                                             chapter.status === FileStatus.PROCESSING ? 'Đang dịch' :
                                             chapter.status === FileStatus.ERROR ? 'Lỗi' : 'Chưa dịch'}
                                        </span>
                                    </div>
                                </div>
                                <div className="flex gap-1 shrink-0">
                                    {chapter.status === FileStatus.COMPLETED && (
                                        <button 
                                            onClick={() => setViewingFileId(chapter.id)}
                                            className="p-2 hover:bg-indigo-50 text-indigo-500 rounded-xl transition-all"
                                        >
                                            <Eye className="w-4 h-4" />
                                        </button>
                                    )}
                                    <button 
                                        onClick={() => {
                                            if (!confirm("Xóa chương này?")) return;
                                            updateProject(currentProject.id, { chapters: currentProject.chapters.filter(c => c.id !== chapter.id) });
                                        }}
                                        className="p-2 hover:bg-rose-50 text-rose-400 hover:text-rose-600 rounded-xl transition-all"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>

                            <div className="flex items-center justify-between mt-auto pt-3 border-t border-slate-50 relative z-10">
                                <div className="text-[10px] font-bold text-slate-400">
                                    {chapter.originalCharCount.toLocaleString()} ký tự
                                </div>
                                {chapter.usedModel && (
                                    <div className="px-2 py-1 bg-slate-100 rounded-md text-[9px] font-bold text-slate-500 truncate max-w-[80px]">
                                        {chapter.usedModel}
                                    </div>
                                )}
                            </div>

                            {/* Status Overlay Background Effects */}
                            {chapter.status === FileStatus.PROCESSING && (
                                <div className="absolute inset-0 bg-indigo-500/5 animate-pulse"></div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
          )}
        </div>

        {/* Global Progress Bar (Top) */}
        {isFetchingLinks && fetchProgress && (
            <div className="fixed top-0 left-0 right-0 h-1 bg-amber-100 z-[100]">
                <div 
                    className="h-full bg-amber-500 transition-all duration-500 ease-out shadow-[0_0_10px_rgba(245,158,11,0.5)]" 
                    style={{ width: `${(fetchProgress.current / fetchProgress.total) * 100}%` }}
                ></div>
            </div>
        )}
      </main>

      {/* Reader Modal */}
      {viewingChapter && (
          <div className={`fixed inset-0 z-[60] flex flex-col animate-in fade-in zoom-in-95 duration-300 ${readerSettings.bgColor}`}>
              {/* Reader Header */}
              <div className="h-16 flex items-center justify-between px-6 border-b border-black/5 bg-black/5 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <button onClick={() => setViewingFileId(null)} className="p-2 hover:bg-black/10 rounded-full transition-colors">
                        <X className="w-6 h-6" />
                    </button>
                    <h3 className="font-bold text-lg truncate max-w-[200px] sm:max-w-md">{viewingChapter.name}</h3>
                </div>
                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => setReaderSettings(prev => ({ ...prev, showOriginal: !prev.showOriginal }))}
                        className={`p-2 rounded-xl transition-all ${readerSettings.showOriginal ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'hover:bg-black/10'}`}
                        title="Xem nguyên tác"
                    >
                        {readerSettings.showOriginal ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                    <div className="w-px h-6 bg-black/10 mx-2"></div>
                    <button 
                        onClick={() => {
                            const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
                            if (currentIndex > 0) setViewingFileId(sortedChapters[currentIndex - 1].id);
                        }}
                        disabled={sortedChapters.findIndex(c => c.id === viewingFileId) === 0}
                        className="p-2 hover:bg-black/10 rounded-xl disabled:opacity-30"
                    >
                        <SkipBack className="w-5 h-5" />
