                    <button 
                        onClick={() => {
                            const currentIndex = sortedChapters.findIndex(c => c.id === viewingFileId);
                            if (currentIndex < sortedChapters.length - 1) setViewingFileId(sortedChapters[currentIndex + 1].id);
