const BG_COLORS = [
    { name: 'Trắng', code: 'bg-white text-slate-900 border-slate-200' },
    { name: 'Giấy cũ', code: 'bg-[#f4ecd8] text-slate-900 border-[#e5dec5]' },
    { name: 'Xanh dịu', code: 'bg-[#e8f5e9] text-slate-900 border-[#d1e7d3]' },
