import { GoogleGenAI } from '@google/genai';
import { quotaManager } from './utils/quotaManager';
import { MODEL_CONFIGS, GLOSSARY_ANALYSIS_PROMPT } from './constants';
import { StoryInfo, FileItem } from './utils/types';

const getAiClient = (apiKey: string) => {
  if (!apiKey || apiKey.length < 30) {
    throw new Error("Gemini API Key không hợp lệ. Vui lòng kiểm tra lại.");
  }
  return new GoogleGenAI({ apiKey });
};

const optimizeDictionary = (dictionary: string, content: string): string => {
  if (!content || !dictionary) return '';
  const lines = dictionary.split('\n');
  const uniqueMap = new Map<string, string>();
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//')) continue;
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; 
    const key = trimmed.substring(0, eqIndex).trim();
    if (key) uniqueMap.set(key, trimmed);
  }
  const usedLines: string[] = [];
  for (const [key, line] of uniqueMap.entries()) {
      if (content.includes(key)) usedLines.push(line);
  }
  return usedLines.join('\n');
};

const handleErrorQuota = (error: any, modelId: string) => {
    const msg = (error.message || error.toString()).toLowerCase();
    if (msg.includes('quota') || msg.includes('exhausted')) {
        quotaManager.markAsDepleted(modelId);
    } else if (error.status === 429 || msg.includes('429')) {
        quotaManager.recordRateLimit(modelId);
    }
};

const selectModel = (allowedModelIds: string[]) => {
  const currentConfigs = quotaManager.getConfigs();
  const priorityTier = ['gemini-3-flash-preview', 'gemini-3-pro-preview', 'gemini-flash-latest'];
  const available = currentConfigs
    .filter(c => allowedModelIds.includes(c.id) && quotaManager.isModelAvailable(c.id))
    .sort((a, b) => {
        const aIndex = priorityTier.indexOf(a.id);
        const bIndex = priorityTier.indexOf(b.id);
        const aPrio = aIndex === -1 ? Infinity : aIndex;
        const bPrio = bIndex === -1 ? Infinity : bIndex;
        if (aPrio !== bPrio) return aPrio - bPrio;
        return a.priority - b.priority;
    });
  return available.map(m => m.id);
}

export const analyzeStoryContext = async (files: FileItem[], storyInfo: StoryInfo, apiKey: string): Promise<string> => {
    const ai = getAiClient(apiKey);
    const modelsToTry = ['gemini-3-flash-preview', 'gemini-3-pro-preview'];
    const sampleFiles = files.length > 3 ? [files[0], files[Math.floor(files.length/2)], files[files.length-1]] : files;
    let contextContent = sampleFiles.map(f => `--- ${f.name} ---\n${f.content.substring(0, 1500)}`).join('\n\n');
    const userPrompt = `Phân tích cốt truyện, xưng hô và lập từ điển nhân vật cho truyện "${storyInfo.title}" từ nội dung mẫu sau:\n\n${contextContent}`;

    for (const modelId of modelsToTry) {
        if (!quotaManager.isModelAvailable(modelId)) continue;
        try {
            const response = await ai.models.generateContent({
                model: modelId,
                contents: userPrompt,
                config: {
                    systemInstruction: GLOSSARY_ANALYSIS_PROMPT,
                    temperature: 0.3,
                },
            });
            if (response.text) {
                quotaManager.recordRequest(modelId);
                return response.text.trim();
            }
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    throw new Error("AI không thể phản hồi lúc này.");
};

export const translateBatch = async (
    files: { id: string, content: string }[],
    userPrompt: string,
    dictionary: string,
    globalContext: string,
    allowedModelIds: string[],
    apiKey: string
): Promise<{ results: Map<string, string>, model: string }> => {
    const ai = getAiClient(apiKey);
    const combinedContent = files.map(f => f.content).join('\n');
    const relevantDictionary = optimizeDictionary(dictionary, combinedContent);

    let inputContent = "";
    for (const file of files) {
        inputContent += `\n[[[FILE_ID: ${file.id}]]]\n${file.content}\n[[[FILE_END: ${file.id}]]]\n`;
    }

    const systemInstruction = `BẠN LÀ CHUYÊN GIA DỊCH THUẬT VĂN HỌC TRUNG-VIỆT LÀM VIỆC THEO QUY TRÌNH "DỊCH CHỮ THEO CHỮ" (WORD-BY-WORD).

NHIỆM VỤ TỐI THƯỢNG: Dịch đầy đủ 100% nội dung, KHÔNG ĐƯỢC BỎ SÓT DÙ CHỈ MỘT DÒNG.

CÁC QUY TẮC BẮT BUỘC:
1. NGHIÊM CẤM TÓM TẮT: Dịch chi tiết từng câu văn. Nếu đoạn văn gốc dài, bạn phải dịch dài tương ứng. Tuyệt đối không được gộp các đoạn văn lại thành một bản tóm tắt ngắn gọn.
2. SÁT NGHĨA & ĐẦY ĐỦ: Mỗi sự kiện, mỗi lời thoại, mỗi mô tả cảnh vật trong nguyên tác đều phải xuất hiện trong bản dịch tiếng Việt.
3. KHÔNG TRẢ VỀ TIẾNG TRUNG: Toàn bộ kết quả phải là tiếng Việt/Hán Việt thuần thục.
4. GIỮ NGUYÊN TAGS: Sử dụng [[[FILE_ID: ID]]] và [[[FILE_END: ID]]] để bọc nội dung. Nếu nội dung quá dài, bạn hãy kiên trì dịch cho đến khi viết được tag kết thúc.
5. TEMPERATURE THẤP: Tập trung vào tính chính xác, không được tự ý "phóng tác" quá đà làm sai lệch nội dung gốc.
6. KIỂM TRA ĐỘ DÀI: Nếu bạn cảm thấy mình đang dịch quá ngắn so với văn bản gốc, hãy dừng lại và dịch lại chi tiết hơn. Bạn được trả công để dịch ĐẦY ĐỦ, không phải dịch nhanh.`;

    const fullPrompt = `[DICTIONARY]\n${relevantDictionary}\n\n[STORY_CONTEXT]\n${globalContext}\n\n[USER_REQUIREMENTS]\n${userPrompt}\n\n[CONTENT_TO_TRANSLATE]\n${inputContent}\n\nLƯU Ý: Đây có thể là một chương rất dài. Hãy dịch kiên trì từ đầu đến cuối, không được bỏ cuộc giữa chừng.`;

    const attempts = selectModel(allowedModelIds);
    for (const modelId of attempts) {
        try {
            const isGemini3 = modelId.includes('gemini-3');
            // Sử dụng temperature = 0.0 để model hoạt động ổn định nhất, không bị phân tâm
            const response = await ai.models.generateContent({
                model: modelId,
                contents: fullPrompt,
                config: {
                    systemInstruction,
                    temperature: 0.0, 
                    maxOutputTokens: 60000,
                    ...(isGemini3 && modelId.includes('pro') ? { thinkingConfig: { thinkingBudget: 6000 } } : {})
                },
            });

            if (!response.text) continue;

            const results = new Map<string, string>();
            for (const file of files) {
                const escapedId = file.id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const regex = new RegExp(`\\[\\[\\[FILE_ID:\\s*${escapedId}\\s*\\]\\]\\]\\s*([\\s\\S]*?)\\s*\\[\\[\\[FILE_END:\\s*${escapedId}\\s*\\]\\]\\]`, 'i');
                const match = response.text.match(regex);

                if (match) {
                    let translated = match[1].trim();
                    translated = translated.split('\n').filter(line => {
                        const hasVietnamese = /[a-zA-Záàảãạâấầẩẫậăắằẳẵặéèẻẽẹêếềểễệíìỉĩịóòỏõọôốồổỗộơớờởỡợúùủũụưứừửữựýỳỷỹỵđ]/i.test(line);
                        const hasChinese = /[\u4e00-\u9fa5]/.test(line);
                        if (hasChinese && !hasVietnamese) return false;
                        return true;
                    }).join('\n');
                    results.set(file.id, translated);
                } else if (response.text.includes(`[[[FILE_ID: ${file.id}]]]`)) {
                    // Trường hợp model bị cắt ngang giữa chừng (thiếu tag kết thúc)
                    console.warn("Dịch bị cắt ngang do giới hạn output. Đang thu thập phần nội dung đã dịch được.");
                    const startTag = `[[[FILE_ID: ${file.id}]]]`;
                    const startIndex = response.text.indexOf(startTag) + startTag.length;
                    let translated = response.text.substring(startIndex).trim();
                    // Làm sạch nội dung dở dang
                    results.set(file.id, translated + "\n\n(Lưu ý: Chương này quá dài, nội dung có thể đã bị model cắt ngắn)");
                }
            }

            if (results.size > 0) {
                quotaManager.recordRequest(modelId);
                return { results, model: modelId };
            }
        } catch (error: any) {
            handleErrorQuota(error, modelId);
        }
    }
    throw new Error("Dịch thất bại. Nội dung quá dài hoặc model gặp lỗi kết nối.");
};

