export const translateChapterTitle = (title: string): string => {
  let clean = title.trim();
  // Xử lý mẫu: 第1章, 第123章
  clean = clean.replace(/第\s*(\d+)\s*[章話节回]/g, 'Chương $1');
  // Xử lý mẫu: Chapter 1
  clean = clean.replace(/Chapter\s*(\d+)/gi, 'Chương $1');
  // Xử lý số Hán Việt cơ bản
  const hanVietMap: Record<string, string> = { '一': '1', '二': '2', '三': '3', '四': '4', '五': '5', '六': '6', '七': '7', '八': '8', '九': '9', '十': '10' };
  clean = clean.replace(/第\s*([一二三四五六七八九十]+)\s*[章話节回]/g, (match, p1) => {
    return `Chương ${hanVietMap[p1] || p1}`;
  });
  return clean;
};

const resolveUrl = (base: string, relative: string) => {
    try {
        return new URL(relative, base).href;
    } catch (e) {
        return relative;
    }
};

export const fetchContentFromUrl = async (url: string): Promise<{ title: string, content: string, nextUrl: string | null }> => {
    let lastError = "";
    const cleanUrl = url.trim();
    if (!cleanUrl.startsWith('http')) throw new Error("Link không hợp lệ. Phải bắt đầu bằng http/https.");

    for (const proxyBase of PROXY_LIST) {
        try {
            const finalUrl = `${proxyBase}${encodeURIComponent(cleanUrl)}`;
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 15000);

            const response = await fetch(finalUrl, { 
                signal: controller.signal,
                headers: { 'Accept': 'text/html' }
            });

            clearTimeout(timeoutId);
            if (!response.ok) {
                lastError = `Proxy trả về lỗi: ${response.status}`;
                continue;
            }

            const buffer = await response.arrayBuffer();
            let tempDecoder = new TextDecoder('utf-8');
            let tempHtml = tempDecoder.decode(buffer);

            // Xử lý mã hóa tự động cho web Trung Quốc
            if (tempHtml.toLowerCase().includes('charset=gbk') || tempHtml.toLowerCase().includes('charset=gb2312')) {
                tempHtml = new TextDecoder('gbk').decode(buffer);
            }

            const parser = new DOMParser();
            const doc = parser.parseFromString(tempHtml, 'text/html');

            // 1. Tìm tiêu đề
            let rawTitle = doc.title?.split('_')[0].split('-')[0].trim() || "Chương mới";
            const h1 = doc.querySelector('h1');
            if (h1 && (h1 as HTMLElement).innerText?.trim().length < 150) {
                rawTitle = (h1 as HTMLElement).innerText.trim();
            }
            const title = translateChapterTitle(rawTitle);

            // 2. Tìm link chương tiếp theo
            let nextUrl: string | null = null;
            const allLinks = Array.from(doc.querySelectorAll('a'));
            for (const link of allLinks) {
                const text = (link.innerText || link.textContent || "").toLowerCase().trim();
                if (NEXT_CHAPTER_KEYWORDS.some(kw => text === kw || (text.includes(kw) && text.length < 15))) {
                    const href = link.getAttribute('href');
                    if (href && !href.startsWith('javascript') && href !== '#' && !href.includes('login') && !href.includes('comment')) {
                        nextUrl = resolveUrl(cleanUrl, href);
                        break;
                    }
                }
            }

            // 3. Dọn dẹp rác cấp độ 1 (Các thẻ không bao giờ chứa nội dung truyện)
            const junkElements = ['script', 'style', 'iframe', 'ins', 'aside', 'header', 'footer', 'nav', '.ads', '#ads', '.app-download', '.bottom-link', '.read-notice', '.hot-comment', '.author-say'];
            junkElements.forEach(s => doc.querySelectorAll(s).forEach(el => el.remove()));

            // 4. Tìm container nội dung bằng thuật toán chấm điểm nâng cao
            let bestTarget: HTMLElement | null = null;
            let maxScore = -1;

            // Kiểm tra các selector phổ biến trước
            for (const selector of CONTENT_SELECTORS) {
                const elements = doc.querySelectorAll(selector);
                elements.forEach(el => {
                    const htmlEl = el as HTMLElement;
                    const text = htmlEl.innerText?.trim() || "";
                    if (text.length < 200) return;

                    const linkDensity = htmlEl.querySelectorAll('a').length / (text.length / 100);
                    if (linkDensity > 0.5) return; // Quá nhiều link -> không phải nội dung truyện

                    let score = text.length;
                    score += htmlEl.querySelectorAll('p, br').length * 20;

                    if (score > maxScore) {
                        maxScore = score;
                        bestTarget = htmlEl;
                    }
                });
            }

            // Nếu không tìm thấy bằng selector, quét toàn bộ body để tìm div "giống" nội dung nhất
            if (!bestTarget) {
                const allDivs = Array.from(doc.querySelectorAll('div, section, article'));
                allDivs.forEach(container => {
                    const htmlEl = container as HTMLElement;
                    // Bỏ qua các thẻ ẩn (đặc biệt quan quan trọng)
                    const style = window.getComputedStyle(htmlEl);
                    if (style.display === 'none' || style.visibility === 'hidden') return;

                    const text = htmlEl.innerText?.trim() || "";
                    if (text.length < 300) return;

                    const linkDensity = htmlEl.querySelectorAll('a').length / (text.length / 100);
                    if (linkDensity > 0.3) return; 

                    let score = text.length;
                    score += htmlEl.querySelectorAll('p').length * 40;
                    score += htmlEl.querySelectorAll('br').length * 20;

                    // Ưu tiên các div có class liên quan đến content/text
                    if (htmlEl.className.toLowerCase().includes('content') || htmlEl.className.toLowerCase().includes('read')) {
                        score *= 1.2;
                    }

                    if (score > maxScore) { 
                        maxScore = score; 
                        bestTarget = htmlEl; 
                    }
                });
            }

            const finalContainer = bestTarget || doc.body;

            // 5. Bóc tách dòng và xử lý nhiễu
            let lines: string[] = [];

            // Xử lý trường hợp nội dung chỉ dùng <br> thay vì <p>
            const brCount = finalContainer.querySelectorAll('br').length;
            const pCount = finalContainer.querySelectorAll('p').length;

            if (pCount > 5 && pCount > brCount) {
                lines = Array.from(finalContainer.querySelectorAll('p')).map(p => (p as HTMLElement).innerText.trim());
            } else {
                // Tách theo dòng bằng cách thay thế các thẻ block-level bằng ký tự xuống dòng
                const cloned = finalContainer.cloneNode(true) as HTMLElement;
                // Loại bỏ các thẻ ẩn lồng bên trong (Scraper trap)
                cloned.querySelectorAll('*').forEach(el => {
                    const s = (el as HTMLElement).style;
                    if (s.display === 'none' || s.opacity === '0' || (el as HTMLElement).innerText.length === 0) {
                        el.remove();
                    }
                });

                const rawText = cloned.innerHTML
                    .replace(/<br\s*\/?>/gi, '\n')
                    .replace(/<\/p>/gi, '\n')
                    .replace(/<\/div>/gi, '\n');

                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = rawText;
                lines = tempDiv.innerText.split('\n').map(l => l.trim());
            }

            // Lọc các dòng rác cuối cùng
            let cleanLines = lines.filter(line => {
                const l = line.trim();
                if (l.length < 2) return false;

                // Loại bỏ dòng chứa cụm từ rác
                const isJunk = JUNK_PHRASES.some(phrase => l.toLowerCase().includes(phrase.toLowerCase()));
                if (isJunk) return false;

                // Loại bỏ dòng lặp lại chính tiêu đề chương
                if (l === title || l === rawTitle) return false;

                // Loại bỏ các dòng quảng cáo ngắn ngủn
                if (l.length < 15 && (l.includes('www.') || l.includes('.com'))) return false;

                return true;
            });

            const cleanText = cleanLines.join('\n\n').trim();
            if (cleanText.length < 150) {
                lastError = "Nội dung bóc tách quá ngắn, hệ thống không thể xác định vùng văn bản chính xác.";
                continue;
            }

            return { title, content: cleanText, nextUrl };
        } catch (e: any) {
            lastError = `Proxy error or timeout: ${e.message}`;
        }
    }
    throw new Error(lastError || "Không thể tải nội dung truyện. Vui lòng kiểm tra lại link.");
};

export const unzipFiles = async (file: File, startOrder: number = 0): Promise<FileItem[]> => {
  const zip = new JSZip();
  const loadedZip = await zip.loadAsync(file);
  const files: FileItem[] = [];
  const filePaths = Object.keys(loadedZip.files).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  let currentOrder = startOrder;
  for (const relativePath of filePaths) {
    const zipEntry = loadedZip.files[relativePath];
    if (!zipEntry.dir && zipEntry.name.toLowerCase().endsWith('.txt')) {
      const content = await zipEntry.async('string');
      files.push({ 
        id: crypto.randomUUID(), 
        name: translateChapterTitle(zipEntry.name.split('/').pop() || zipEntry.name), 
        orderIndex: currentOrder++,
        content, 
        translatedContent: null, 
        status: FileStatus.IDLE, 
        retryCount: 0, 
        originalCharCount: content.length, 
        remainingRawCharCount: 0 
      });
    }
  }
  return files;
};

export const createMergedFile = (files: FileItem[]): string => {
  return [...files].sort((a, b) => a.orderIndex - b.orderIndex)
    .filter((f) => f.status === FileStatus.COMPLETED && f.translatedContent)
    .map((f) => `### ${f.name}\n\n${f.translatedContent?.trim()}`) 
    .join('\n\n'); 
};

export const downloadTextFile = (filename: string, content: string) => {
  const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

