const PROXY_LIST = [
    "https://api.allorigins.win/raw?url=",
    "https://corsproxy.io/?",
    "https://api.codetabs.com/v1/proxy?quest=",
    "https://thingproxy.freeboard.io/fetch/"
];

const JUNK_PHRASES = [
    "重要声明", "本站", "版权归", "All rights reserved", "最新章节", "永久地址", 
    "网友发表", "来自搜索引擎", "本站立场无关", "www.", ".com", ".net", ".org",
    "点击下一页", "继续阅读", "顶点小说", "笔趣阁", "69书吧", "飘天文学", "shubao", "paoshu",
    "手机用户请访问", "推荐阅读", "sodu", "txt下载", "chm下载", "uukanshu", "biquge",
    "content_bottom", "content_top", "read_ads", "read-ads", "center-ads"
];

const PAGINATION_KEYWORDS = ["下一页", "下一頁", "next page", "2/2", "3/3", "2/3", "(2)", "(3)"];

/**
 * Chuyển đổi tiêu đề chương
 */
export const translateChapterTitle = (title: string): string => {
  let clean = title.trim();
  clean = clean.replace(/第\s*(\d+)\s*[章話节回]/g, 'Chương $1');
  clean = clean.replace(/Chapter\s*(\d+)/gi, 'Chương $1');
  const hanVietMap: Record<string, string> = { '一': '1', '二': '2', '三': '3', '四': '4', '五': '5', '六': '6', '七': '7', '八': '8', '九': '9', '十': '10' };
  clean = clean.replace(/第\s*([一二三四五六七八九十]+)\s*[章話节回]/g, (match, p1) => `Chương ${hanVietMap[p1] || p1}`);
  return clean;
};

const resolveUrl = (base: string, relative: string) => {
    try { return new URL(relative, base).href; } catch (e) { return relative; }
};

/**
 * Cào nội dung với cơ chế đệ quy trang (Pagination support)
 */
export const fetchContentFromUrl = async (url: string, isPaginationCall = false): Promise<{ title: string, content: string, nextUrl: string | null }> => {
    let lastError = "";
    const cleanUrl = url.trim();

    for (const proxyBase of PROXY_LIST) {
        try {
            const finalUrl = `${proxyBase}${encodeURIComponent(cleanUrl)}`;
            const response = await fetch(finalUrl);
            if (!response.ok) continue;

            const buffer = await response.arrayBuffer();
            let html = new TextDecoder('utf-8').decode(buffer);
            if (html.toLowerCase().includes('charset=gbk') || html.toLowerCase().includes('charset=gb2312')) {
                html = new TextDecoder('gbk').decode(buffer);
            }

            const parser = new DOMParser();
            const doc = parser.parseFromString(html, 'text/html');

            // Xử lý tiêu đề (chỉ lấy ở trang đầu tiên)
            const h1 = doc.querySelector('h1');
            const title = translateChapterTitle(h1?.innerText || doc.title?.split('_')[0] || "Chương mới");

            // Xử lý loại bỏ rác
            doc.querySelectorAll('script, style, iframe, ins, .ads, #ads, .author-say, .read-notice').forEach(el => el.remove());

            // Tìm vùng nội dung tốt nhất
            const selectors = ['#content', '#article', '#chaptercontent', '.content', '.showtxt', '.read-content', 'article'];
            let contentContainer: HTMLElement | null = null;
            for (const s of selectors) {
                const el = doc.querySelector(s) as HTMLElement;
                if (el && el.innerText.trim().length > 200) {
                    contentContainer = el;
                    break;
                }
            }
            if (!contentContainer) contentContainer = doc.body;

            // Làm sạch nội dung ẩn (Scraper traps)
            contentContainer.querySelectorAll('*').forEach(el => {
                const style = window.getComputedStyle(el);
                if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') el.remove();
            });

            const rawLines = contentContainer.innerText.split('\n').map(l => l.trim()).filter(l => l.length > 5);
            const cleanLines = rawLines.filter(l => !JUNK_PHRASES.some(j => l.toLowerCase().includes(j.toLowerCase())));
            let pageContent = cleanLines.join('\n\n');

            // TÌM LINK TRANG TIẾP THEO (Pagination within chapter)
            let innerNextPageUrl: string | null = null;
            let realNextChapterUrl: string | null = null;

            const allLinks = Array.from(doc.querySelectorAll('a'));
            for (const link of allLinks) {
                const text = link.innerText.trim().toLowerCase();
                const href = link.getAttribute('href');
                if (!href || href.startsWith('javascript') || href === '#') continue;

                const fullHref = resolveUrl(cleanUrl, href);

                // Ưu tiên tìm pagination (trang 2 của cùng 1 chương)
                if (PAGINATION_KEYWORDS.some(kw => text.includes(kw) && text.length < 10)) {
                    // Nếu URL gần giống URL hiện tại (thường là _2.html, -2.html) -> Đây là pagination
                    if (fullHref.length >= cleanUrl.length - 5) {
                        innerNextPageUrl = fullHref;
                    }
                }

                // Tìm link chương thực sự tiếp theo
                if (text.includes("下一章") || text.includes("next chapter") || text.includes("chương sau")) {
                    realNextChapterUrl = fullHref;
                }
            }

            // Nếu có trang tiếp theo của cùng chương, gọi đệ quy và gộp nội dung
            if (innerNextPageUrl && innerNextPageUrl !== cleanUrl) {
                try {
                    const nextPageData = await fetchContentFromUrl(innerNextPageUrl, true);
                    pageContent += "\n\n" + nextPageData.content;
                    // Trả về nextUrl của chương thực sự tiếp theo từ trang cuối cùng của pagination
                    realNextChapterUrl = nextPageData.nextUrl;
                } catch (e) {
                    console.warn("Lỗi khi cào trang tiếp theo của chương:", e);
                }
            }

            return { title, content: pageContent, nextUrl: realNextChapterUrl };
        } catch (e: any) { lastError = e.message; }
    }
    throw new Error(lastError || "Thất bại khi cào dữ liệu.");
};

