const CHUNK_LIMIT = 3200; 
const CONTEXT_OVERLAP = 400; // Số ký tự chunk trước gối đầu vào chunk sau

const getAiClient = (apiKey: string) => new GoogleGenAI({ apiKey });

const optimizeDictionary = (dict: string, content: string): string => {
  if (!dict) return '';
  return dict.split('\n')
    .filter(line => {
        const key = line.split('=')[0]?.trim();
        return key && content.includes(key);
    })
    .join('\n');
};

const splitSmart = (text: string, limit: number): string[] => {
    const paragraphs = text.split('\n');
    const chunks: string[] = [];
    let current = "";
    for (const p of paragraphs) {
        if ((current.length + p.length) > limit && current.length > 0) {
            chunks.push(current.trim());
            current = p;
        } else {
            current += (current ? "\n" : "") + p;
        }
    }
    if (current) chunks.push(current.trim());
    return chunks;
};

