QUY TRÌNH KIỂM SOÁT:
1. Dịch sát nghĩa, mượt mà, thuần Việt.
2. Nếu có phần "Ngữ cảnh trước đó", hãy dùng nó để nhất quán xưng hô nhưng KHÔNG dịch lại phần đó.
3. Trả về kết quả trong thẻ [[[RESULT]]].
4. Trả về số dòng đã dịch được ở cuối trong thẻ [[[LINES: n]]].`;

    for (const file of files) {
        const chunks = splitSmart(file.content, CHUNK_LIMIT);
        let fullTranslated = "";
        let previousTranslatedContext = ""; // Lưu trữ đoạn dịch cuối của chunk trước

        for (let i = 0; i < chunks.length; i++) {
            const chunk = chunks[i];
            const dict = optimizeDictionary(dictionary, chunk);

            // Lấy một ít nội dung gốc của đoạn trước để AI biết mạch văn
            const prevOriginal = i > 0 ? `\n[NGỮ CẢNH GỐC TRƯỚC ĐÓ]:\n...${chunks[i-1].slice(-CONTEXT_OVERLAP)}` : "";
            const prevTrans = i > 0 ? `\n[BẢN DỊCH TRƯỚC ĐÓ]:\n...${previousTranslatedContext}` : "";

            const prompt = `
[TỪ ĐIỂN]:\n${dict}
[BỐI CẢNH TRUYỆN]:\n${globalContext}
${prevOriginal}${prevTrans}

[NỘI DUNG CẦN DỊCH NGAY BÂY GIỜ (PHẦN ${i+1}/${chunks.length})]:
${chunk}

[YÊU CẦU RIÊNG]: ${userPrompt}
`;

            let chunkSuccess = false;
            const models = allowedModels.filter(m => quotaManager.isModelAvailable(m));

            for (const modelId of models) {
                try {
                    const response = await ai.models.generateContent({
                        model: modelId,
                        contents: prompt,
                        config: { systemInstruction, temperature: 0.1, maxOutputTokens: 8192 }
                    });

                    let text = response.text || "";
                    if (text.includes("[[[RESULT]]]")) {
                        text = text.substring(text.indexOf("[[[RESULT]]]") + 12, text.lastIndexOf("[[[RESULT]]]")).trim();
                    } else {
                        text = text.replace(/\[\[\[.*?\]\]\]/g, "").trim();
                    }

                    // Lưu ngữ cảnh cho chunk sau (lấy 3 câu cuối)
                    const lines = text.split('\n').filter(l => l.trim());
                    previousTranslatedContext = lines.slice(-3).join('\n');

                    fullTranslated += (fullTranslated ? "\n\n" : "") + text;
                    lastModel = modelId;
                    quotaManager.recordRequest(modelId);
                    chunkSuccess = true;
                    break;
                } catch (e: any) {
                    const msg = e.message.toLowerCase();
                    if (msg.includes('quota')) quotaManager.markAsDepleted(modelId);
                }
            }
            if (!chunkSuccess) throw new Error(`Lỗi tại phần ${i+1} của chương.`);
        }
        finalResults.set(file.id, fullTranslated);
    }
    return { results: finalResults, model: lastModel };
};

export const analyzeStoryContext = async (files: FileItem[], story: StoryInfo, apiKey: string): Promise<string> => {
    const ai = getAiClient(apiKey);
    const content = files.slice(0, 3).map(f => f.content.substring(0, 2000)).join('\n\n');
    const prompt = `Phân tích bối cảnh, xưng hô cho truyện "${story.title}":\n\n${content}`;
    const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction: "Trả về hồ sơ nhân vật và thuật ngữ.", temperature: 0.3 }
    });
    return res.text || "";
};

