const App: React.FC = () => {
  const [projects, setProjects] = useState<StoryProject[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const [showLinkModal, setShowLinkModal] = useState<boolean>(false);
  const [showContextSetup, setShowContextSetup] = useState<boolean>(false);
  const [showNewProjectModal, setShowNewProjectModal] = useState<boolean>(false);
  const [showTTSSettings, setShowTTSSettings] = useState<boolean>(false);
  const [showConsole, setShowConsole] = useState<boolean>(false);
  const [logs, setLogs] = useState<{time: string, msg: string, type: 'info'|'warn'|'err'}[]>([]);

  const [linkInput, setLinkInput] = useState<string>("");
  const [isAutoCrawlEnabled, setIsAutoCrawlEnabled] = useState<boolean>(true);
  const [isFetchingLinks, setIsFetchingLinks] = useState<boolean>(false);
  const [apiKey, setApiKey] = useState<string | null>(localStorage.getItem('gemini_api_key'));
  const [viewingRawId, setViewingRawId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<{id: string, message: string, type: string}[]>([]);

  const currentProject = useMemo(() => projects.find(p => p.id === currentProjectId) || null, [projects, currentProjectId]);

  const addLog = (msg: string, type: 'info'|'warn'|'err' = 'info') => {
    setLogs(prev => [{ time: new Date().toLocaleTimeString(), msg, type }, ...prev].slice(0, 50));
  };

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Math.random().toString(36);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  };

  useEffect(() => { getAllProjects().then(setProjects); }, []);

  const handleLinkCrawl = async (targetUrl?: string) => {
    if (!currentProject) return;
    const url = targetUrl || linkInput;
    if (!url) return;
    setIsFetchingLinks(true);
    addLog(`Đang cào dữ liệu từ: ${url}...`, 'info');
    try {
        const result = await fetchContentFromUrl(url);
        const chapterId = Math.random().toString(36);
        const newChapter: FileItem = { 
            id: chapterId, name: result.title, orderIndex: currentProject.chapters.length,
            content: result.content, translatedContent: null, status: FileStatus.IDLE, 
            retryCount: 0, originalCharCount: result.content.length, remainingRawCharCount: 0 
        };
        const updatedChapters = [...currentProject.chapters, newChapter];
        setProjects(prev => prev.map(p => p.id === currentProject.id ? { ...p, chapters: updatedChapters, lastCrawlUrl: result.nextUrl || url } : p));
        await saveProject({ ...currentProject, chapters: updatedChapters, lastCrawlUrl: result.nextUrl || url });
        addLog(`Thành công: ${result.title} (${result.content.length} ký tự)`, 'info');
        if (isProcessing) setProcessingQueue(prev => [...prev, chapterId]);
        setLinkInput(""); setShowLinkModal(false);
    } catch (e: any) {
        addLog(`Lỗi cào: ${e.message}`, 'err');
        addToast(e.message, 'error');
    } finally { setIsFetchingLinks(false); }
  };

  const startTranslation = async () => {
    if (!currentProject || !apiKey) return;
    const idleChapters = currentProject.chapters.filter(c => c.status === FileStatus.IDLE || c.status === FileStatus.ERROR);
    if (idleChapters.length === 0) {
        if (isAutoCrawlEnabled && currentProject.lastCrawlUrl) {
            handleLinkCrawl(currentProject.lastCrawlUrl);
            setIsProcessing(true);
        } else addToast("Không có chương mới", "info");
        return;
    }
    setIsProcessing(true);
    setProcessingQueue(idleChapters.map(c => c.id));
    addLog("Bắt đầu tiến trình dịch thuật...", 'info');
  };

  useEffect(() => {
    if (!isProcessing || processingQueue.length === 0 || !currentProject || !apiKey) {
        if (isProcessing && processingQueue.length === 0 && isAutoCrawlEnabled && currentProject?.lastCrawlUrl) {
            handleLinkCrawl(currentProject.lastCrawlUrl);
        }
        return;
    }

    const translateNext = async () => {
        const chapterId = processingQueue[0];
        const chapter = currentProject.chapters.find(c => c.id === chapterId);
        if (!chapter) return;

        setProjects(prev => prev.map(p => p.id === currentProject.id ? { ...p, chapters: p.chapters.map(c => c.id === chapterId ? { ...c, status: FileStatus.PROCESSING } : c) } : p));
        addLog(`Đang dịch: ${chapter.name}...`, 'info');

        try {
            const prompt = replacePromptVariables(currentProject.promptTemplate, currentProject.info);
            const { results, model } = await translateBatch([chapter], prompt, currentProject.dictionary, currentProject.globalContext, MODEL_CONFIGS.map(m=>m.id), apiKey);

            const translated = results.get(chapterId);
            setProjects(prev => prev.map(p => p.id === currentProject.id ? { ...p, chapters: p.chapters.map(c => c.id === chapterId ? { ...c, status: FileStatus.COMPLETED, translatedContent: translated || "", usedModel: model } : c) } : p));
            addLog(`Xong: ${chapter.name} [Model: ${model}]`, 'info');
        } catch (e: any) {
            setProjects(prev => prev.map(p => p.id === currentProject.id ? { ...p, chapters: p.chapters.map(c => c.id === chapterId ? { ...c, status: FileStatus.ERROR } : c) } : p));
            addLog(`Lỗi dịch: ${chapter.name} - ${e.message}`, 'err');
        } finally {
            setProcessingQueue(prev => prev.slice(1));
        }
    };
    translateNext();
  }, [isProcessing, processingQueue]);

  const sortedChapters = useMemo(() => currentProject ? [...currentProject.chapters].sort((a,b)=>a.orderIndex - b.orderIndex) : [], [currentProject]);

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 font-sans overflow-hidden">
