        <div className="flex-1 flex flex-col relative">
            <header className="h-16 border-b border-white/10 flex items-center justify-between px-8 bg-slate-900/50 backdrop-blur-xl z-20">
                <div className="flex items-center gap-4">
                    <Book className="w-6 h-6 text-indigo-400" />
                    <h1 className="font-bold tracking-tight">{currentProject?.info.title || "NovelPro Senior"}</h1>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setShowConsole(!showConsole)} className={`p-2 rounded-lg transition-colors ${showConsole ? 'bg-indigo-500 text-white' : 'hover:bg-white/10'}`}><Terminal className="w-5 h-5" /></button>
                    <button onClick={startTranslation} disabled={isProcessing} className="bg-indigo-600 hover:bg-indigo-700 px-6 py-2 rounded-xl font-bold text-sm shadow-lg shadow-indigo-500/20 flex items-center gap-2">
                        {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        {isProcessing ? "Đang xử lý..." : "Dịch tất cả"}
                    </button>
                </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                {currentProject ? (
                    <div className="max-w-6xl mx-auto">
                        <div className="flex gap-4 mb-8">
                            <button onClick={() => setShowLinkModal(true)} className="bg-white/5 border border-white/10 p-4 rounded-2xl flex items-center gap-3 hover:bg-white/10 transition-all font-bold"><Link2 className="w-5 h-5 text-amber-400" />Cào từ Link</button>
                            <button onClick={() => setShowContextSetup(true)} className="bg-white/5 border border-white/10 p-4 rounded-2xl flex items-center gap-3 hover:bg-white/10 transition-all font-bold"><Brain className="w-5 h-5 text-indigo-400" />Bối cảnh & Từ điển</button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                            {sortedChapters.map(ch => (
                                <div key={ch.id} className="bg-slate-800/50 border border-white/5 p-5 rounded-2xl group relative hover:border-indigo-500/50 transition-all">
                                    <div className="flex justify-between items-start mb-4">
                                        <span className={`text-[10px] font-bold px-2 py-1 rounded-md uppercase tracking-wider ${ch.status === 'COMPLETED' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-slate-700 text-slate-400'}`}>
                                            {ch.status}
                                        </span>
                                        <button onClick={() => setViewingRawId(ch.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-white/10 rounded-lg transition-all"><ScrollText className="w-4 h-4" /></button>
                                    </div>
                                    <h3 className="font-bold truncate text-slate-200">{ch.name}</h3>
                                    <p className="text-[10px] text-slate-500 mt-1 uppercase font-bold">{ch.originalCharCount} ký tự raw</p>
                                </div>
