                )}
            </div>

            {/* Live Console Drawer */}
            {showConsole && (
                <div className="absolute right-8 bottom-8 w-96 h-96 bg-black/90 backdrop-blur-2xl border border-white/10 rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in slide-in-from-bottom-4 duration-300 z-50">
                    <div className="p-4 border-b border-white/5 flex items-center justify-between bg-white/5">
                        <div className="flex items-center gap-2"><Activity className="w-4 h-4 text-indigo-400" /><span className="text-xs font-bold uppercase tracking-widest">Live Monitor</span></div>
                        <button onClick={() => setShowConsole(false)}><X className="w-4 h-4" /></button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-2 font-mono text-[11px] custom-scrollbar">
                        {logs.length === 0 && <p className="opacity-30 italic">Đang chờ sự kiện...</p>}
